    if market_key in CRICKET_PROP_MARKETS:
        required = list(dict.fromkeys(required + CRICKET_PLAYER_PROP_INPUTS))
    missing = []
    for field in required:
        if _cricket_value_missing(field, input_stats, payload):
            missing.append(field)
    return missing


