def normalize_sport_inputs_for_model(
    sport: Any,
    market: Any,
    selection: Any,
    input_stats: Any,
    ticket: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    raw_input_stats, input_stats_flags = _normalize_input_stats(input_stats)
    payload = dict(ticket or {})
    sport_alias_resolved = normalize_sport_key(str(sport or payload.get("sport") or ""))
    effective_market = market or payload.get("market") or raw_input_stats.get("market") or raw_input_stats.get("market_name")
    before_missing = _missing_inputs_for_sport(sport_alias_resolved, effective_market, raw_input_stats, payload)
    normalized = _normalize_generic_betting_aliases(
        raw_input_stats,
        market=effective_market,
        selection=selection or payload.get("selection"),
        ticket=payload,
    )

    normalizer_used = "generic_betting_alias_normalizer"
    if sport_alias_resolved == "basketball_nba":
        normalized = _normalize_nba_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "nba_input_normalizer"
    elif sport_alias_resolved == "basketball_wnba":
        normalized = _normalize_wnba_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "wnba_input_normalizer"
    elif sport_alias_resolved == "basketball_ncaab":
        normalized = _normalize_mens_college_basketball_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "mens_college_basketball_input_normalizer"
    elif sport_alias_resolved == "basketball_ncaawb":
        normalized = _normalize_womens_college_basketball_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "womens_college_basketball_input_normalizer"
    elif sport_alias_resolved == "americanfootball_nfl":
        normalized = _normalize_nfl_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "nfl_input_normalizer"
    elif sport_alias_resolved == "americanfootball_ncaaf":
        normalized = _normalize_college_football_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "college_football_input_normalizer"
    elif sport_alias_resolved == "baseball_mlb":
        normalized = _normalize_mlb_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "mlb_input_normalizer"
    elif sport_alias_resolved == "soccer":
        normalized = _normalize_soccer_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "soccer_input_normalizer"
    elif sport_alias_resolved == "rugby":
        normalized = _normalize_rugby_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "rugby_input_normalizer"
    elif sport_alias_resolved == "lacrosse":
        normalized = _normalize_lacrosse_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "lacrosse_input_normalizer"
    elif sport_alias_resolved == "table_tennis":
        normalized = _normalize_table_tennis_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "table_tennis_input_normalizer"
    elif sport_alias_resolved == "volleyball":
        normalized = _normalize_volleyball_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "volleyball_input_normalizer"
    elif sport_alias_resolved == "afl":
        normalized = _normalize_afl_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "afl_input_normalizer"
    elif sport_alias_resolved == "icehockey_nhl":
        normalized = _normalize_nhl_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "nhl_input_normalizer"
    elif sport_alias_resolved == "tennis":
        normalized = _normalize_tennis_input_aliases(normalized)
        normalizer_used = "tennis_input_normalizer"
    elif sport_alias_resolved in {"mma_mixed_martial_arts", "boxing"}:
        normalized = _normalize_combat_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "combat_input_normalizer"
    elif sport_alias_resolved == "golf":
        normalized = _normalize_golf_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "golf_input_normalizer"
    elif sport_alias_resolved == "formula1":
        normalized = _normalize_f1_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "f1_input_normalizer"
    elif sport_alias_resolved == "formula_e":
        normalized = _normalize_formula_e_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "formula_e_input_normalizer"
    elif sport_alias_resolved == "nascar":
        normalized = _normalize_nascar_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "nascar_input_normalizer"
    elif sport_alias_resolved == "indycar":
        normalized = _normalize_indycar_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "indycar_input_normalizer"
    elif sport_alias_resolved == "motogp":
        normalized = _normalize_motogp_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "motogp_input_normalizer"
    elif sport_alias_resolved == "cricket":
        normalized = _normalize_cricket_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "cricket_input_normalizer"
    elif sport_alias_resolved == "cs2":
        normalized = _normalize_cs2_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "cs2_input_normalizer"
    elif sport_alias_resolved == "valorant":
        normalized = _normalize_valorant_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "valorant_input_normalizer"
    elif sport_alias_resolved == "league_of_legends":
        normalized = _normalize_lol_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "league_of_legends_input_normalizer"
    elif sport_alias_resolved == "dota2":
        normalized = _normalize_dota2_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "dota2_input_normalizer"
    elif sport_alias_resolved == "call_of_duty":
        normalized = _normalize_cod_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "call_of_duty_input_normalizer"
    elif sport_alias_resolved == "overwatch":
        normalized = _normalize_overwatch_input_aliases(normalized, payload, sport_alias_resolved)
        normalizer_used = "overwatch_input_normalizer"

    after_market = market or payload.get("market") or normalized.get("market")
    after_missing = _missing_inputs_for_sport(sport_alias_resolved, after_market, normalized, payload)
    diagnostics = {
        "raw_input_keys": sorted(raw_input_stats.keys()),
        "normalized_input_keys": sorted(normalized.keys()),
        "missing_inputs_before_normalization": list(dict.fromkeys(before_missing)),
        "missing_inputs_after_normalization": list(dict.fromkeys(after_missing)),
        "sport_alias_resolved": sport_alias_resolved,
        "normalizer_used": normalizer_used,
        "input_stats_flags": input_stats_flags,
    }
    return {
        "input_stats": normalized,
        "diagnostics": diagnostics,
        **diagnostics,
    }


def _nfl_thresholds(risk_profile: Any) -> tuple[float, float]:
    profile = str(risk_profile or "moderate").strip().lower()
    if profile == "standard":
        profile = "moderate"
    if profile == "aggressive":
        return 1.5, 60
    if profile == "conservative":
        return 3.0, 75
    return 2.0, 65


def _logistic_probability(value: float, scale: float) -> float:
    return max(0.03, min(0.97, 1 / (1 + 2.718281828 ** (-(value / scale)))))


def american_odds_to_implied_probability(odds: Optional[float]) -> Optional[float]:
    return implied_probability_from_american(odds) if odds is not None else None


def negative_binomial_pmf(k: int, mean: float, dispersion: float = 8.0) -> float:
    if k < 0:
        return 0.0
    mean = max(0.05, float(mean))
    dispersion = max(0.5, float(dispersion or 8.0))
    p = dispersion / (dispersion + mean)
    log_coeff = math.lgamma(k + dispersion) - math.lgamma(dispersion) - math.lgamma(k + 1)
    return math.exp(log_coeff + dispersion * math.log(p) + k * math.log(1 - p))


def negative_binomial_cdf(k: int, mean: float, dispersion: float = 8.0) -> float:
    if k < 0:
        return 0.0
    return min(1.0, sum(negative_binomial_pmf(i, mean, dispersion) for i in range(k + 1)))


def estimate_run_distribution(mean_runs: float, dispersion: float = 8.0, max_runs: int = 20) -> list[float]:
    probabilities = [negative_binomial_pmf(i, mean_runs, dispersion) for i in range(max_runs)]
    probabilities.append(max(0.0, 1.0 - sum(probabilities)))
    total = sum(probabilities) or 1.0
    return [p / total for p in probabilities]


def estimate_moneyline_probability_from_runs(team_dist: list[float], opponent_dist: list[float]) -> float:
    win = 0.0
    tie = 0.0
    for team_runs, team_prob in enumerate(team_dist):
        for opponent_runs, opponent_prob in enumerate(opponent_dist):
            probability = team_prob * opponent_prob
            if team_runs > opponent_runs:
                win += probability
            elif team_runs == opponent_runs:
                tie += probability
    return max(0.03, min(0.97, win + tie * 0.5))


def estimate_runline_cover_probability(team_dist: list[float], opponent_dist: list[float], line: float) -> float:
    cover = 0.0
    for team_runs, team_prob in enumerate(team_dist):
        for opponent_runs, opponent_prob in enumerate(opponent_dist):
            if (team_runs - opponent_runs) + line > 0:
                cover += team_prob * opponent_prob
    return max(0.03, min(0.97, cover))


def estimate_total_probability(team_dist: list[float], opponent_dist: list[float], total_line: float, selection: Any) -> float:
    over_probability = 0.0
    under_probability = 0.0
    push_probability = 0.0
    for team_runs, team_prob in enumerate(team_dist):
        for opponent_runs, opponent_prob in enumerate(opponent_dist):
            total = team_runs + opponent_runs
            probability = team_prob * opponent_prob
            if total > total_line:
                over_probability += probability
            elif total < total_line:
                under_probability += probability
            else:
                push_probability += probability
    probability = under_probability if "under" in str(selection or "").lower() else over_probability
    return max(0.03, min(0.97, probability + push_probability * 0.5))


def estimate_team_total_probability(team_dist: list[float], team_total_line: float, selection: Any) -> float:
    over_probability = 0.0
    under_probability = 0.0
    push_probability = 0.0
    for runs, probability in enumerate(team_dist):
        if runs > team_total_line:
            over_probability += probability
        elif runs < team_total_line:
            under_probability += probability
        else:
            push_probability += probability
    probability = under_probability if "under" in str(selection or "").lower() else over_probability
    return max(0.03, min(0.97, probability + push_probability * 0.5))


def poisson_pmf(k: int, lam: float) -> float:
    if k < 0:
        return 0.0
    lam = max(0.05, min(5.5, float(lam or 0.05)))
    return math.exp(-lam + k * math.log(lam) - math.lgamma(k + 1))


def build_soccer_score_matrix(team_lambda: float, opponent_lambda: float, max_goals: int = 8) -> list[list[float]]:
    team_probs = [poisson_pmf(i, team_lambda) for i in range(max_goals)]
    opponent_probs = [poisson_pmf(i, opponent_lambda) for i in range(max_goals)]
    team_probs.append(max(0.0, 1.0 - sum(team_probs)))
    opponent_probs.append(max(0.0, 1.0 - sum(opponent_probs)))
    matrix = [[team_probs[i] * opponent_probs[j] for j in range(max_goals + 1)] for i in range(max_goals + 1)]
    total = sum(sum(row) for row in matrix) or 1.0
    return [[cell / total for cell in row] for row in matrix]


def _normalize_score_matrix(matrix: list[list[float]]) -> list[list[float]]:
    total = sum(sum(row) for row in matrix) or 1.0
    return [[max(0.0, cell) / total for cell in row] for row in matrix]


def apply_dixon_coles_adjustment(matrix: list[list[float]], team_lambda: float, opponent_lambda: float, rho: float = -0.08) -> list[list[float]]:
    adjusted = [row[:] for row in matrix]
    rho = max(-0.18, min(0.12, float(rho or -0.08)))
    corrections = {
        (0, 0): 1 - (team_lambda * opponent_lambda * rho),
        (1, 0): 1 + (team_lambda * rho),
        (0, 1): 1 + (opponent_lambda * rho),
        (1, 1): 1 - rho,
    }
    for (team_goals, opponent_goals), factor in corrections.items():
        adjusted[team_goals][opponent_goals] *= max(0.5, min(1.5, factor))
    return _normalize_score_matrix(adjusted)


def apply_bivariate_poisson_adjustment(matrix: list[list[float]], shared_intensity: float = 0.05) -> list[list[float]]:
    adjusted = [row[:] for row in matrix]
    shared_intensity = max(0.0, min(0.18, float(shared_intensity or 0.0)))
    if shared_intensity <= 0:
        return adjusted
    for team_goals, row in enumerate(adjusted):
        for opponent_goals, _ in enumerate(row):
            if team_goals == opponent_goals:
                adjusted[team_goals][opponent_goals] *= 1 + shared_intensity
            elif abs(team_goals - opponent_goals) >= 3:
                adjusted[team_goals][opponent_goals] *= 1 - shared_intensity * 0.35
    return _normalize_score_matrix(adjusted)


def estimate_three_way_probability(matrix: list[list[float]], selection: Any, team: Any, opponent: Any) -> float:
    team_win = sum(matrix[i][j] for i in range(len(matrix)) for j in range(len(matrix[i])) if i > j)
    draw = sum(matrix[i][i] for i in range(len(matrix)))
    opponent_win = max(0.0, 1.0 - team_win - draw)
    text = str(selection or "").strip().lower()
    team_text = str(team or "").strip().lower()
    opponent_text = str(opponent or "").strip().lower()
    if text in {"draw", "x"}:
        return draw
    if text in {"away", "opponent", "2"} or (opponent_text and opponent_text in text):
        return opponent_win
    return team_win if text in {"home", "team", "1"} or (team_text and team_text in text) else team_win


def estimate_draw_no_bet_probability(matrix: list[list[float]], selection: Any, team: Any, opponent: Any) -> float:
    team_win = sum(matrix[i][j] for i in range(len(matrix)) for j in range(len(matrix[i])) if i > j)
    opponent_win = sum(matrix[i][j] for i in range(len(matrix)) for j in range(len(matrix[i])) if i < j)
    denominator = max(0.01, team_win + opponent_win)
    text = str(selection or "").strip().lower()
    opponent_text = str(opponent or "").strip().lower()
    return opponent_win / denominator if opponent_text and opponent_text in text else team_win / denominator


def estimate_double_chance_probability(matrix: list[list[float]], selection: Any, team: Any, opponent: Any) -> float:
    team_win = sum(matrix[i][j] for i in range(len(matrix)) for j in range(len(matrix[i])) if i > j)
    draw = sum(matrix[i][i] for i in range(len(matrix)))
    opponent_win = max(0.0, 1.0 - team_win - draw)
    text = str(selection or "").strip().lower().replace(" ", "_")
    if text in {"1x", "team_or_draw"} or str(team or "").lower() in text and "draw" in text:
        return team_win + draw
    if text in {"x2", "opponent_or_draw"} or str(opponent or "").lower() in text and "draw" in text:
        return opponent_win + draw
    if text in {"12", "team_or_opponent", "no_draw"}:
        return team_win + opponent_win
    return team_win + draw


def estimate_handicap_probability(matrix: list[list[float]], line: float) -> float:
    cover = 0.0
    push = 0.0
    for team_goals, row in enumerate(matrix):
        for opponent_goals, probability in enumerate(row):
            result = (team_goals - opponent_goals) + line
            if result > 0:
                cover += probability
            elif result == 0:
                push += probability
    return max(0.03, min(0.97, cover + push * 0.5))


def estimate_total_probability_from_score_matrix(matrix: list[list[float]], total_line: float, selection: Any) -> float:
    over = 0.0
    under = 0.0
    push = 0.0
    for team_goals, row in enumerate(matrix):
        for opponent_goals, probability in enumerate(row):
            total = team_goals + opponent_goals
            if total > total_line:
                over += probability
            elif total < total_line:
                under += probability
            else:
                push += probability
    probability = under if "under" in str(selection or "").lower() else over
    return max(0.03, min(0.97, probability + push * 0.5))


def estimate_team_total_probability_from_score_matrix(matrix: list[list[float]], team_total_line: float, selection: Any) -> float:
    over = 0.0
    under = 0.0
    push = 0.0
    for team_goals, row in enumerate(matrix):
        probability = sum(row)
        if team_goals > team_total_line:
            over += probability
        elif team_goals < team_total_line:
            under += probability
        else:
            push += probability
    probability = under if "under" in str(selection or "").lower() else over
    return max(0.03, min(0.97, probability + push * 0.5))


def estimate_btts_probability(matrix: list[list[float]], selection: Any) -> float:
    yes = sum(matrix[i][j] for i in range(1, len(matrix)) for j in range(1, len(matrix[i])))
    return max(0.03, min(0.97, 1 - yes if "no" in str(selection or "").lower() else yes))


def estimate_correct_score_probability(matrix: list[list[float]], correct_score_selection: Any) -> float:
    numbers = [int(part) for part in re.findall(r"\d+", str(correct_score_selection or ""))[:2]]
    if len(numbers) != 2:
        return 0.03
    team_goals, opponent_goals = numbers
    if team_goals >= len(matrix) or opponent_goals >= len(matrix[0]):
        return 0.03
    return max(0.03, min(0.97, matrix[team_goals][opponent_goals]))


def estimate_first_half_lambdas(team_lambda: float, opponent_lambda: float, share: Optional[float] = None) -> tuple[float, float]:
    first_half_share = max(0.38, min(0.50, float(share) if share is not None else 0.45))
    return team_lambda * first_half_share, opponent_lambda * first_half_share


def calibrate_soccer_probability(
    *,
    raw_probability: float,
    market_anchor_probability: float,
    market_anchor_is_no_vig: bool,
    projected_goal_differential: float,
    market_key: str,
    input_confidence_hint: float,
) -> dict[str, Any]:
    flags: list[str] = []
    if raw_probability >= 0.90 or raw_probability <= 0.05:
        flags.append("raw probability extreme")
    anchor_weight = 0.25 if market_anchor_is_no_vig else 0.05
    calibrated = (raw_probability * (1 - anchor_weight)) + (market_anchor_probability * anchor_weight)
    if abs(calibrated - raw_probability) >= 0.025:
        flags.append("probability calibration applied")

    abs_diff = abs(projected_goal_differential)
    if market_key in {"draw_no_bet", "double_chance", "both_teams_to_score"}:
        lower_cap, upper_cap = 0.18, 0.86
    elif market_key in {"correct_score", "first_goal_scorer"}:
        lower_cap, upper_cap = 0.03, 0.32
    elif abs_diff >= 1.0 and input_confidence_hint >= 75:
        lower_cap, upper_cap = 0.12, 0.75
    elif abs_diff >= 0.60:
        lower_cap, upper_cap = 0.15, 0.70
    elif abs_diff >= 0.25:
        lower_cap, upper_cap = 0.20, 0.60
    else:
        lower_cap, upper_cap = 0.25, 0.50
    final_probability = max(lower_cap, min(upper_cap, calibrated))
    if final_probability != calibrated:
        flags.append("probability capped by projected goal differential")
        flags.append("probability calibration applied")
    return {
        "raw_model_probability": raw_probability,
        "calibrated_model_probability": calibrated,
        "final_probability": final_probability,
        "market_anchor_probability": market_anchor_probability,
        "probability_calibration_applied": bool(flags),
        "probability_sanity_flags": list(dict.fromkeys(flags)),
        "probability_cap_reason": f"projected goal differential {round(projected_goal_differential, 2)} goals",
    }


def build_nhl_score_matrix(team_lambda: float, opponent_lambda: float, max_goals: int = 9) -> list[list[float]]:
    team_probs = [poisson_pmf(i, max(0.10, min(6.5, team_lambda))) for i in range(max_goals)]
    opponent_probs = [poisson_pmf(i, max(0.10, min(6.5, opponent_lambda))) for i in range(max_goals)]
    team_probs.append(max(0.0, 1.0 - sum(team_probs)))
    opponent_probs.append(max(0.0, 1.0 - sum(opponent_probs)))
    return _normalize_score_matrix([[team_probs[i] * opponent_probs[j] for j in range(max_goals + 1)] for i in range(max_goals + 1)])


def apply_bivariate_hockey_adjustment(matrix: list[list[float]], shared_intensity: float = 0.04) -> list[list[float]]:
    adjusted = [row[:] for row in matrix]
    shared_intensity = max(0.0, min(0.14, float(shared_intensity or 0.0)))
    if shared_intensity <= 0:
        return adjusted
    for team_goals, row in enumerate(adjusted):
        for opponent_goals, _ in enumerate(row):
            if team_goals == opponent_goals:
                adjusted[team_goals][opponent_goals] *= 1 + shared_intensity
            elif team_goals + opponent_goals >= 7:
                adjusted[team_goals][opponent_goals] *= 1 + shared_intensity * 0.25
            elif abs(team_goals - opponent_goals) >= 4:
                adjusted[team_goals][opponent_goals] *= 1 - shared_intensity * 0.30
    return _normalize_score_matrix(adjusted)


def estimate_nhl_three_way_probability(matrix: list[list[float]], selection: Any, team: Any, opponent: Any) -> float:
    return estimate_three_way_probability(matrix, selection, team, opponent)


def estimate_nhl_regulation_moneyline_probability(matrix: list[list[float]], selection: Any, team: Any, opponent: Any) -> float:
    return estimate_three_way_probability(matrix, selection, team, opponent)


def _nhl_matrix_parts(matrix: list[list[float]]) -> tuple[float, float, float]:
    team_win = sum(matrix[i][j] for i in range(len(matrix)) for j in range(len(matrix[i])) if i > j)
    draw = sum(matrix[i][i] for i in range(len(matrix)))
    opponent_win = max(0.0, 1.0 - team_win - draw)
    return team_win, draw, opponent_win


def estimate_nhl_moneyline_probability(matrix: list[list[float]], selection: Any, team: Any, opponent: Any, shootout_edge: float = 0.0) -> float:
    team_win, draw, opponent_win = _nhl_matrix_parts(matrix)
    text = str(selection or "").strip().lower()
    opponent_text = str(opponent or "").strip().lower()
    team_ot_share = max(0.42, min(0.58, 0.50 + shootout_edge))
    if opponent_text and opponent_text in text:
        return max(0.03, min(0.97, opponent_win + draw * (1 - team_ot_share)))
    return max(0.03, min(0.97, team_win + draw * team_ot_share))


def estimate_nhl_draw_no_bet_probability(matrix: list[list[float]], selection: Any, team: Any, opponent: Any) -> float:
    return estimate_draw_no_bet_probability(matrix, selection, team, opponent)


def estimate_nhl_puckline_probability(matrix: list[list[float]], line: float) -> float:
    return estimate_handicap_probability(matrix, line)


def estimate_nhl_total_probability_from_score_matrix(matrix: list[list[float]], total_line: float, selection: Any) -> float:
    return estimate_total_probability_from_score_matrix(matrix, total_line, selection)


def estimate_nhl_team_total_probability_from_score_matrix(matrix: list[list[float]], team_total_line: float, selection: Any) -> float:
    return estimate_team_total_probability_from_score_matrix(matrix, team_total_line, selection)


def estimate_nhl_period_lambdas(team_lambda: float, opponent_lambda: float, period: str, share: Optional[float] = None) -> tuple[float, float]:
    default_shares = {
        "first": 0.305,
        "second": 0.345,
        "third": 0.350,
    }
    share_value = max(0.24, min(0.42, float(share) if share is not None else default_shares.get(period, 0.33)))
    return team_lambda * share_value, opponent_lambda * share_value


def estimate_nhl_player_prop_probability(projection: float, prop_line: float) -> float:
    return _logistic_probability(projection - prop_line, max(0.55, abs(prop_line) * 0.25))


def calibrate_nhl_probability(
    *,
    raw_probability: float,
    market_anchor_probability: float,
    market_anchor_is_no_vig: bool,
    projected_goal_differential: float,
    market_key: str,
    input_confidence_hint: float,
    goalie_edge_quality: float,
) -> dict[str, Any]:
    flags: list[str] = []
    if raw_probability >= 0.88 or raw_probability <= 0.10:
        flags.append("raw probability extreme")
    anchor_weight = 0.25 if market_anchor_is_no_vig else 0.05
    calibrated = raw_probability * (1 - anchor_weight) + market_anchor_probability * anchor_weight
    if abs(calibrated - raw_probability) >= 0.025:
        flags.append("probability calibration applied")

    abs_diff = abs(projected_goal_differential)
    if market_key in {"three_way_moneyline", "regulation_moneyline"}:
        lower_cap, upper_cap = 0.14, 0.68
    elif market_key == "draw_no_bet":
        lower_cap, upper_cap = 0.22, 0.82
    elif market_key in {"puckline", "spread", "alternate_puckline", "total", "alternate_total", "team_total"}:
        lower_cap, upper_cap = 0.25, 0.76
    elif market_key in {"first_goal_scorer"}:
        lower_cap, upper_cap = 0.03, 0.32
    elif market_key in {"player_prop", "anytime_goal_scorer"}:
        lower_cap, upper_cap = 0.08, 0.78
    elif abs_diff >= 1.25 and input_confidence_hint >= 78 and goalie_edge_quality >= 0.4:
        lower_cap, upper_cap = 0.20, 0.82
    elif abs_diff >= 0.90:
        lower_cap, upper_cap = 0.30, 0.75
    elif abs_diff >= 0.50:
        lower_cap, upper_cap = 0.32, 0.70
    elif abs_diff >= 0.20:
        lower_cap, upper_cap = 0.38, 0.64
    else:
        lower_cap, upper_cap = 0.42, 0.58

    final_probability = max(lower_cap, min(upper_cap, calibrated))
    if final_probability != calibrated:
        flags.append("probability capped by projected goal differential")
        flags.append("probability calibration applied")
    return {
        "raw_model_probability": raw_probability,
        "calibrated_model_probability": calibrated,
        "final_probability": final_probability,
        "market_anchor_probability": market_anchor_probability,
        "probability_calibration_applied": bool(flags),
        "probability_sanity_flags": list(dict.fromkeys(flags)),
        "probability_cap_reason": f"projected goal differential {round(projected_goal_differential, 2)} goals",
    }


def tennis_logistic(value: float, scale: float = 1.0) -> float:
    return max(0.01, min(0.99, 1 / (1 + math.exp(-value / max(0.05, scale)))))


def estimate_tennis_base_strength(input_stats: dict[str, Any]) -> dict[str, float]:
    player_elo = _safe_float(input_stats.get("player_elo"), 1500) or 1500
    opponent_elo = _safe_float(input_stats.get("opponent_elo"), 1500) or 1500
    player_surface_elo = _safe_float(input_stats.get("player_surface_elo"), player_elo) or player_elo
    opponent_surface_elo = _safe_float(input_stats.get("opponent_surface_elo"), opponent_elo) or opponent_elo
    player_rank = _safe_float(input_stats.get("player_ranking"), 100) or 100
    opponent_rank = _safe_float(input_stats.get("opponent_ranking"), 100) or 100
    form_edge = (
        (_safe_float(input_stats.get("player_recent_form_wins"), 0) or 0)
        - (_safe_float(input_stats.get("player_recent_form_losses"), 0) or 0)
        - (_safe_float(input_stats.get("opponent_recent_form_wins"), 0) or 0)
        + (_safe_float(input_stats.get("opponent_recent_form_losses"), 0) or 0)
    ) * 4.0
    rank_edge = max(-55, min(55, (opponent_rank - player_rank) * 0.6))
    player_strength = player_elo * 0.45 + player_surface_elo * 0.45 + rank_edge + form_edge
    opponent_strength = opponent_elo * 0.45 + opponent_surface_elo * 0.45
    return {
        "player_strength_rating": round(player_strength, 2),
        "opponent_strength_rating": round(opponent_strength, 2),
        "player_surface_edge": round(player_surface_elo - opponent_surface_elo, 2),
    }


def estimate_tennis_serve_point_probability(input_stats: dict[str, Any], prefix: str) -> float:
    opponent_prefix = "opponent" if prefix == "player" else "player"
    first_in = (_safe_float(input_stats.get(f"{prefix}_first_serve_in_percent"), 62) or 62) / 100
    first_won = (_safe_float(input_stats.get(f"{prefix}_first_serve_points_won_percent"), 70) or 70) / 100
    second_won = (_safe_float(input_stats.get(f"{prefix}_second_serve_points_won_percent"), 52) or 52) / 100
    ace_rate = (_safe_float(input_stats.get(f"{prefix}_ace_rate"), 7) or 7) / 100
    df_rate = (_safe_float(input_stats.get(f"{prefix}_double_fault_rate"), 3) or 3) / 100
    opponent_return = (_safe_float(input_stats.get(f"{opponent_prefix}_return_points_won_percent"), 38) or 38) / 100
    point_probability = first_in * first_won + (1 - first_in) * second_won + ace_rate * 0.25 - df_rate * 0.35
    point_probability = point_probability * 0.86 + (1 - opponent_return) * 0.14
    return max(0.42, min(0.75, point_probability))


def estimate_tennis_hold_probability_from_points(point_probability: float) -> float:
    p = max(0.35, min(0.80, point_probability))
    q = 1 - p
    pre_deuce = p**4 * (1 + 4 * q + 10 * q**2)
    deuce = 20 * p**3 * q**3
    win_from_deuce = p * p / max(0.01, 1 - 2 * p * q)
    return max(0.45, min(0.95, pre_deuce + deuce * win_from_deuce))


def estimate_tennis_tiebreak_probability(player_serve_point: float, opponent_serve_point: float, input_stats: dict[str, Any]) -> float:
    base = 0.5 + (player_serve_point - opponent_serve_point) * 0.75
    tb_edge = ((_safe_float(input_stats.get("player_tiebreak_win_percent"), 50) or 50) - (_safe_float(input_stats.get("opponent_tiebreak_win_percent"), 50) or 50)) / 100
    return max(0.30, min(0.70, base + tb_edge * 0.12))


def estimate_tennis_set_probability(player_hold: float, opponent_hold: float, tiebreak_probability: float) -> float:
    service_edge = (player_hold - opponent_hold)
    raw = 0.5 + service_edge * 1.15 + (tiebreak_probability - 0.5) * 0.18
    return max(0.20, min(0.80, raw))


def estimate_tennis_match_probability(set_probability: float, best_of_sets: int) -> float:
    p = max(0.05, min(0.95, set_probability))
    if int(best_of_sets or 3) >= 5:
        return p**3 + 3 * p**3 * (1 - p) + 6 * p**3 * (1 - p) ** 2
    return p * p + 2 * p * p * (1 - p)


def estimate_tennis_set_score_distribution(set_probability: float, best_of_sets: int) -> dict[str, float]:
    p = max(0.05, min(0.95, set_probability))
    if int(best_of_sets or 3) >= 5:
        return {
            "3-0": p**3,
            "3-1": 3 * p**3 * (1 - p),
            "3-2": 6 * p**3 * (1 - p) ** 2,
            "0-3": (1 - p) ** 3,
            "1-3": 3 * (1 - p) ** 3 * p,
            "2-3": 6 * (1 - p) ** 3 * p**2,
        }
    return {
        "2-0": p**2,
        "2-1": 2 * p**2 * (1 - p),
        "0-2": (1 - p) ** 2,
        "1-2": 2 * (1 - p) ** 2 * p,
    }


def estimate_tennis_game_margin_distribution(match_probability: float, set_probability: float, best_of_sets: int) -> dict[str, float]:
    expected_sets = 3.0 if int(best_of_sets or 3) >= 5 else 2.35
    if abs(set_probability - 0.5) < 0.045:
        expected_sets += 0.35
    mean_margin = (match_probability - 0.5) * (10 if int(best_of_sets or 3) >= 5 else 7)
    expected_total = expected_sets * (9.6 + (1 - abs(set_probability - 0.5)) * 1.8)
    return {"mean_margin": mean_margin, "expected_total_games": expected_total, "volatility": 5.5 if int(best_of_sets or 3) >= 5 else 4.0}


def estimate_tennis_total_games_probability(total_line: float, selection: Any, game_distribution: dict[str, float]) -> float:
    raw = tennis_logistic(game_distribution["expected_total_games"] - total_line, game_distribution["volatility"])
    return 1 - raw if "under" in str(selection or "").lower() else raw


def estimate_tennis_first_set_total_probability(total_line: float, selection: Any, set_probability: float) -> float:
    expected = 9.2 + (1 - abs(set_probability - 0.5)) * 2.3
    raw = tennis_logistic(expected - total_line, 2.2)
    return 1 - raw if "under" in str(selection or "").lower() else raw


def estimate_tennis_correct_score_probability(distribution: dict[str, float], correct_score_selection: Any) -> float:
    text = str(correct_score_selection or "").strip()
    return max(0.03, min(0.65, distribution.get(text, 0.03)))


def estimate_tennis_player_prop_probability(projection: float, prop_line: float) -> float:
    return max(0.03, min(0.82, tennis_logistic(projection - prop_line, max(0.55, abs(prop_line) * 0.22))))


def calibrate_tennis_probability(
    *,
    raw_probability: float,
    market_anchor_probability: float,
    market_anchor_is_no_vig: bool,
    elo_gap: float,
    surface_edge: float,
    market_key: str,
    input_confidence_hint: float,
) -> dict[str, Any]:
    flags: list[str] = []
    if raw_probability >= 0.88 or raw_probability <= 0.12:
        flags.append("raw probability extreme")
    anchor_weight = 0.25 if market_anchor_is_no_vig else 0.05
    calibrated = raw_probability * (1 - anchor_weight) + market_anchor_probability * anchor_weight
    if abs(calibrated - raw_probability) >= 0.025:
        flags.append("probability calibration applied")
    edge_size = abs(elo_gap) * 0.75 + abs(surface_edge) * 0.25
    if market_key in {"correct_score"}:
        lower_cap, upper_cap = 0.03, 0.45
    elif market_key in {"first_set_moneyline", "first_set_total_games", "player_prop", "aces", "double_faults", "break_points", "service_games_won", "return_games_won"}:
        lower_cap, upper_cap = 0.14, 0.75
    elif edge_size >= 220 and input_confidence_hint >= 78:
        lower_cap, upper_cap = 0.12, 0.88
    elif edge_size >= 140:
        lower_cap, upper_cap = 0.18, 0.82
    elif edge_size >= 70:
        lower_cap, upper_cap = 0.22, 0.78
    else:
        lower_cap, upper_cap = 0.25, 0.75
    final_probability = max(lower_cap, min(upper_cap, calibrated))
    if final_probability != calibrated:
        flags.append("probability capped by tennis strength edge")
        flags.append("probability calibration applied")
    return {
        "raw_model_probability": raw_probability,
        "calibrated_model_probability": calibrated,
        "final_probability": final_probability,
        "market_anchor_probability": market_anchor_probability,
        "probability_calibration_applied": bool(flags),
        "probability_sanity_flags": list(dict.fromkeys(flags)),
        "probability_cap_reason": f"elo gap {round(elo_gap, 1)}, surface edge {round(surface_edge, 1)}",
    }


def calibrate_mlb_probability(
    *,
    raw_probability: float,
    market_anchor_probability: float,
    market_anchor_is_no_vig: bool,
    projected_run_differential: float,
    input_confidence_hint: float,
) -> dict[str, Any]:
    flags: list[str] = []
    if raw_probability >= 0.88 or raw_probability <= 0.12:
        flags.append("raw probability extreme")

    abs_diff = abs(projected_run_differential)
    high_quality_extreme = abs_diff >= 2.0 and input_confidence_hint >= 78
    if (raw_probability >= 0.88 or raw_probability <= 0.12) and not high_quality_extreme:
        model_floor = 0.62 if raw_probability >= 0.88 else 0.38
        anchor_weight = 0.85 if market_anchor_is_no_vig else 0.05
        calibrated = (model_floor * (1 - anchor_weight)) + (market_anchor_probability * anchor_weight)
    else:
        anchor_weight = 0.25 if market_anchor_is_no_vig else 0.05
        calibrated = (raw_probability * (1 - anchor_weight)) + (market_anchor_probability * anchor_weight)
    if abs(calibrated - raw_probability) >= 0.025:
        flags.append("probability calibration applied")

    if high_quality_extreme:
        lower_cap, upper_cap = 0.18, 0.86
    elif abs_diff >= 1.5:
        lower_cap, upper_cap = 0.22, 0.78
    elif abs_diff >= 1.0:
        lower_cap, upper_cap = 0.28, 0.72
    elif abs_diff >= 0.5:
        lower_cap, upper_cap = 0.35, 0.65
    else:
        lower_cap, upper_cap = 0.42, 0.58

    final_probability = max(lower_cap, min(upper_cap, calibrated))
    if final_probability != calibrated:
        flags.append("probability capped by projected run differential")
        flags.append("probability calibration applied")
    return {
        "raw_model_probability": raw_probability,
        "calibrated_model_probability": calibrated,
        "final_probability": final_probability,
        "market_anchor_probability": market_anchor_probability,
        "probability_calibration_applied": bool(flags),
        "probability_sanity_flags": list(dict.fromkeys(flags)),
        "probability_cap_reason": f"projected run differential {round(projected_run_differential, 2)} runs",
    }


def calculate_edge_percent(true_probability: Optional[float], implied_probability: Optional[float]) -> Optional[float]:
    return edge_percentage(true_probability, implied_probability) if true_probability is not None and implied_probability is not None else None


def calculate_confidence(base: float, *adjustments: float) -> float:
    return max(1, min(95, round(base + sum(adjustments), 2)))


def calculate_suggested_stake(
    *,
    bankroll: float,
    american_odds: Optional[float],
    true_probability: Optional[float],
    risk_profile: str,
    confidence: float,
) -> float:
    if american_odds is None or true_probability is None:
        return 0.0
    return suggested_stake_with_risk_controls(
        bankroll=bankroll,
        american_odds=american_odds,
        true_probability=true_probability,
        risk_profile="standard" if str(risk_profile or "").lower() == "moderate" else risk_profile,
        confidence_0_100=confidence,
    )


def _combat_pct(value: Any, default: float = 0.0) -> float:
    number = _safe_float(value, default)
    if number is None:
        return default
    return number / 100 if number > 1 else number


def _combat_market_probability(
    *,
    market: str,
    selection: Any,
    fighter_win_probability: float,
    opponent_win_probability: float,
    ko_tko_probability: float,
    submission_probability: float,
    decision_probability: float,
    goes_distance_probability: float,
    scheduled_rounds: float,
    line: Optional[float],
) -> float:
    market_key = _normal_market_key(market)
    selection_text = str(selection or "").strip().lower()
    does_not_go_distance = 1 - goes_distance_probability
    if market_key in {"moneyline", "match_winner"}:
        return fighter_win_probability
    if market_key in {"method_of_victory", "fighter_by_ko_tko"}:
        return ko_tko_probability
    if market_key == "fighter_by_submission":
        return submission_probability
    if market_key == "fighter_by_decision":
        return decision_probability
    if market_key == "opponent_by_ko_tko":
        return opponent_win_probability * max(0.05, min(0.80, ko_tko_probability / max(fighter_win_probability, 0.01) * 0.85))
    if market_key == "opponent_by_submission":
        return opponent_win_probability * max(0.03, min(0.65, submission_probability / max(fighter_win_probability, 0.01) * 0.85))
    if market_key == "opponent_by_decision":
        return opponent_win_probability * max(0.08, min(0.75, decision_probability / max(fighter_win_probability, 0.01) * 0.90))
    if market_key == "fight_goes_distance":
        return goes_distance_probability
    if market_key == "fight_does_not_go_distance":
        return does_not_go_distance
    if market_key == "over_rounds":
        round_line = line if line is not None else scheduled_rounds - 0.5
        round_share = max(0.15, min(0.95, round_line / max(scheduled_rounds, 1)))
        return max(0.08, min(0.88, goes_distance_probability + (1 - goes_distance_probability) * (1 - round_share) * 0.55))
    if market_key == "under_rounds":
        round_line = line if line is not None else scheduled_rounds - 0.5
        round_share = max(0.15, min(0.95, round_line / max(scheduled_rounds, 1)))
        over_probability = max(0.08, min(0.88, goes_distance_probability + (1 - goes_distance_probability) * (1 - round_share) * 0.55))
        return 1 - over_probability
    if market_key == "round_group":
        return max(0.12, min(0.55, does_not_go_distance * 0.50))
    if market_key == "exact_round":
        return max(0.04, min(0.25, does_not_go_distance / max(scheduled_rounds, 1)))
    if market_key == "double_chance":
        if "ko" in selection_text or "tko" in selection_text:
            return max(0.10, min(0.75, ko_tko_probability + submission_probability * 0.45))
        return max(0.10, min(0.75, ko_tko_probability + decision_probability * 0.45))
    if market_key == "knockdown_prop":
        return max(0.12, min(0.72, ko_tko_probability + does_not_go_distance * 0.18))
    if market_key == "takedown_prop":
        return max(0.12, min(0.72, submission_probability + 0.22))
    if market_key == "significant_strikes_prop":
        return max(0.15, min(0.78, goes_distance_probability + 0.10))
    if market_key == "submission_attempt_prop":
        return max(0.10, min(0.70, submission_probability + 0.18))
    return fighter_win_probability


def _estimate_combat_finish_model(
    *,
    sport: str,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _combat_full_inputs_missing(input_stats, payload) + _combat_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    fighter_elo = _safe_float(input_stats.get("fighter_elo"), 1500) or 1500
    opponent_elo = _safe_float(input_stats.get("opponent_elo"), 1500) or 1500
    fighter_recent = _combat_pct(input_stats.get("fighter_recent_win_percent"), 0.50)
    opponent_recent = _combat_pct(input_stats.get("opponent_recent_win_percent"), 0.50)
    fighter_finish = _combat_pct(input_stats.get("fighter_finish_rate"), 0.45)
    opponent_finish = _combat_pct(input_stats.get("opponent_finish_rate"), 0.45)
    fighter_ko = _combat_pct(input_stats.get("fighter_ko_tko_rate"), 0.25)
    opponent_ko = _combat_pct(input_stats.get("opponent_ko_tko_rate"), 0.25)
    fighter_sub = 0.0 if sport == "boxing" else _combat_pct(input_stats.get("fighter_submission_rate"), 0.15)
    opponent_sub = 0.0 if sport == "boxing" else _combat_pct(input_stats.get("opponent_submission_rate"), 0.15)
    fighter_decision = _combat_pct(input_stats.get("fighter_decision_rate"), 0.35)
    opponent_decision = _combat_pct(input_stats.get("opponent_decision_rate"), 0.35)

    striking_edge = (
        (_safe_float(input_stats.get("fighter_strikes_landed_per_min"), 0) or 0)
        - (_safe_float(input_stats.get("opponent_strikes_landed_per_min"), 0) or 0)
        - ((_safe_float(input_stats.get("fighter_strikes_absorbed_per_min"), 0) or 0) - (_safe_float(input_stats.get("opponent_strikes_absorbed_per_min"), 0) or 0)) * 0.55
        + ((_combat_pct(input_stats.get("fighter_striking_accuracy"), 0.45) - _combat_pct(input_stats.get("opponent_striking_accuracy"), 0.45)) * 6)
        + ((_combat_pct(input_stats.get("fighter_striking_defense"), 0.55) - _combat_pct(input_stats.get("opponent_striking_defense"), 0.55)) * 5)
    )
    grappling_edge = (
        ((_safe_float(input_stats.get("fighter_takedown_average"), 0) or 0) - (_safe_float(input_stats.get("opponent_takedown_average"), 0) or 0)) * 0.18
        + ((_combat_pct(input_stats.get("fighter_takedown_accuracy"), 0.35) - _combat_pct(input_stats.get("opponent_takedown_accuracy"), 0.35)) * 2.2)
        + ((_combat_pct(input_stats.get("fighter_takedown_defense"), 0.65) - _combat_pct(input_stats.get("opponent_takedown_defense"), 0.65)) * 2.0)
        + ((_safe_float(input_stats.get("fighter_submission_average"), 0) or 0) - (_safe_float(input_stats.get("opponent_submission_average"), 0) or 0)) * 0.18
    )
    if sport == "boxing":
        grappling_edge = 0
    age_edge = ((_safe_float(input_stats.get("opponent_age"), 30) or 30) - (_safe_float(input_stats.get("fighter_age"), 30) or 30)) * 0.018
    reach_edge = ((_safe_float(input_stats.get("fighter_reach"), 72) or 72) - (_safe_float(input_stats.get("opponent_reach"), 72) or 72)) * 0.018
    height_edge = ((_safe_float(input_stats.get("fighter_height"), 70) or 70) - (_safe_float(input_stats.get("opponent_height"), 70) or 70)) * 0.010
    rest_edge = ((_safe_float(input_stats.get("fighter_days_rest"), 90) or 90) - (_safe_float(input_stats.get("opponent_days_rest"), 90) or 90)) * 0.0008
    cardio_edge = ((_safe_float(input_stats.get("cardio_rating"), 70) or 70) - 70) * 0.006
    explicit_style_edge = ((_safe_float(input_stats.get("striking_advantage"), 0) or 0) + (_safe_float(input_stats.get("grappling_advantage"), 0) or 0)) * 0.01
    injury_penalty = -0.12 if str(input_stats.get("fighter_injury_status", "")).lower() not in {"healthy", "clear", "none"} else 0
    opponent_injury_bonus = 0.08 if str(input_stats.get("opponent_injury_status", "")).lower() not in {"healthy", "clear", "none"} else 0

    model_score = (
        (fighter_elo - opponent_elo) / 450
        + (fighter_recent - opponent_recent) * 0.55
        + striking_edge * 0.08
        + grappling_edge * 0.11
        + age_edge
        + reach_edge
        + height_edge
        + rest_edge
        + cardio_edge
        + explicit_style_edge
        + injury_penalty
        + opponent_injury_bonus
    )
    raw_win_probability = 1 / (1 + math.exp(-model_score))
    no_vig_anchor = _safe_float(input_stats.get("no_vig_market_probability"))
    if no_vig_anchor is not None and no_vig_anchor > 1:
        no_vig_anchor = no_vig_anchor / 100
    market_anchor = max(0.01, min(0.99, no_vig_anchor)) if no_vig_anchor is not None else None
    market_weight = 0.15 if market_anchor is not None else 0.0
    calibrated_win_probability = (
        raw_win_probability * (1 - market_weight) + market_anchor * market_weight
        if market_anchor is not None
        else raw_win_probability
    )
    abs_score = abs(model_score)
    if abs_score < 0.45:
        low_cap, high_cap = 0.36, 0.64
    elif abs_score < 0.90:
        low_cap, high_cap = 0.28, 0.74
    else:
        low_cap, high_cap = 0.20, 0.84
    flags = []
    probability_cap_reason = None
    final_win_probability = max(low_cap, min(high_cap, calibrated_win_probability))
    if final_win_probability != calibrated_win_probability:
        flags.append("combat probability cap applied")
        probability_cap_reason = f"fighter model score {round(model_score, 3)}"
    if raw_win_probability > 0.88 or raw_win_probability < 0.12:
        flags.append("raw probability extreme")

    fighter_win_probability = final_win_probability
    opponent_win_probability = 1 - fighter_win_probability
    finish_pressure = max(0.08, min(0.92, (fighter_finish + opponent_finish) / 2))
    durability = _safe_float(input_stats.get("chin_durability"), 70) or 70
    cardio = _safe_float(input_stats.get("cardio_rating"), 70) or 70
    scheduled_rounds = _safe_float(input_stats.get("scheduled_rounds"), 3) or 3
    pace = _safe_float(input_stats.get("pace_rating"), 70) or 70
    does_not_go_distance = max(0.12, min(0.82, finish_pressure * 0.72 + (pace - 70) * 0.002 - (durability - 70) * 0.002 - (cardio - 70) * 0.001))
    if scheduled_rounds >= 5:
        does_not_go_distance = min(0.88, does_not_go_distance + 0.05)
    goes_distance_probability = 1 - does_not_go_distance
    finish_total = max(0.01, fighter_ko + fighter_sub + fighter_decision)
    ko_share = fighter_ko / finish_total
    sub_share = fighter_sub / finish_total
    decision_share = fighter_decision / finish_total
    ko_tko_probability = fighter_win_probability * (does_not_go_distance * ko_share + 0.04)
    submission_probability = fighter_win_probability * (does_not_go_distance * sub_share + 0.02)
    decision_probability = max(0.02, fighter_win_probability - ko_tko_probability - submission_probability)
    if sport == "boxing":
        submission_probability = 0.0
        decision_probability = max(0.02, fighter_win_probability - ko_tko_probability)

    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    market_probability = _combat_market_probability(
        market=str(market or "moneyline"),
        selection=payload.get("selection") or input_stats.get("selection"),
        fighter_win_probability=fighter_win_probability,
        opponent_win_probability=opponent_win_probability,
        ko_tko_probability=ko_tko_probability,
        submission_probability=submission_probability,
        decision_probability=decision_probability,
        goes_distance_probability=goes_distance_probability,
        scheduled_rounds=scheduled_rounds,
        line=line,
    )
    market_key = _normal_market_key(market)
    if market_key == "moneyline":
        market_probability = fighter_win_probability
    else:
        market_probability = max(0.03, min(0.88, market_probability))

    confidence = 72.0
    risk_flags = []
    for flag, penalty in [
        ("short notice", 8),
        ("weight cut risk", 7),
        ("travel risk", 4),
        ("altitude risk", 4),
    ]:
        key = flag.replace(" ", "_")
        if input_stats.get(key):
            risk_flags.append(flag)
            confidence -= penalty
    if str(input_stats.get("fighter_injury_status", "healthy")).lower() not in {"healthy", "clear", "none"}:
        risk_flags.append("injury uncertainty")
        confidence -= 12
    if (_safe_float(input_stats.get("fighter_days_rest"), 90) or 90) > 365:
        risk_flags.append("large layoff")
        confidence -= 6
    if market_key in {"exact_round", "round_group", "method_of_victory", "knockdown_prop", "takedown_prop", "significant_strikes_prop", "submission_attempt_prop"}:
        risk_flags.append("volatile market")
        confidence -= 5
    if not input_stats.get("book_count") or (_safe_float(input_stats.get("book_count"), 0) or 0) < 5:
        risk_flags.append("book count too low")
        confidence -= 3
    if not input_stats.get("best_available_odds"):
        risk_flags.append("best available odds missing")
        confidence -= 2
    confidence = max(1, min(95, round(confidence, 2)))
    risk = "high" if risk_flags or market_key in {"exact_round", "round_group"} else "moderate"
    edge = calculate_edge_percent(market_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags = []
    if edge is not None and edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge is not None and edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    if "injury uncertainty" in risk_flags and market_key not in {"moneyline", "fight_goes_distance", "fight_does_not_go_distance"}:
        no_bet_flags.append("risk too high")
    suggested = 0.0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=market_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.005), 2)

    return {
        "model_status": "active",
        "true_probability": market_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": risk,
        "suggested_stake": suggested,
        "no_bet_flags": no_bet_flags,
        "raw_model_probability": raw_win_probability,
        "calibrated_model_probability": calibrated_win_probability,
        "probability_calibration_applied": bool(market_anchor is not None or flags),
        "probability_sanity_flags": list(dict.fromkeys(flags)),
        "probability_cap_reason": probability_cap_reason,
        "market_anchor_probability": market_anchor,
        "fighter_win_probability": fighter_win_probability,
        "opponent_win_probability": opponent_win_probability,
        "ko_tko_probability": ko_tko_probability,
        "submission_probability": submission_probability,
        "decision_probability": decision_probability,
        "goes_distance_probability": goes_distance_probability,
        "does_not_go_distance_probability": 1 - goes_distance_probability,
        "over_rounds_probability": _combat_market_probability(market="over_rounds", selection="Over", fighter_win_probability=fighter_win_probability, opponent_win_probability=opponent_win_probability, ko_tko_probability=ko_tko_probability, submission_probability=submission_probability, decision_probability=decision_probability, goes_distance_probability=goes_distance_probability, scheduled_rounds=scheduled_rounds, line=line),
        "under_rounds_probability": _combat_market_probability(market="under_rounds", selection="Under", fighter_win_probability=fighter_win_probability, opponent_win_probability=opponent_win_probability, ko_tko_probability=ko_tko_probability, submission_probability=submission_probability, decision_probability=decision_probability, goes_distance_probability=goes_distance_probability, scheduled_rounds=scheduled_rounds, line=line),
        "risk_flags": risk_flags,
        "input_coverage": 1.0,
        "provider_enrichment": {"provider_status": "not_provided", "provider_enrichment_present": []},
    }


def _normal_cdf(value: float, mean: float = 0.0, stddev: float = 1.0) -> float:
    stddev = max(0.0001, stddev)
    z = (value - mean) / (stddev * math.sqrt(2))
    return max(0.0, min(1.0, 0.5 * (1 + math.erf(z))))


def _golf_number(input_stats: dict[str, Any], key: str, default: float = 0.0) -> float:
    return _safe_float(input_stats.get(key), default) or default


def _golf_strength_score(input_stats: dict[str, Any], prefix: str = "player") -> float:
    rank = _golf_number(input_stats, f"{prefix}_world_rank", 80)
    recent_rank = _golf_number(input_stats, f"{prefix}_recent_form_rank", 70)
    scoring = _golf_number(input_stats, f"{prefix}_recent_scoring_average", 70.8)
    fit = _golf_number(input_stats, f"{prefix}_course_fit_score", _golf_number(input_stats, "course_fit_score", 65))
    history = _golf_number(input_stats, f"{prefix}_course_history_score", _golf_number(input_stats, "course_history_score", 60))
    sg_total = _golf_number(input_stats, f"{prefix}_sg_total", 0)
    sg_off_tee = _golf_number(input_stats, f"{prefix}_sg_off_tee", 0)
    sg_approach = _golf_number(input_stats, f"{prefix}_sg_approach", 0)
    sg_around_green = _golf_number(input_stats, f"{prefix}_sg_around_green", 0)
    sg_putting = _golf_number(input_stats, f"{prefix}_sg_putting", 0)
    return (
        sg_total * 0.55
        + sg_approach * 0.22
        + sg_off_tee * 0.13
        + sg_putting * 0.08
        + sg_around_green * 0.07
        + (100 - min(rank, 200)) / 100 * 0.45
        + (100 - min(recent_rank, 200)) / 100 * 0.22
        + (70.5 - scoring) * 0.16
        + (fit - 60) / 100 * 0.28
        + (history - 55) / 100 * 0.12
    )


def _golf_place_probabilities(input_stats: dict[str, Any], strength: float, calibrated_strength: Optional[float] = None) -> dict[str, float]:
    field_size = max(20, min(180, int(_golf_number(input_stats, "field_size", 120))))
    field_strength = max(40, min(100, _golf_number(input_stats, "field_strength", 75)))
    difficulty = max(40, min(100, _golf_number(input_stats, "course_difficulty_rating", 70)))
    wind = max(0, min(100, _golf_number(input_stats, "weather_wind_rating", 35)))
    volatility = 1 + max(0, field_strength - 70) * 0.006 + max(0, difficulty - 70) * 0.004 + max(0, wind - 40) * 0.004
    strength_for_probs = calibrated_strength if calibrated_strength is not None else strength
    win_base = math.exp(max(-2.5, min(2.5, strength_for_probs * 1.18))) / field_size
    outright = max(0.002, min(0.22, win_base * 1.35 / volatility))
    top5 = max(0.02, min(0.62, outright * 4.4 + 0.035 + strength_for_probs * 0.025))
    top10 = max(0.04, min(0.76, outright * 7.1 + 0.075 + strength_for_probs * 0.035))
    top20 = max(0.08, min(0.90, outright * 11.5 + 0.17 + strength_for_probs * 0.045))
    cut_projection = _golf_number(input_stats, "cut_line_projection", 75)
    make_cut = cut_projection / 100 if cut_projection > 1 else cut_projection
    if input_stats.get("cut_line_projection") is None:
        make_cut = _normal_cdf(strength_for_probs, mean=-0.18, stddev=0.72)
    make_cut = max(0.12, min(0.96, make_cut))
    return {
        "outright_winner": outright,
        "top_5": top5,
        "top_10": top10,
        "top_20": top20,
        "make_cut": make_cut,
        "miss_cut": 1 - make_cut,
    }


def _golf_market_probability(
    *,
    market: str,
    selection: Any,
    input_stats: dict[str, Any],
    strength: float,
    place_probs: dict[str, float],
    line: Optional[float],
) -> float:
    market_key = _normal_market_key(market)
    if market_key in place_probs:
        return place_probs[market_key]
    if market_key == "top_n_finish":
        top_n = max(1, _safe_float(input_stats.get("top_n"), 10) or 10)
        if top_n <= 5:
            return place_probs["top_5"]
        if top_n <= 10:
            return place_probs["top_10"]
        if top_n <= 20:
            return place_probs["top_20"]
        return max(place_probs["top_20"], min(0.96, place_probs["top_20"] + (top_n - 20) * 0.012))
    if market_key == "finishing_position":
        finish_line = line if line is not None else _safe_float(input_stats.get("line"), 20) or 20
        return _golf_market_probability(market="top_n_finish", selection=selection, input_stats={**input_stats, "top_n": finish_line}, strength=strength, place_probs=place_probs, line=line)
    if market_key in {"tournament_matchup", "round_matchup", "three_ball"}:
        opponent_strength = _golf_strength_score(input_stats, "opponent")
        diff = strength - opponent_strength
        base = 1 / (1 + math.exp(-diff / 0.75))
        if market_key == "three_ball":
            return max(0.18, min(0.62, base * 0.74))
        if market_key == "round_matchup":
            return max(0.28, min(0.72, 0.5 + (base - 0.5) * 0.72))
        return max(0.30, min(0.74, base))
    if market_key == "first_round_leader":
        return max(0.002, min(0.14, place_probs["outright_winner"] * 0.72))

    round_score_mean = 70.8 - strength * 0.85 + (_golf_number(input_stats, "course_difficulty_rating", 70) - 70) * 0.045 + (_golf_number(input_stats, "weather_wind_rating", 35) - 35) * 0.025
    prop_line = line if line is not None else _safe_float(input_stats.get("line"))
    selection_text = str(selection or "").lower()
    if market_key == "round_score_prop":
        score_line = prop_line if prop_line is not None else 70.5
        under_prob = _normal_cdf(score_line, mean=round_score_mean, stddev=2.25)
        return 1 - under_prob if "over" in selection_text else under_prob
    birdies_mean = max(2.0, min(6.2, 3.7 + strength * 0.45 - (_golf_number(input_stats, "course_difficulty_rating", 70) - 70) * 0.015))
    if market_key in {"birdies_prop", "player_prop"}:
        prop_type = str(input_stats.get("prop_type") or "").lower()
        if market_key == "player_prop" and prop_type and "bird" not in prop_type:
            pass
        birdie_line = prop_line if prop_line is not None else 3.5
        over_prob = 1 - _normal_cdf(birdie_line, mean=birdies_mean, stddev=1.25)
        return over_prob if "over" in selection_text or market_key == "player_prop" else 1 - over_prob
    if market_key == "eagles_prop":
        eagle_line = prop_line if prop_line is not None else 0.5
        over_prob = max(0.03, min(0.28, 0.10 + strength * 0.025 - eagle_line * 0.04))
        return over_prob if "over" in selection_text else 1 - over_prob
    if market_key == "fairways_hit_prop":
        fairway_line = prop_line if prop_line is not None else 8.5
        fairways_mean = max(6.0, min(11.5, 8.7 + _golf_number(input_stats, "player_sg_off_tee", 0) * 0.35))
        over_prob = 1 - _normal_cdf(fairway_line, mean=fairways_mean, stddev=1.65)
        return over_prob if "over" in selection_text else 1 - over_prob
    if market_key == "greens_in_regulation_prop":
        gir_line = prop_line if prop_line is not None else 12.5
        gir_mean = max(9.0, min(15.8, 12.1 + _golf_number(input_stats, "player_sg_approach", 0) * 0.72))
        over_prob = 1 - _normal_cdf(gir_line, mean=gir_mean, stddev=1.9)
        return over_prob if "over" in selection_text else 1 - over_prob
    if market_key == "putts_prop":
        putts_line = prop_line if prop_line is not None else 29.5
        putts_mean = max(26.5, min(32.5, 29.1 - _golf_number(input_stats, "player_sg_putting", 0) * 0.65))
        under_prob = _normal_cdf(putts_line, mean=putts_mean, stddev=2.0)
        return 1 - under_prob if "over" in selection_text else under_prob
    return place_probs["top_10"]


def _estimate_golf_course_fit_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _golf_full_inputs_missing(input_stats, payload) + _golf_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    strength = _golf_strength_score(input_stats, "player")
    raw_model_probability = max(0.02, min(0.98, 1 / (1 + math.exp(-strength / 0.85))))
    no_vig_anchor = _safe_float(input_stats.get("no_vig_market_probability"))
    if no_vig_anchor is not None and no_vig_anchor > 1:
        no_vig_anchor = no_vig_anchor / 100
    market_anchor = max(0.01, min(0.99, no_vig_anchor)) if no_vig_anchor is not None else None
    anchor_weight = 0.12 if market_anchor is not None else 0.0
    calibrated_strength = strength
    calibrated_model_probability = raw_model_probability
    if market_anchor is not None:
        calibrated_model_probability = raw_model_probability * (1 - anchor_weight) + market_anchor * anchor_weight
        calibrated_strength = math.log(calibrated_model_probability / max(0.001, 1 - calibrated_model_probability)) * 0.85
    place_probs = _golf_place_probabilities(input_stats, strength, calibrated_strength)
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    market_probability = _golf_market_probability(
        market=str(market or "top_10"),
        selection=payload.get("selection") or input_stats.get("selection"),
        input_stats=input_stats,
        strength=calibrated_strength,
        place_probs=place_probs,
        line=line,
    )
    market_probability = max(0.002, min(0.94, market_probability))
    sanity_flags = []
    probability_cap_reason = None
    if market_probability in {0.002, 0.94}:
        sanity_flags.append("golf probability cap applied")
        probability_cap_reason = "market probability bounded by golf sanity caps"
    confidence = 74.0
    risk_flags = []
    market_key = _normal_market_key(market)
    if input_stats.get("weather_wind_rating") is not None and _golf_number(input_stats, "weather_wind_rating", 0) >= 70:
        risk_flags.append("high wind volatility")
        confidence -= 6
    if input_stats.get("course_fit_score") is None:
        risk_flags.append("course fit missing")
        confidence -= 5
    if input_stats.get("player_withdrawal_risk") or str(input_stats.get("injury_status") or "").lower() not in {"", "healthy", "none", "clear"}:
        risk_flags.append("withdrawal or injury risk")
        confidence -= 10
    if market_key in {"outright_winner", "first_round_leader", "eagles_prop", "three_ball"}:
        risk_flags.append("volatile golf market")
        confidence -= 5
    if market_key.endswith("_prop") or market_key == "player_prop":
        risk_flags.append("prop fragility")
        confidence -= 3
    if not input_stats.get("book_count") or (_safe_float(input_stats.get("book_count"), 0) or 0) < 4:
        risk_flags.append("book count too low")
        confidence -= 3
    confidence = max(1, min(95, round(confidence, 2)))
    edge = calculate_edge_percent(market_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags = []
    if edge is not None and edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge is not None and edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    if "withdrawal or injury risk" in risk_flags:
        no_bet_flags.append("risk too high")
    suggested = 0.0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=market_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)
    return {
        "model_status": "active",
        "true_probability": market_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested,
        "no_bet_flags": no_bet_flags,
        "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_model_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": probability_cap_reason,
        "market_anchor_probability": market_anchor,
        "player_strength_score": strength,
        "field_size": int(_golf_number(input_stats, "field_size", 120)),
        "outright_win_probability": place_probs["outright_winner"],
        "top_5_probability": place_probs["top_5"],
        "top_10_probability": place_probs["top_10"],
        "top_20_probability": place_probs["top_20"],
        "make_cut_probability": place_probs["make_cut"],
        "miss_cut_probability": place_probs["miss_cut"],
        "risk_flags": risk_flags,
        "input_coverage": 1.0,
        "provider_enrichment": {"provider_status": "not_provided", "provider_enrichment_present": []},
    }


def _basketball_module_calibration(sport: str) -> dict[str, Any]:
    if sport == "basketball_wnba":
        return {
            "league_calibration_applied": "wnba",
            "pace_baseline": 78.5,
            "home_court": 2.1,
            "rating_scale": 8.5,
            "volatility": 11.5,
            "injury_weight": 0.75,
            "travel_weight": 0.45,
            "confidence_base": 74.0,
        }
    if sport == "basketball_ncaab":
        return {
            "league_calibration_applied": "ncaab",
            "pace_baseline": 70.5,
            "home_court": 3.1,
            "rating_scale": 9.5,
            "volatility": 13.5,
            "rank_weight": 0.06,
            "strength_weight": 0.08,
            "conference_weight": 0.045,
            "experience_weight": 0.025,
            "confidence_base": 72.0,
        }
    return {
        "league_calibration_applied": "ncaawb",
        "pace_baseline": 72.0,
        "home_court": 3.4,
        "rating_scale": 8.8,
        "volatility": 14.5,
        "rank_weight": 0.08,
        "strength_weight": 0.09,
        "conference_weight": 0.05,
        "experience_weight": 0.02,
        "top_team_weight": 0.7,
        "confidence_base": 71.0,
    }


def _estimate_basketball_module_model(
    *,
    sport: str,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _basketball_module_full_inputs_missing(sport, input_stats, payload) + _basketball_module_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    calibration = _basketball_module_calibration(sport)
    home_off = _safe_float(input_stats.get("home_offensive_rating"), 100) or 100
    home_def = _safe_float(input_stats.get("home_defensive_rating"), 100) or 100
    away_off = _safe_float(input_stats.get("away_offensive_rating"), 100) or 100
    away_def = _safe_float(input_stats.get("away_defensive_rating"), 100) or 100
    home_pace = _safe_float(input_stats.get("home_pace"), calibration["pace_baseline"]) or calibration["pace_baseline"]
    away_pace = _safe_float(input_stats.get("away_pace"), calibration["pace_baseline"]) or calibration["pace_baseline"]
    possessions = max(58, min(88, (home_pace + away_pace) / 2))
    home_quality = (home_off - away_def) * 0.42 + (_safe_float(input_stats.get("home_effective_fg_pct"), 50) - _safe_float(input_stats.get("away_effective_fg_pct"), 50)) * 0.11
    away_quality = (away_off - home_def) * 0.42 + (_safe_float(input_stats.get("away_effective_fg_pct"), 50) - _safe_float(input_stats.get("home_effective_fg_pct"), 50)) * 0.11
    margin = home_quality - away_quality + calibration["home_court"]
    margin += (_safe_float(input_stats.get("home_rebound_rate"), 50) - _safe_float(input_stats.get("away_rebound_rate"), 50)) * 0.04
    margin -= (_safe_float(input_stats.get("home_turnover_rate"), 15) - _safe_float(input_stats.get("away_turnover_rate"), 15)) * 0.09
    margin += (_safe_float(input_stats.get("home_free_throw_rate"), 25) - _safe_float(input_stats.get("away_free_throw_rate"), 25)) * 0.035
    margin += (_safe_float(input_stats.get("home_rest_days"), 2) - _safe_float(input_stats.get("away_rest_days"), 2)) * 0.25
    margin -= (_safe_float(input_stats.get("home_travel_fatigue"), 0) - _safe_float(input_stats.get("away_travel_fatigue"), 0)) * calibration.get("travel_weight", 0.35)
    if sport == "basketball_wnba":
        margin += (_safe_float(input_stats.get("home_injury_adjustment"), 0) - _safe_float(input_stats.get("away_injury_adjustment"), 0)) * calibration["injury_weight"]
    else:
        rank_edge = (_safe_float(input_stats.get("away_rank"), 60) - _safe_float(input_stats.get("home_rank"), 60)) * calibration["rank_weight"]
        strength_edge = (_safe_float(input_stats.get("home_strength_rating"), 0) - _safe_float(input_stats.get("away_strength_rating"), 0)) * calibration["strength_weight"]
        conference_edge = (_safe_float(input_stats.get("home_conference_strength"), 0) - _safe_float(input_stats.get("away_conference_strength"), 0)) * calibration["conference_weight"]
        experience_edge = (_safe_float(input_stats.get("home_experience_rating"), 0) - _safe_float(input_stats.get("away_experience_rating"), 0)) * calibration["experience_weight"]
        shooting_edge = (_safe_float(input_stats.get("home_three_point_rate"), 35) - _safe_float(input_stats.get("away_three_point_rate"), 35)) * 0.025
        ft_edge = (_safe_float(input_stats.get("home_free_throw_pct"), 72) - _safe_float(input_stats.get("away_free_throw_pct"), 72)) * 0.025
        margin += rank_edge + strength_edge + conference_edge + experience_edge + shooting_edge + ft_edge
        if sport == "basketball_ncaawb" and (_safe_float(input_stats.get("home_rank"), 99) or 99) <= 5:
            margin += calibration.get("top_team_weight", 0)
    if input_stats.get("neutral_court") or input_stats.get("tournament_game"):
        margin -= calibration["home_court"] * 0.65

    selected_home = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower() == str(input_stats.get("home_team") or "").strip().lower()
    selected_margin = margin if selected_home else -margin
    raw_probability = 1 / (1 + math.exp(-selected_margin / calibration["rating_scale"]))
    no_vig_anchor = _safe_float(input_stats.get("no_vig_market_probability"))
    if no_vig_anchor is not None and no_vig_anchor > 1:
        no_vig_anchor = no_vig_anchor / 100
    market_anchor = max(0.01, min(0.99, no_vig_anchor)) if no_vig_anchor is not None else None
    calibrated_probability = raw_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_probability
    probability = max(0.08, min(0.92, calibrated_probability))
    projected_total = max(98, min(185, possessions * ((home_off + away_off) / 200) * 2.0 + 18))
    market_key = _normal_market_key(market)
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    total_line = _safe_float(payload.get("total_line"), _safe_float(input_stats.get("total_line")))
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").lower()
    if market_key in {"spread", "first_half_spread", "first_quarter_spread", "alt_spread"}:
        spread_line = line if line is not None else 0
        scale = calibration["volatility"] * (0.55 if "first_half" in market_key else 0.32 if "first_quarter" in market_key else 1.0)
        probability = _normal_cdf(selected_margin + spread_line, mean=0, stddev=max(4.0, scale))
    elif market_key in {"total", "first_half_total", "first_quarter_total", "alt_total"}:
        target_total = total_line if total_line is not None else projected_total
        projected = projected_total * (0.49 if "first_half" in market_key else 0.245 if "first_quarter" in market_key else 1.0)
        over_prob = 1 - _normal_cdf(target_total, mean=projected, stddev=max(5.0, calibration["volatility"]))
        probability = over_prob if "over" in selection_text else 1 - over_prob
    elif market_key in {"team_total", "alt_team_total"}:
        target_total = total_line if total_line is not None else projected_total / 2
        projected_team = projected_total / 2 + selected_margin / 2
        over_prob = 1 - _normal_cdf(target_total, mean=projected_team, stddev=max(4.0, calibration["volatility"] * 0.72))
        probability = over_prob if "over" in selection_text else 1 - over_prob
    elif market_key in BASKETBALL_MODULE_PROP_MARKETS:
        prop_map = {
            "player_points": "player_points_projection",
            "player_rebounds": "player_rebounds_projection",
            "player_assists": "player_assists_projection",
            "player_pra": "player_pra_projection",
            "player_threes": "player_threes_projection",
            "player_steals": "player_steals_projection",
            "player_blocks": "player_blocks_projection",
            "player_turnovers": "player_turnovers_projection",
        }
        if market_key == "double_double":
            probability = max(0.05, min(0.72, (_safe_float(input_stats.get("player_rebounds_projection"), 6) or 6) / 16))
        else:
            projection = _safe_float(input_stats.get(prop_map.get(market_key, "player_points_projection")), 10) or 10
            prop_line = line if line is not None else projection
            stddev = max(1.8, projection * 0.22)
            over_prob = 1 - _normal_cdf(prop_line, mean=projection, stddev=stddev)
            probability = over_prob if "over" in selection_text or selection_text == str(input_stats.get("player") or "").lower() else 1 - over_prob
    probability = max(0.02, min(0.94, probability))
    confidence = calibration["confidence_base"]
    risk_flags = []
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 3
        risk_flags.append("book count too low")
    if market_key in BASKETBALL_MODULE_PROP_MARKETS:
        confidence -= 3
        if _safe_float(input_stats.get("player_minutes_projection"), 0) < 18:
            confidence -= 10
            risk_flags.append("player minutes uncertainty")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    if input_stats.get("tempo_volatility") or input_stats.get("blowout_risk"):
        confidence -= 4
        risk_flags.append("college variance")
    confidence = max(1, min(95, round(confidence, 2)))
    edge = calculate_edge_percent(probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags = []
    if edge is not None and edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge is not None and edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    return {
        "model_status": "active",
        "true_probability": probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": "moderate" if not risk_flags else "high",
        "suggested_stake": suggested,
        "no_bet_flags": no_bet_flags,
        "raw_model_probability": raw_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None),
        "probability_sanity_flags": ["basketball module probability cap applied"] if probability != calibrated_probability else [],
        "probability_cap_reason": calibration["league_calibration_applied"],
        "market_anchor_probability": market_anchor,
        "league_calibration_applied": calibration["league_calibration_applied"],
        "projected_margin": round(margin, 2),
        "projected_total": round(projected_total, 2),
        "projected_team_points": round(projected_total / 2 + selected_margin / 2, 2),
        "projected_opponent_points": round(projected_total / 2 - selected_margin / 2, 2),
        "risk_flags": risk_flags,
        "input_coverage": 1.0,
        "provider_enrichment": {"provider_status": "not_provided", "provider_enrichment_present": []},
    }


def _calibrate_nfl_probability(
    *,
    raw_probability: float,
    market_anchor_probability: float,
    market_anchor_is_no_vig: bool,
    projected_margin: float,
    input_confidence_hint: float,
) -> dict[str, Any]:
    flags: list[str] = []
    if raw_probability >= 0.90 or raw_probability <= 0.10:
        flags.append("raw probability extreme")

    abs_margin = abs(projected_margin)
    high_quality_extreme = abs_margin >= 14 and input_confidence_hint >= 80
    if (raw_probability >= 0.90 or raw_probability <= 0.10) and not high_quality_extreme:
        if market_anchor_is_no_vig:
            calibrated = (raw_probability * 0.10) + (market_anchor_probability * 0.90)
        else:
            model_floor = 0.58 if raw_probability >= 0.90 else 0.42
            calibrated = (model_floor * 0.95) + (market_anchor_probability * 0.05)
    else:
        anchor_weight = 0.25 if market_anchor_is_no_vig else 0.05
        calibrated = (raw_probability * (1 - anchor_weight)) + (market_anchor_probability * anchor_weight)
    if abs(calibrated - raw_probability) >= 0.025:
        flags.append("probability calibration applied")

    if high_quality_extreme:
        lower_cap, upper_cap = 0.08, 0.92
    elif abs_margin >= 10:
        lower_cap, upper_cap = 0.15, 0.85
    elif abs_margin >= 7:
        lower_cap, upper_cap = 0.22, 0.78
    elif abs_margin >= 4:
        lower_cap, upper_cap = 0.30, 0.70
    else:
        lower_cap, upper_cap = 0.38, 0.62

    final_probability = max(lower_cap, min(upper_cap, calibrated))
    if final_probability != calibrated:
        flags.append("probability capped by projected margin")
        flags.append("probability calibration applied")

    return {
        "raw_model_probability": raw_probability,
        "calibrated_model_probability": calibrated,
        "final_probability": final_probability,
        "market_anchor_probability": market_anchor_probability,
        "probability_calibration_applied": bool(flags),
        "probability_sanity_flags": list(dict.fromkeys(flags)),
        "probability_cap_reason": (
            "extreme projected margin with high input confidence"
            if high_quality_extreme
            else f"projected margin {round(projected_margin, 2)} points"
        ),
    }


def _estimate_soccer_goal_model(
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    core_missing = _soccer_full_inputs_missing(input_stats, payload)
    market_missing = _soccer_market_specific_missing(market, input_stats, payload)
    if core_missing or market_missing:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    optional_present = [field for field in SOCCER_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    provider_present = [field for field in SOCCER_PROVIDER_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    officiating_present = _official_inputs_present(input_stats, SOCCER_OFFICIATING_INPUTS)
    social_present = [field for field in SOCCER_SOCIAL_CROWD_INPUTS if input_stats.get(field) is not None]
    live_present = [field for field in SOCCER_LIVE_BETTING_INPUTS if input_stats.get(field) is not None]

    team_lambda = (
        number("team_expected_goals") * 0.35
        + ((number("team_xg_for") + number("opponent_xg_against")) / 2) * 0.35
        + ((number("team_goals_for_per_match") + number("opponent_goals_against_per_match")) / 2) * 0.15
        + ((number("team_shots_on_target_per_match") + number("opponent_shots_on_target_allowed_per_match")) / 9) * 0.15
    )
    opponent_lambda = (
        number("opponent_expected_goals") * 0.35
        + ((number("opponent_xg_for") + number("team_xg_against")) / 2) * 0.35
        + ((number("opponent_goals_for_per_match") + number("team_goals_against_per_match")) / 2) * 0.15
        + ((number("opponent_shots_on_target_per_match") + number("team_shots_on_target_allowed_per_match")) / 9) * 0.15
    )
    time_decay_applied = False
    if input_stats.get("team_recent_xg_for_5") is not None and input_stats.get("opponent_recent_xg_for_5") is not None:
        team_lambda = team_lambda * 0.75 + number("team_recent_xg_for_5") * 0.25
        opponent_lambda = opponent_lambda * 0.75 + number("opponent_recent_xg_for_5") * 0.25
        time_decay_applied = True
    if input_stats.get("team_home_xg_for") is not None and str(input_stats.get("home_away") or "").lower() == "home":
        team_lambda = team_lambda * 0.85 + number("team_home_xg_for") * 0.15
    if input_stats.get("opponent_away_xg_for") is not None:
        opponent_lambda = opponent_lambda * 0.85 + number("opponent_away_xg_for") * 0.15
    team_lambda += (number("team_big_chances_per_match") - number("opponent_big_chances_allowed_per_match")) * 0.035
    opponent_lambda += (number("opponent_big_chances_per_match") - number("team_big_chances_allowed_per_match")) * 0.035
    possession_edge = (number("team_possession_percent") - number("opponent_possession_percent")) / 100
    team_lambda += max(-0.08, min(0.08, possession_edge * 0.18))
    opponent_lambda -= max(-0.08, min(0.08, possession_edge * 0.12))
    rest_edge = number("team_rest_days") - number("opponent_rest_days")
    team_lambda += max(-0.08, min(0.08, rest_edge * 0.025))
    opponent_lambda -= max(-0.06, min(0.06, rest_edge * 0.015))

    injury_status = str(input_stats.get("injury_report_status") or "").lower()
    lineup_status = str(input_stats.get("lineup_status") or "").lower()
    if "attacker" in injury_status or "forward" in injury_status:
        team_lambda -= 0.18
    if "defender" in injury_status:
        opponent_lambda += 0.15
    if "goalkeeper" in injury_status or "keeper" in injury_status:
        opponent_lambda += 0.20
    if lineup_status not in {"confirmed", "posted", "official"}:
        team_lambda -= 0.08
        opponent_lambda -= 0.03
    if str(input_stats.get("weather_severity") or "").lower() in {"severe", "high", "wind", "storm"}:
        team_lambda -= 0.08
        opponent_lambda -= 0.08
    if officiating_present:
        team_lambda += (number("referee_penalty_rate", 0.10) - 0.10) * 0.25
        opponent_lambda += (number("referee_penalty_rate", 0.10) - 0.10) * 0.20

    probability_sanity_flags: list[str] = []
    uncapped_team_lambda = team_lambda
    uncapped_opponent_lambda = opponent_lambda
    team_lambda = max(0.20, min(3.8, team_lambda))
    opponent_lambda = max(0.20, min(3.8, opponent_lambda))
    if team_lambda != uncapped_team_lambda or opponent_lambda != uncapped_opponent_lambda:
        probability_sanity_flags.append("lambda capped")

    rho = _safe_float(input_stats.get("dixon_coles_rho"), -0.08)
    score_matrix = build_soccer_score_matrix(team_lambda, opponent_lambda)
    score_matrix = apply_dixon_coles_adjustment(score_matrix, team_lambda, opponent_lambda, rho if rho is not None else -0.08)
    shared_intensity = _safe_float(input_stats.get("shared_intensity"))
    if shared_intensity is None:
        goal_correlation = _safe_float(input_stats.get("goal_correlation"), 0.05) or 0.05
        shared_intensity = max(0.02, min(0.10, goal_correlation))
    score_matrix = apply_bivariate_poisson_adjustment(score_matrix, shared_intensity)
    first_half_lambdas = estimate_first_half_lambdas(team_lambda, opponent_lambda, _safe_float(input_stats.get("first_half_goal_share")))
    first_half_matrix = apply_bivariate_poisson_adjustment(
        apply_dixon_coles_adjustment(build_soccer_score_matrix(*first_half_lambdas), *first_half_lambdas, rho if rho is not None else -0.08),
        min(0.08, shared_intensity),
    )

    selection = payload.get("selection") or input_stats.get("selection")
    team = input_stats.get("team")
    opponent = input_stats.get("opponent")
    if market_key in {"moneyline", "three_way_moneyline", "home_draw_away"}:
        if market_key == "moneyline" and input_stats.get("two_way_market") is True:
            raw_model_probability = estimate_draw_no_bet_probability(score_matrix, selection, team, opponent)
        elif market_key == "moneyline" and input_stats.get("two_way_market") is None:
            raw_model_probability = estimate_three_way_probability(score_matrix, selection, team, opponent)
        else:
            raw_model_probability = estimate_three_way_probability(score_matrix, selection, team, opponent)
    elif market_key == "draw_no_bet":
        raw_model_probability = estimate_draw_no_bet_probability(score_matrix, selection, team, opponent)
    elif market_key == "double_chance":
        raw_model_probability = estimate_double_chance_probability(score_matrix, selection, team, opponent)
    elif market_key in {"asian_handicap", "spread", "alt_line"}:
        line = _safe_float(input_stats.get("line") if input_stats.get("line") is not None else payload.get("line"), 0) or 0
        raw_model_probability = estimate_handicap_probability(score_matrix, line)
    elif market_key in {"total", "second_half_total"}:
        total_line = _safe_float(input_stats.get("total_line") if input_stats.get("total_line") is not None else payload.get("total_line"), 0) or 0
        raw_model_probability = estimate_total_probability_from_score_matrix(score_matrix, total_line, selection)
    elif market_key == "team_total":
        team_total_line = _safe_float(input_stats.get("team_total_line") if input_stats.get("team_total_line") is not None else payload.get("team_total_line"), 0) or 0
        raw_model_probability = estimate_team_total_probability_from_score_matrix(score_matrix, team_total_line, selection)
    elif market_key == "both_teams_to_score":
        raw_model_probability = estimate_btts_probability(score_matrix, selection)
    elif market_key == "correct_score":
        raw_model_probability = estimate_correct_score_probability(score_matrix, input_stats.get("correct_score_selection") or payload.get("correct_score_selection"))
    elif market_key == "first_half_moneyline":
        raw_model_probability = estimate_three_way_probability(first_half_matrix, selection, team, opponent)
    elif market_key == "first_half_total":
        total_line = _safe_float(input_stats.get("total_line") if input_stats.get("total_line") is not None else payload.get("total_line"), 0) or 0
        raw_model_probability = estimate_total_probability_from_score_matrix(first_half_matrix, total_line, selection)
    elif market_key == "first_half_team_total":
        team_total_line = _safe_float(input_stats.get("team_total_line") if input_stats.get("team_total_line") is not None else payload.get("team_total_line"), 0) or 0
        raw_model_probability = estimate_team_total_probability_from_score_matrix(first_half_matrix, team_total_line, selection)
    elif market_key in {"corners", "team_corners"}:
        line_key = "team_corner_line" if market_key == "team_corners" else "corner_line"
        projection = number("team_corner_rate", 5.0) if market_key == "team_corners" else number("team_corner_rate", 5.0) + number("opponent_corner_rate", 4.8)
        line = _safe_float(input_stats.get(line_key) if input_stats.get(line_key) is not None else payload.get(line_key), 0) or 0
        raw_model_probability = _logistic_probability(projection - line, 2.0)
    elif market_key in {"cards", "team_cards"}:
        line_key = "team_card_line" if market_key == "team_cards" else "card_line"
        projection = number("team_cards_per_match", 2.0) if market_key == "team_cards" else number("team_cards_per_match", 2.0) + number("opponent_cards_per_match", 2.0)
        if officiating_present:
            projection = projection * 0.85 + number("referee_cards_per_match", projection) * 0.15
        line = _safe_float(input_stats.get(line_key) if input_stats.get(line_key) is not None else payload.get(line_key), 0) or 0
        raw_model_probability = _logistic_probability(projection - line, 1.4)
    elif market_key == "anytime_goal_scorer":
        goal_projection = number("player_goal_projection")
        minutes = max(1, number("player_minutes_projection", 75))
        raw_model_probability = max(0.03, min(0.75, 1 - math.exp(-goal_projection * minutes / 90)))
    elif market_key == "first_goal_scorer":
        raw_model_probability = max(0.03, min(0.35, number("player_first_goal_projection")))
    elif market_key == "player_prop":
        projection = number("player_projection")
        prop_line = number("prop_line")
        raw_model_probability = _logistic_probability(projection - prop_line, max(0.75, abs(prop_line) * 0.22))
    else:
        raw_model_probability = estimate_three_way_probability(score_matrix, selection, team, opponent)

    implied_probability = american_odds_to_implied_probability(odds_american)
    market_probability = _safe_probability(input_stats.get("no_vig_market_probability"))
    market_anchor_probability = market_probability if market_probability is not None else implied_probability if implied_probability is not None else 0.5
    projected_goal_differential = team_lambda - opponent_lambda

    confidence_base = 68
    confidence_hint = calculate_confidence(confidence_base, min(7, len(optional_present) * 0.15), min(4, len(provider_present) * 0.5))
    calibration = calibrate_soccer_probability(
        raw_probability=raw_model_probability,
        market_anchor_probability=market_anchor_probability,
        market_anchor_is_no_vig=market_probability is not None,
        projected_goal_differential=projected_goal_differential,
        market_key=market_key,
        input_confidence_hint=confidence_hint,
    )
    if probability_sanity_flags:
        calibration["probability_sanity_flags"] = list(dict.fromkeys(calibration["probability_sanity_flags"] + probability_sanity_flags))
        calibration["probability_calibration_applied"] = True
    true_probability = calibration["final_probability"]

    confidence_adjustments: list[float] = [min(7, len(optional_present) * 0.15), min(4, len(provider_present) * 0.5)]
    if lineup_status not in {"confirmed", "posted", "official"}:
        confidence_adjustments.append(-7)
    if "goalkeeper" in injury_status or "keeper" in injury_status:
        confidence_adjustments.append(-7)
    if abs(rest_edge) >= 3:
        confidence_adjustments.append(-3)
    if str(input_stats.get("weather_severity") or "").lower() in {"severe", "high", "wind", "storm"}:
        confidence_adjustments.append(-5)
    if input_stats.get("best_available_odds") is None:
        confidence_adjustments.append(-3)
    book_count = _safe_float(input_stats.get("book_count"))
    if book_count is not None and book_count < 5:
        confidence_adjustments.append(-4)
    current_odds = _safe_float(input_stats.get("current_odds"))
    consensus_odds = _safe_float(input_stats.get("consensus_odds"))
    risk = "medium"
    if current_odds is not None and consensus_odds is not None and abs(current_odds - consensus_odds) >= 25:
        risk = "high"
        confidence_adjustments.append(-3)
    if officiating_present and number("official_sample_size") and number("official_sample_size") < 20:
        confidence_adjustments.append(-2)
    if market_key in {"correct_score", "first_goal_scorer"}:
        risk = "high"
        confidence_adjustments.append(-8)
    if market_key in {"player_prop", "anytime_goal_scorer", "first_goal_scorer"}:
        if str(input_stats.get("player_starting_status") or "").lower() not in {"confirmed", "starting", "active"}:
            confidence_adjustments.append(-12)
        if number("player_minutes_projection") < 60:
            confidence_adjustments.append(-6)
    if calibration["probability_sanity_flags"]:
        confidence_adjustments.append(-min(6, len(calibration["probability_sanity_flags"]) * 2))
    confidence = calculate_confidence(confidence_base, *confidence_adjustments)

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
        risk = "high"
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
        risk = "high"
    if lineup_status not in {"confirmed", "posted", "official"}:
        no_bet_flags.append("lineup not confirmed")
    if market_key in {"player_prop", "anytime_goal_scorer", "first_goal_scorer"} and str(input_stats.get("player_starting_status") or "").lower() not in {"confirmed", "starting", "active"}:
        no_bet_flags.append("player starting status unconfirmed")
    if market_key in {"correct_score", "first_goal_scorer"} and edge is not None and edge < 8:
        no_bet_flags.append("high variance market")
    if current_odds is not None and consensus_odds is not None and abs(current_odds - consensus_odds) >= 35:
        no_bet_flags.append("market disagreement too high")

    suggested = 0.0
    if not no_bet_flags:
        suggested = calculate_suggested_stake(
            bankroll=bankroll,
            american_odds=odds_american,
            true_probability=true_probability,
            risk_profile=risk_profile,
            confidence=confidence,
        )
        risk = "low" if edge is not None and edge >= 5 else risk

    draw_probability = sum(score_matrix[i][i] for i in range(len(score_matrix)))
    btts_probability = estimate_btts_probability(score_matrix, "yes")
    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "final_probability": true_probability,
        "model_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": risk,
        "suggested_stake": suggested,
        "raw_model_probability": calibration["raw_model_probability"],
        "calibrated_model_probability": calibration["calibrated_model_probability"],
        "probability_calibration_applied": calibration["probability_calibration_applied"],
        "probability_sanity_flags": calibration["probability_sanity_flags"],
        "probability_cap_reason": calibration["probability_cap_reason"],
        "market_anchor_probability": calibration["market_anchor_probability"],
        "team_lambda": round(team_lambda, 3),
        "opponent_lambda": round(opponent_lambda, 3),
        "projected_team_goals": round(team_lambda, 3),
        "projected_opponent_goals": round(opponent_lambda, 3),
        "projected_total_goals": round(team_lambda + opponent_lambda, 3),
        "projected_goal_differential": round(projected_goal_differential, 3),
        "draw_probability": draw_probability,
        "btts_probability": btts_probability,
        "dixon_coles_adjustment_applied": True,
        "bivariate_poisson_adjustment_applied": shared_intensity > 0,
        "time_decay_applied": time_decay_applied,
        "soccer_input_contract": deepcopy(SOCCER_INPUT_CONTRACT),
        "input_coverage": {
            "required_core_present": list(SOCCER_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": SOCCER_REQUIRED_MARKET_SPECIFIC_INPUTS.get(market_key, []),
            "optional_enrichment_present": optional_present,
            "optional_enrichment_missing": [field for field in SOCCER_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
            "provider_enrichment_present": provider_present,
            "officiating_present": officiating_present,
            "referee_present": officiating_present,
            "social_crowd_present": social_present,
            "live_betting_present": live_present,
        },
        "provider_enrichment": {
            "provider_enrichment_present": provider_present,
            "provider_status": "available" if provider_present else "not_provided",
        },
        "no_bet_flags": no_bet_flags,
    }


def _estimate_nhl_goal_model(
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    core_missing = _nhl_full_inputs_missing(input_stats, payload)
    market_missing = _nhl_market_specific_missing(market, input_stats, payload)
    if core_missing or market_missing:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    def truthy(key: str) -> bool:
        return _truthy_available(input_stats.get(key))

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    optional_present = [field for field in NHL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    provider_present = [field for field in NHL_PROVIDER_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    officiating_present = _official_inputs_present(input_stats, NHL_OFFICIATING_INPUTS)
    social_present = [field for field in NHL_SOCIAL_CROWD_INPUTS if input_stats.get(field) is not None]
    live_present = [field for field in NHL_LIVE_BETTING_INPUTS if input_stats.get(field) is not None]

    team_lambda = (
        number("team_projected_goals") * 0.30
        + ((number("team_xg_for_per_game") + number("opponent_xg_against_per_game")) / 2) * 0.35
        + ((number("team_goals_for_per_game") + number("opponent_goals_against_per_game")) / 2) * 0.15
        + ((number("team_high_danger_chances_for_per_game") + number("opponent_high_danger_chances_against_per_game")) / 18) * 0.12
        + ((number("team_shots_for_per_game") + number("opponent_shots_against_per_game")) / 62) * 0.08
    )
    opponent_lambda = (
        number("opponent_projected_goals") * 0.30
        + ((number("opponent_xg_for_per_game") + number("team_xg_against_per_game")) / 2) * 0.35
        + ((number("opponent_goals_for_per_game") + number("team_goals_against_per_game")) / 2) * 0.15
        + ((number("opponent_high_danger_chances_for_per_game") + number("team_high_danger_chances_against_per_game")) / 18) * 0.12
        + ((number("opponent_shots_for_per_game") + number("team_shots_against_per_game")) / 62) * 0.08
    )

    time_decay_applied = False
    if input_stats.get("team_recent_xg_for_5") is not None and input_stats.get("opponent_recent_xg_for_5") is not None:
        team_lambda = team_lambda * 0.75 + number("team_recent_xg_for_5") * 0.25
        opponent_lambda = opponent_lambda * 0.75 + number("opponent_recent_xg_for_5") * 0.25
        time_decay_applied = True
    if input_stats.get("team_home_xg_for") is not None and str(input_stats.get("home_away") or "").lower() == "home":
        team_lambda = team_lambda * 0.88 + number("team_home_xg_for") * 0.12
    if input_stats.get("opponent_away_xg_for") is not None:
        opponent_lambda = opponent_lambda * 0.88 + number("opponent_away_xg_for") * 0.12

    goalie_risk_flags: list[str] = []
    goalie_adjustment_applied = True
    team_goalie_confirmed = truthy("team_goalie_confirmed")
    opponent_goalie_confirmed = truthy("opponent_goalie_confirmed")
    if not team_goalie_confirmed:
        goalie_risk_flags.append("team goalie unconfirmed")
        opponent_lambda += 0.12
    if not opponent_goalie_confirmed:
        goalie_risk_flags.append("opponent goalie unconfirmed")
        team_lambda += 0.12
    if _truthy_available(input_stats.get("backup_goalie_expected")):
        goalie_risk_flags.append("backup goalie risk")
        opponent_lambda += 0.18
    goalie_fatigue = number("goalie_fatigue_index")
    if goalie_fatigue >= 0.70:
        goalie_risk_flags.append("goalie fatigue")
        opponent_lambda += 0.08
    team_goalie_gsaax = number("team_starting_goalie_gsaax")
    opponent_goalie_gsaax = number("opponent_starting_goalie_gsaax")
    opponent_lambda += max(-0.18, min(0.18, -team_goalie_gsaax * 0.015))
    team_lambda += max(-0.18, min(0.18, -opponent_goalie_gsaax * 0.015))
    team_save = number("team_starting_goalie_save_percent", 0.910)
    opponent_save = number("opponent_starting_goalie_save_percent", 0.910)
    opponent_lambda += max(-0.12, min(0.12, (0.910 - team_save) * 5.0))
    team_lambda += max(-0.12, min(0.12, (0.910 - opponent_save) * 5.0))

    special_teams_adjustment_applied = True
    team_power_play_edge = (number("team_power_play_percent", 21) - (100 - number("opponent_penalty_kill_percent", 79))) / 100
    opponent_power_play_edge = (number("opponent_power_play_percent", 21) - (100 - number("team_penalty_kill_percent", 79))) / 100
    team_lambda += max(-0.12, min(0.12, team_power_play_edge * 0.8))
    opponent_lambda += max(-0.12, min(0.12, opponent_power_play_edge * 0.8))
    team_lambda += max(-0.08, min(0.08, (number("team_penalties_drawn_per_game", 3) - number("opponent_penalties_taken_per_game", 3)) * 0.025))
    opponent_lambda += max(-0.08, min(0.08, (number("opponent_penalties_drawn_per_game", 3) - number("team_penalties_taken_per_game", 3)) * 0.025))
    if officiating_present:
        pp_rate = number("referee_power_play_rate", 3.0)
        team_lambda += max(-0.08, min(0.08, (pp_rate - 3.0) * 0.025))
        opponent_lambda += max(-0.08, min(0.08, (pp_rate - 3.0) * 0.025))

    rest_edge = number("team_rest_days") - number("opponent_rest_days")
    team_lambda += max(-0.08, min(0.08, rest_edge * 0.025))
    opponent_lambda -= max(-0.06, min(0.06, rest_edge * 0.018))
    if _truthy_available(input_stats.get("team_back_to_back")):
        team_lambda -= 0.08
        goalie_risk_flags.append("team back to back fatigue")
    if _truthy_available(input_stats.get("opponent_back_to_back")):
        opponent_lambda -= 0.08
    injury_status = str(input_stats.get("injury_report_status") or "").lower()
    lineup_status = str(input_stats.get("lineup_status") or "").lower()
    if "scorer" in injury_status or "forward" in injury_status:
        team_lambda -= 0.15
    if "defense" in injury_status or "defender" in injury_status:
        opponent_lambda += 0.12
    if lineup_status not in {"confirmed", "posted", "official"}:
        team_lambda -= 0.06
        opponent_lambda -= 0.04

    probability_sanity_flags: list[str] = []
    uncapped_team_lambda = team_lambda
    uncapped_opponent_lambda = opponent_lambda
    team_lambda = max(0.40, min(5.6, team_lambda))
    opponent_lambda = max(0.40, min(5.6, opponent_lambda))
    if team_lambda != uncapped_team_lambda or opponent_lambda != uncapped_opponent_lambda:
        probability_sanity_flags.append("lambda capped")

    shared_intensity = _safe_float(input_stats.get("shared_intensity"))
    if shared_intensity is None:
        tempo = (number("team_shots_for_per_game") + number("opponent_shots_for_per_game")) / 64
        goalie_volatility = min(0.08, abs(team_save - opponent_save) * 0.8 + abs(team_goalie_gsaax - opponent_goalie_gsaax) * 0.006)
        shared_intensity = max(0.02, min(0.10, 0.035 + (tempo - 1.0) * 0.04 + goalie_volatility))
    score_matrix = apply_bivariate_hockey_adjustment(build_nhl_score_matrix(team_lambda, opponent_lambda), shared_intensity)
    first_period_matrix = apply_bivariate_hockey_adjustment(build_nhl_score_matrix(*estimate_nhl_period_lambdas(team_lambda, opponent_lambda, "first", _safe_float(input_stats.get("first_period_goal_share")))), min(0.08, shared_intensity))
    second_period_matrix = apply_bivariate_hockey_adjustment(build_nhl_score_matrix(*estimate_nhl_period_lambdas(team_lambda, opponent_lambda, "second", _safe_float(input_stats.get("second_period_goal_share")))), min(0.08, shared_intensity))
    third_period_matrix = apply_bivariate_hockey_adjustment(build_nhl_score_matrix(*estimate_nhl_period_lambdas(team_lambda, opponent_lambda, "third", _safe_float(input_stats.get("third_period_goal_share")))), min(0.08, shared_intensity))

    selection = payload.get("selection") or input_stats.get("selection")
    team = input_stats.get("team")
    opponent = input_stats.get("opponent")
    shootout_edge = max(-0.06, min(0.06, (team_goalie_gsaax - opponent_goalie_gsaax) * 0.006))
    matrix_for_market = score_matrix
    period_lambda_adjustment_applied = market_key.startswith(("first_period", "second_period", "third_period"))
    if market_key.startswith("first_period"):
        matrix_for_market = first_period_matrix
    elif market_key.startswith("second_period"):
        matrix_for_market = second_period_matrix
    elif market_key.startswith("third_period"):
        matrix_for_market = third_period_matrix

    if market_key == "moneyline":
        raw_model_probability = estimate_nhl_moneyline_probability(score_matrix, selection, team, opponent, shootout_edge)
    elif market_key == "three_way_moneyline":
        raw_model_probability = estimate_nhl_three_way_probability(score_matrix, selection, team, opponent)
    elif market_key == "regulation_moneyline":
        raw_model_probability = estimate_nhl_regulation_moneyline_probability(score_matrix, selection, team, opponent)
    elif market_key == "draw_no_bet":
        raw_model_probability = estimate_nhl_draw_no_bet_probability(score_matrix, selection, team, opponent)
    elif market_key in {"puckline", "spread", "alternate_puckline"}:
        line = _safe_float(input_stats.get("line") if input_stats.get("line") is not None else payload.get("line"), 0) or 0
        raw_model_probability = estimate_nhl_puckline_probability(score_matrix, line)
    elif market_key in {"total", "alternate_total", "first_period_total", "second_period_total", "third_period_total"}:
        total_line = _safe_float(input_stats.get("total_line") if input_stats.get("total_line") is not None else payload.get("total_line"), 0) or 0
        raw_model_probability = estimate_nhl_total_probability_from_score_matrix(matrix_for_market, total_line, selection)
    elif market_key in {"team_total", "first_period_team_total"}:
        team_total_line = _safe_float(input_stats.get("team_total_line") if input_stats.get("team_total_line") is not None else payload.get("team_total_line"), 0) or 0
        raw_model_probability = estimate_nhl_team_total_probability_from_score_matrix(matrix_for_market, team_total_line, selection)
    elif market_key in {"first_period_moneyline", "second_period_moneyline", "third_period_moneyline"}:
        raw_model_probability = estimate_nhl_three_way_probability(matrix_for_market, selection, team, opponent)
    elif market_key == "anytime_goal_scorer":
        goal_projection = number("player_goal_projection")
        minutes = max(1, number("player_minutes_projection", 15))
        raw_model_probability = max(0.03, min(0.75, 1 - math.exp(-goal_projection * minutes / 18)))
    elif market_key == "first_goal_scorer":
        raw_model_probability = max(0.03, min(0.32, number("player_first_goal_projection")))
    elif market_key == "player_prop":
        raw_model_probability = estimate_nhl_player_prop_probability(number("player_projection"), number("prop_line"))
    else:
        raw_model_probability = estimate_nhl_moneyline_probability(score_matrix, selection, team, opponent, shootout_edge)

    implied_probability = american_odds_to_implied_probability(odds_american)
    market_probability = _safe_probability(input_stats.get("no_vig_market_probability"))
    market_anchor_probability = market_probability if market_probability is not None else implied_probability if implied_probability is not None else 0.5
    projected_goal_differential = team_lambda - opponent_lambda
    confidence_hint = calculate_confidence(68, min(7, len(optional_present) * 0.15), min(4, len(provider_present) * 0.5))
    goalie_edge_quality = 0.6 if team_goalie_confirmed and opponent_goalie_confirmed and abs(team_goalie_gsaax - opponent_goalie_gsaax) >= 4 else 0.2
    calibration = calibrate_nhl_probability(
        raw_probability=raw_model_probability,
        market_anchor_probability=market_anchor_probability,
        market_anchor_is_no_vig=market_probability is not None,
        projected_goal_differential=projected_goal_differential,
        market_key=market_key,
        input_confidence_hint=confidence_hint,
        goalie_edge_quality=goalie_edge_quality,
    )
    if probability_sanity_flags:
        calibration["probability_sanity_flags"] = list(dict.fromkeys(calibration["probability_sanity_flags"] + probability_sanity_flags))
        calibration["probability_calibration_applied"] = True
    true_probability = calibration["final_probability"]

    confidence_adjustments: list[float] = [min(7, len(optional_present) * 0.15), min(4, len(provider_present) * 0.5)]
    if goalie_risk_flags:
        confidence_adjustments.append(-min(10, len(goalie_risk_flags) * 3))
    if lineup_status not in {"confirmed", "posted", "official"}:
        confidence_adjustments.append(-7)
    if abs(rest_edge) >= 2:
        confidence_adjustments.append(-3)
    if input_stats.get("best_available_odds") is None:
        confidence_adjustments.append(-3)
    book_count = _safe_float(input_stats.get("book_count"))
    if book_count is not None and book_count < 5:
        confidence_adjustments.append(-4)
    current_odds = _safe_float(input_stats.get("current_odds"))
    consensus_odds = _safe_float(input_stats.get("consensus_odds"))
    risk = "medium"
    if current_odds is not None and consensus_odds is not None and abs(current_odds - consensus_odds) >= 25:
        risk = "high"
        confidence_adjustments.append(-3)
    if officiating_present and number("official_sample_size") and number("official_sample_size") < 20:
        confidence_adjustments.append(-2)
    if market_key == "first_goal_scorer":
        risk = "high"
        confidence_adjustments.append(-8)
    if market_key in {"player_prop", "anytime_goal_scorer", "first_goal_scorer"}:
        if str(input_stats.get("player_starting_status") or "").lower() not in {"confirmed", "starting", "active"}:
            confidence_adjustments.append(-12)
        if number("player_minutes_projection") < 10:
            confidence_adjustments.append(-6)
    if calibration["probability_sanity_flags"]:
        confidence_adjustments.append(-min(6, len(calibration["probability_sanity_flags"]) * 2))
    confidence = calculate_confidence(68, *confidence_adjustments)

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
        risk = "high"
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
        risk = "high"
    if lineup_status not in {"confirmed", "posted", "official"}:
        no_bet_flags.append("lineup not confirmed")
    if goalie_risk_flags and market_key not in {"total", "alternate_total"}:
        no_bet_flags.append(goalie_risk_flags[0])
    if market_key in {"player_prop", "anytime_goal_scorer", "first_goal_scorer"} and str(input_stats.get("player_starting_status") or "").lower() not in {"confirmed", "starting", "active"}:
        no_bet_flags.append("player starting status unconfirmed")
    if market_key == "first_goal_scorer" and edge is not None and edge < 8:
        no_bet_flags.append("high variance market")
    if current_odds is not None and consensus_odds is not None and abs(current_odds - consensus_odds) >= 35:
        no_bet_flags.append("market disagreement too high")

    suggested = 0.0
    if not no_bet_flags:
        suggested = calculate_suggested_stake(
            bankroll=bankroll,
            american_odds=odds_american,
            true_probability=true_probability,
            risk_profile=risk_profile,
            confidence=confidence,
        )
        risk = "low" if edge is not None and edge >= 5 else risk

    regulation_team_win, regulation_draw_probability, regulation_opponent_win = _nhl_matrix_parts(score_matrix)
    overtime_probability = regulation_draw_probability
    shootout_adjustment_probability = overtime_probability * (0.50 + shootout_edge)
    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "final_probability": true_probability,
        "model_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": risk,
        "suggested_stake": suggested,
        "raw_model_probability": calibration["raw_model_probability"],
        "calibrated_model_probability": calibration["calibrated_model_probability"],
        "probability_calibration_applied": calibration["probability_calibration_applied"],
        "probability_sanity_flags": calibration["probability_sanity_flags"],
        "probability_cap_reason": calibration["probability_cap_reason"],
        "market_anchor_probability": calibration["market_anchor_probability"],
        "team_lambda": round(team_lambda, 3),
        "opponent_lambda": round(opponent_lambda, 3),
        "projected_team_goals": round(team_lambda, 3),
        "projected_opponent_goals": round(opponent_lambda, 3),
        "projected_total_goals": round(team_lambda + opponent_lambda, 3),
        "projected_goal_differential": round(projected_goal_differential, 3),
        "regulation_draw_probability": regulation_draw_probability,
        "overtime_probability": overtime_probability,
        "shootout_adjustment_probability": shootout_adjustment_probability,
        "bivariate_poisson_adjustment_applied": shared_intensity > 0,
        "goalie_adjustment_applied": goalie_adjustment_applied,
        "goalie_risk_flags": goalie_risk_flags,
        "special_teams_adjustment_applied": special_teams_adjustment_applied,
        "period_lambda_adjustment_applied": period_lambda_adjustment_applied,
        "time_decay_applied": time_decay_applied,
        "nhl_input_contract": deepcopy(NHL_INPUT_CONTRACT),
        "input_coverage": {
            "required_core_present": list(NHL_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": NHL_REQUIRED_MARKET_SPECIFIC_INPUTS.get(market_key, []),
            "optional_enrichment_present": optional_present,
            "optional_enrichment_missing": [field for field in NHL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
            "provider_enrichment_present": provider_present,
            "officiating_present": officiating_present,
            "referee_present": officiating_present,
            "social_crowd_present": social_present,
            "live_betting_present": live_present,
        },
        "provider_enrichment": {
            "provider_enrichment_present": provider_present,
            "provider_status": "available" if provider_present else "not_provided",
        },
        "no_bet_flags": no_bet_flags,
    }


def _estimate_tennis_markov_model(
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    core_missing = _tennis_full_inputs_missing(input_stats, payload)
    market_missing = _tennis_market_specific_missing(market, input_stats, payload)
    if core_missing or market_missing:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    optional_present = [field for field in TENNIS_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    provider_present = [field for field in TENNIS_PROVIDER_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    officiating_present = _official_inputs_present(input_stats, TENNIS_OFFICIATING_INPUTS)
    social_present = [field for field in TENNIS_SOCIAL_CROWD_INPUTS if input_stats.get(field) is not None]
    live_present = [field for field in TENNIS_LIVE_BETTING_INPUTS if input_stats.get(field) is not None]

    best_of_sets = int(max(3, min(5, number("best_of_sets", 3))))
    strength = estimate_tennis_base_strength(input_stats)
    player_serve_point = estimate_tennis_serve_point_probability(input_stats, "player")
    opponent_serve_point = estimate_tennis_serve_point_probability(input_stats, "opponent")
    player_hold = estimate_tennis_hold_probability_from_points(player_serve_point)
    opponent_hold = estimate_tennis_hold_probability_from_points(opponent_serve_point)
    player_break = max(0.05, min(0.55, 1 - opponent_hold))
    opponent_break = max(0.05, min(0.55, 1 - player_hold))
    serve_edge = player_hold - opponent_hold
    return_edge = player_break - opponent_break
    tiebreak_probability = estimate_tennis_tiebreak_probability(player_serve_point, opponent_serve_point, input_stats)
    set_probability = estimate_tennis_set_probability(player_hold, opponent_hold, tiebreak_probability)
    elo_gap = strength["player_strength_rating"] - strength["opponent_strength_rating"]
    set_probability = max(0.18, min(0.82, set_probability + max(-0.06, min(0.06, elo_gap / 2800))))

    surface_adjustment_applied = True
    fatigue_adjustment_applied = input_stats.get("player_fatigue_index") is not None or input_stats.get("opponent_fatigue_index") is not None
    injury_adjustment_applied = input_stats.get("player_injury_status") is not None or input_stats.get("opponent_injury_status") is not None
    weather_adjustment_applied = input_stats.get("weather_wind_mph") is not None or input_stats.get("weather_temperature") is not None
    fatigue_edge = number("opponent_fatigue_index") - number("player_fatigue_index")
    set_probability += max(-0.035, min(0.035, fatigue_edge * 0.02))
    player_injury_status = str(input_stats.get("player_injury_status") or "").lower()
    opponent_injury_status = str(input_stats.get("opponent_injury_status") or "").lower()
    if any(word in player_injury_status for word in ["questionable", "injured", "limited"]):
        set_probability -= 0.045
    if any(word in opponent_injury_status for word in ["questionable", "injured", "limited"]):
        set_probability += 0.035
    if input_stats.get("player_surface_win_percent") is not None:
        set_probability += max(-0.035, min(0.035, ((number("player_surface_win_percent", 50) - number("opponent_surface_win_percent", 50)) / 100) * 0.08))
    set_probability = max(0.18, min(0.82, set_probability))
    match_probability = estimate_tennis_match_probability(set_probability, best_of_sets)
    first_set_probability = max(0.18, min(0.82, set_probability * 0.92 + 0.04))
    score_distribution = estimate_tennis_set_score_distribution(set_probability, best_of_sets)
    game_distribution = estimate_tennis_game_margin_distribution(match_probability, set_probability, best_of_sets)

    selection = str(payload.get("selection") or input_stats.get("selection") or input_stats.get("player") or "").lower()
    opponent_text = str(input_stats.get("opponent") or "").lower()
    if market_key in {"moneyline", "match_winner"}:
        raw_model_probability = 1 - match_probability if opponent_text and opponent_text in selection else match_probability
    elif market_key == "first_set_moneyline":
        raw_model_probability = 1 - first_set_probability if opponent_text and opponent_text in selection else first_set_probability
    elif market_key == "set_handicap":
        line = _safe_float(input_stats.get("line") if input_stats.get("line") is not None else payload.get("line"), 0) or 0
        expected_set_margin = (set_probability - 0.5) * (best_of_sets if best_of_sets >= 5 else 2.2)
        raw_model_probability = tennis_logistic(expected_set_margin + line, 0.85)
    elif market_key == "game_handicap":
        line = _safe_float(input_stats.get("line") if input_stats.get("line") is not None else payload.get("line"), 0) or 0
        raw_model_probability = tennis_logistic(game_distribution["mean_margin"] + line, game_distribution["volatility"])
    elif market_key == "total_games":
        total_line = _safe_float(input_stats.get("total_line") if input_stats.get("total_line") is not None else payload.get("total_line"), 0) or 0
        raw_model_probability = estimate_tennis_total_games_probability(total_line, selection, game_distribution)
    elif market_key == "first_set_total_games":
        total_line = _safe_float(input_stats.get("total_line") if input_stats.get("total_line") is not None else payload.get("total_line"), 0) or 0
        raw_model_probability = estimate_tennis_first_set_total_probability(total_line, selection, set_probability)
    elif market_key == "correct_score":
        raw_model_probability = estimate_tennis_correct_score_probability(score_distribution, input_stats.get("correct_score_selection") or payload.get("correct_score_selection"))
    elif market_key in {"player_prop", "aces", "double_faults", "break_points", "service_games_won", "return_games_won"}:
        raw_model_probability = estimate_tennis_player_prop_probability(number("player_projection"), number("prop_line"))
    else:
        raw_model_probability = match_probability

    implied_probability = american_odds_to_implied_probability(odds_american)
    market_probability = _safe_probability(input_stats.get("no_vig_market_probability"))
    market_anchor_probability = market_probability if market_probability is not None else implied_probability if implied_probability is not None else 0.5
    confidence_hint = calculate_confidence(68, min(7, len(optional_present) * 0.15), min(4, len(provider_present) * 0.5))
    calibration = calibrate_tennis_probability(
        raw_probability=raw_model_probability,
        market_anchor_probability=market_anchor_probability,
        market_anchor_is_no_vig=market_probability is not None,
        elo_gap=elo_gap,
        surface_edge=strength["player_surface_edge"],
        market_key=market_key,
        input_confidence_hint=confidence_hint,
    )
    true_probability = calibration["final_probability"]

    confidence_adjustments: list[float] = [min(7, len(optional_present) * 0.15), min(4, len(provider_present) * 0.5)]
    risk = "medium"
    no_bet_flags: list[str] = []
    if any(word in player_injury_status for word in ["questionable", "injured", "limited"]):
        confidence_adjustments.append(-9)
        no_bet_flags.append("injury risk")
    if number("player_retirement_risk") >= 0.25:
        confidence_adjustments.append(-10)
        no_bet_flags.append("retirement risk")
    if number("player_fatigue_index") >= 0.70:
        confidence_adjustments.append(-5)
        no_bet_flags.append("fatigue risk")
    if input_stats.get("best_available_odds") is None:
        confidence_adjustments.append(-3)
    book_count = _safe_float(input_stats.get("book_count"))
    if book_count is not None and book_count < 5:
        confidence_adjustments.append(-4)
    current_odds = _safe_float(input_stats.get("current_odds"))
    consensus_odds = _safe_float(input_stats.get("consensus_odds"))
    if current_odds is not None and consensus_odds is not None and abs(current_odds - consensus_odds) >= 25:
        confidence_adjustments.append(-3)
        risk = "high"
        no_bet_flags.append("market disagreement")
    if weather_adjustment_applied and number("weather_wind_mph") >= 18 and market_key in {"aces", "player_prop", "service_games_won"}:
        confidence_adjustments.append(-5)
        no_bet_flags.append("weather risk for serve props")
    if market_key == "correct_score":
        confidence_adjustments.append(-8)
        risk = "high"
    if market_key in {"player_prop", "aces", "double_faults", "break_points", "service_games_won", "return_games_won"} and str(input_stats.get("player_starting_status") or "").lower() not in {"confirmed", "active", "starting"}:
        confidence_adjustments.append(-12)
        no_bet_flags.append("player starting status unconfirmed")
    if calibration["probability_sanity_flags"]:
        confidence_adjustments.append(-min(6, len(calibration["probability_sanity_flags"]) * 2))
    confidence = calculate_confidence(68, *confidence_adjustments)
    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
        risk = "high"
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
        risk = "high"
    if market_key == "correct_score" and edge is not None and edge < 8:
        no_bet_flags.append("correct score high variance")

    suggested = 0.0
    if not no_bet_flags:
        suggested = calculate_suggested_stake(
            bankroll=bankroll,
            american_odds=odds_american,
            true_probability=true_probability,
            risk_profile=risk_profile,
            confidence=confidence,
        )
        risk = "low" if edge is not None and edge >= 5 else risk

    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "final_probability": true_probability,
        "model_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": risk,
        "suggested_stake": suggested,
        "raw_model_probability": calibration["raw_model_probability"],
        "calibrated_model_probability": calibration["calibrated_model_probability"],
        "probability_calibration_applied": calibration["probability_calibration_applied"],
        "probability_sanity_flags": calibration["probability_sanity_flags"],
        "probability_cap_reason": calibration["probability_cap_reason"],
        "market_anchor_probability": calibration["market_anchor_probability"],
        "player_strength_rating": strength["player_strength_rating"],
        "opponent_strength_rating": strength["opponent_strength_rating"],
        "player_surface_edge": strength["player_surface_edge"],
        "serve_edge": serve_edge,
        "return_edge": return_edge,
        "player_hold_probability": player_hold,
        "opponent_hold_probability": opponent_hold,
        "player_break_probability": player_break,
        "opponent_break_probability": opponent_break,
        "player_set_probability": set_probability,
        "player_match_probability": match_probability,
        "first_set_probability": first_set_probability,
        "tiebreak_probability": tiebreak_probability,
        "markov_model_applied": True,
        "surface_adjustment_applied": surface_adjustment_applied,
        "fatigue_adjustment_applied": fatigue_adjustment_applied,
        "injury_adjustment_applied": injury_adjustment_applied,
        "weather_adjustment_applied": weather_adjustment_applied,
        "tennis_input_contract": deepcopy(TENNIS_INPUT_CONTRACT),
        "input_coverage": {
            "required_core_present": list(TENNIS_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": TENNIS_REQUIRED_MARKET_SPECIFIC_INPUTS.get(market_key, []),
            "optional_enrichment_present": optional_present,
            "optional_enrichment_missing": [field for field in TENNIS_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
            "provider_enrichment_present": provider_present,
            "officiating_present": officiating_present,
            "referee_present": officiating_present,
            "social_crowd_present": social_present,
            "live_betting_present": live_present,
        },
        "provider_enrichment": {
            "provider_enrichment_present": provider_present,
            "provider_status": "available" if provider_present else "not_provided",
        },
        "no_bet_flags": list(dict.fromkeys(no_bet_flags)),
    }


def _estimate_mlb_negative_binomial_model(
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    core_missing = _mlb_full_inputs_missing(input_stats, payload)
    market_missing = _mlb_market_specific_missing(market, input_stats, payload)
    if core_missing or market_missing:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    optional_present = [field for field in MLB_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    provider_present = [field for field in MLB_PROVIDER_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    officiating_present = _official_inputs_present(input_stats, MLB_OFFICIATING_INPUTS)
    social_present = [field for field in MLB_SOCIAL_CROWD_INPUTS if input_stats.get(field) is not None]
    live_present = [field for field in MLB_LIVE_BETTING_INPUTS if input_stats.get(field) is not None]

    team_runs = number("team_projected_runs")
    opponent_runs = number("opponent_projected_runs")
    team_starter_quality = ((4.2 - number("opponent_starting_pitcher_fip", 4.2)) + (4.2 - number("opponent_starting_pitcher_xfip", 4.2))) * 0.10
    opponent_starter_quality = ((4.2 - number("team_starting_pitcher_fip", 4.2)) + (4.2 - number("team_starting_pitcher_xfip", 4.2))) * 0.10
    offense_adjustment = (
        (number("team_woba", 0.320) - number("opponent_woba", 0.320)) * 2.2
        + (number("team_xwoba", 0.320) - number("opponent_xwoba", 0.320)) * 1.8
        + (number("team_wrc_plus", 100) - number("opponent_wrc_plus", 100)) * 0.012
        + (number("team_iso", 0.160) - number("opponent_iso", 0.160)) * 1.2
    )
    bullpen_adjustment = (
        (number("opponent_bullpen_fip", 4.1) - number("team_bullpen_fip", 4.1)) * 0.10
        + (number("opponent_bullpen_era", 4.1) - number("team_bullpen_era", 4.1)) * 0.06
    )
    usage_adjustment = (number("opponent_bullpen_recent_usage") - number("team_bullpen_recent_usage")) * 0.04
    park_adjustment = (number("park_factor_runs", 1.0) - 1.0) * 1.5
    weather_adjustment = 0.0
    roof_status = str(input_stats.get("roof_status") or "").strip().lower()
    if roof_status not in {"closed", "dome"}:
        weather_adjustment += max(-0.35, min(0.35, (number("weather_temperature", 72) - 72) * 0.01))
        wind = number("weather_wind_mph")
        direction = str(input_stats.get("weather_wind_direction") or "").lower()
        if wind >= 12:
            weather_adjustment += 0.25 if "out" in direction else -0.15 if "in" in direction else 0.05
    if str(input_stats.get("lineup_status") or "").strip().lower() not in {"confirmed", "posted", "official"}:
        team_runs -= 0.18
        opponent_runs -= 0.10
    if str(input_stats.get("injury_report_status") or "").strip().lower() not in {"clean", "clear", "healthy", "normal", "available"}:
        team_runs -= 0.12

    team_runs += team_starter_quality + offense_adjustment * 0.55 + bullpen_adjustment * 0.55 + usage_adjustment + park_adjustment + weather_adjustment
    opponent_runs += opponent_starter_quality - offense_adjustment * 0.45 - bullpen_adjustment * 0.45 - usage_adjustment + park_adjustment + weather_adjustment

    if input_stats.get("team_recent_woba_14") is not None and input_stats.get("opponent_recent_woba_14") is not None:
        team_runs += (number("team_recent_woba_14", 0.320) - number("opponent_recent_woba_14", 0.320)) * 1.1
    if input_stats.get("team_vs_pitcher_handedness_woba") is not None:
        team_runs += (number("team_vs_pitcher_handedness_woba", 0.320) - 0.320) * 1.0
    if input_stats.get("opponent_vs_pitcher_handedness_woba") is not None:
        opponent_runs += (number("opponent_vs_pitcher_handedness_woba", 0.320) - 0.320) * 1.0
    team_runs += number("team_defensive_runs_saved") * 0.005 - number("opponent_defensive_runs_saved") * 0.003
    opponent_runs += number("opponent_defensive_runs_saved") * 0.005 - number("team_defensive_runs_saved") * 0.003
    if officiating_present:
        umpire_over = number("umpire_over_rate", 0.5)
        strike_impact = number("umpire_strikeout_rate_impact", 0)
        run_env_adjustment = (umpire_over - 0.5) * 0.30 - strike_impact * 0.10
        team_runs += run_env_adjustment
        opponent_runs += run_env_adjustment

    team_runs = max(1.8, min(8.5, team_runs))
    opponent_runs = max(1.8, min(8.5, opponent_runs))
    if market_key.startswith("first_5"):
        team_starter_ip = max(1.0, min(6.0, number("team_starting_pitcher_innings_projection", 5.2)))
        opponent_starter_ip = max(1.0, min(6.0, number("opponent_starting_pitcher_innings_projection", 5.2)))
        team_runs = max(0.8, min(5.0, team_runs * 0.52 + (6.0 - opponent_starter_ip) * 0.05))
        opponent_runs = max(0.8, min(5.0, opponent_runs * 0.52 + (6.0 - team_starter_ip) * 0.05))

    team_dispersion = number("team_run_dispersion", 8.0)
    opponent_dispersion = number("opponent_run_dispersion", 8.0)
    team_dist = estimate_run_distribution(team_runs, team_dispersion)
    opponent_dist = estimate_run_distribution(opponent_runs, opponent_dispersion)
    selection = payload.get("selection") or input_stats.get("selection")

    if market_key in {"moneyline", "first_5_moneyline"}:
        raw_model_probability = estimate_moneyline_probability_from_runs(team_dist, opponent_dist)
    elif market_key in {"runline", "first_5_runline", "alt_line"}:
        line = _safe_float(input_stats.get("line") if input_stats.get("line") is not None else payload.get("line"), 0) or 0
        raw_model_probability = estimate_runline_cover_probability(team_dist, opponent_dist, line)
    elif market_key in {"total", "first_5_total"}:
        total_line = _safe_float(input_stats.get("total_line") if input_stats.get("total_line") is not None else payload.get("total_line"), 0) or 0
        raw_model_probability = estimate_total_probability(team_dist, opponent_dist, total_line, selection)
    elif market_key == "team_total":
        team_total_line = _safe_float(input_stats.get("team_total_line") if input_stats.get("team_total_line") is not None else payload.get("team_total_line"), 0) or 0
        raw_model_probability = estimate_team_total_probability(team_dist, team_total_line, selection)
    elif market_key == "player_prop":
        projection = number("player_projection")
        prop_line = number("prop_line")
        scale = max(0.75, abs(prop_line) * 0.22)
        raw_model_probability = _logistic_probability(projection - prop_line, scale)
    else:
        raw_model_probability = estimate_moneyline_probability_from_runs(team_dist, opponent_dist)

    implied_probability = american_odds_to_implied_probability(odds_american)
    market_probability = _safe_probability(input_stats.get("no_vig_market_probability"))
    market_anchor_probability = market_probability if market_probability is not None else implied_probability if implied_probability is not None else 0.5
    projected_run_differential = team_runs - opponent_runs
    calibration = calibrate_mlb_probability(
        raw_probability=raw_model_probability,
        market_anchor_probability=market_anchor_probability,
        market_anchor_is_no_vig=market_probability is not None,
        projected_run_differential=projected_run_differential,
        input_confidence_hint=68,
    )
    true_probability = calibration["final_probability"]

    confidence_adjustments: list[float] = [min(8, len(optional_present) * 0.18), min(4, len(provider_present) * 0.5)]
    pitcher_status = str(input_stats.get("team_starting_pitcher_status") or input_stats.get("starting_pitcher_status") or "confirmed").lower()
    lineup_status = str(input_stats.get("lineup_status") or "").lower()
    team_bullpen_rest = str(input_stats.get("team_bullpen_rest_status") or "").lower()
    if pitcher_status in {"scratched", "unknown", "unconfirmed"}:
        confidence_adjustments.append(-20)
    if lineup_status not in {"confirmed", "posted", "official"}:
        confidence_adjustments.append(-6)
    if team_bullpen_rest in {"tired", "thin", "overworked"} or number("team_bullpen_recent_usage") >= 4:
        confidence_adjustments.append(-5)
    if roof_status not in {"closed", "dome"} and number("weather_wind_mph") >= 15:
        confidence_adjustments.append(-4 if market_key in {"total", "first_5_total", "team_total"} else -2)
    book_count = _safe_float(input_stats.get("book_count"))
    if book_count is not None and book_count < 5:
        confidence_adjustments.append(-4)
    if input_stats.get("best_available_odds") is None:
        confidence_adjustments.append(-3)
    current_odds = _safe_float(input_stats.get("current_odds"))
    consensus_odds = _safe_float(input_stats.get("consensus_odds"))
    risk = "medium"
    if current_odds is not None and consensus_odds is not None and abs(current_odds - consensus_odds) >= 25:
        risk = "high"
        confidence_adjustments.append(-3)
    if market_key == "player_prop" and str(input_stats.get("player_starting_status") or "").lower() not in {"confirmed", "starting", "active"}:
        confidence_adjustments.append(-10)
    if calibration["probability_sanity_flags"]:
        confidence_adjustments.append(-min(8, 2 * len(calibration["probability_sanity_flags"])))
    confidence = calculate_confidence(68, *confidence_adjustments)

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if pitcher_status in {"scratched", "unknown", "unconfirmed"}:
        no_bet_flags.append("starting pitcher uncertainty")
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
        risk = "high"
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
        risk = "high"
    if market_key == "player_prop" and str(input_stats.get("player_starting_status") or "").lower() not in {"confirmed", "starting", "active"}:
        no_bet_flags.append("player starting status unconfirmed")
    if current_odds is not None and consensus_odds is not None and abs(current_odds - consensus_odds) >= 35:
        no_bet_flags.append("market disagreement too high")

    suggested = 0.0
    if not no_bet_flags:
        suggested = calculate_suggested_stake(
            bankroll=bankroll,
            american_odds=odds_american,
            true_probability=true_probability,
            risk_profile=risk_profile,
            confidence=confidence,
        )
        risk = "low" if edge is not None and edge >= 5 else risk

    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "final_probability": true_probability,
        "model_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": risk,
        "suggested_stake": suggested,
        "raw_model_probability": calibration["raw_model_probability"],
        "calibrated_model_probability": calibration["calibrated_model_probability"],
        "probability_calibration_applied": calibration["probability_calibration_applied"],
        "probability_sanity_flags": calibration["probability_sanity_flags"],
        "probability_cap_reason": calibration["probability_cap_reason"],
        "market_anchor_probability": calibration["market_anchor_probability"],
        "projected_team_runs": round(team_runs, 2),
        "projected_opponent_runs": round(opponent_runs, 2),
        "projected_total_runs": round(team_runs + opponent_runs, 2),
        "projected_run_differential": round(projected_run_differential, 2),
        "mlb_input_contract": deepcopy(MLB_INPUT_CONTRACT),
        "input_coverage": {
            "required_core_present": list(MLB_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": MLB_REQUIRED_MARKET_SPECIFIC_INPUTS.get(market_key, []),
            "optional_enrichment_present": optional_present,
            "optional_enrichment_missing": [field for field in MLB_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
            "provider_enrichment_present": provider_present,
            "officiating_present": officiating_present,
            "umpire_present": officiating_present,
            "referee_present": officiating_present,
            "social_crowd_present": social_present,
            "live_betting_present": live_present,
        },
        "provider_enrichment": {
            "provider_enrichment_present": provider_present,
            "provider_status": "available" if provider_present else "not_provided",
        },
        "no_bet_flags": no_bet_flags,
    }


def _estimate_college_football_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _college_football_full_inputs_missing(input_stats, payload) + _college_football_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    selected_home = selection_text == str(input_stats.get("home_team") or "").strip().lower()
    selected_away = selection_text == str(input_stats.get("away_team") or "").strip().lower()
    if not selected_home and not selected_away:
        selected_home = str(input_stats.get("team") or "").strip().lower() == str(input_stats.get("home_team") or "").strip().lower()

    home_drive = (
        (number("home_offensive_epa_per_play") - number("away_defensive_epa_per_play")) * 22
        + (number("home_success_rate") - number("away_defensive_success_rate_allowed")) * 16
        + (number("home_explosiveness") - number("away_explosiveness_allowed")) * 18
        + (number("home_points_per_drive") - number("away_points_allowed_per_drive")) * 2.4
        + (number("home_red_zone_td_rate") - number("away_red_zone_td_rate_allowed")) * 5.5
        + (number("home_havoc_rate") - number("away_havoc_allowed")) * 0.08
    )
    away_drive = (
        (number("away_offensive_epa_per_play") - number("home_defensive_epa_per_play")) * 22
        + (number("away_success_rate") - number("home_defensive_success_rate_allowed")) * 16
        + (number("away_explosiveness") - number("home_explosiveness_allowed")) * 18
        + (number("away_points_per_drive") - number("home_points_allowed_per_drive")) * 2.4
        + (number("away_red_zone_td_rate") - number("home_red_zone_td_rate_allowed")) * 5.5
        + (number("away_havoc_rate") - number("home_havoc_allowed")) * 0.08
    )
    home_field = 0 if input_stats.get("neutral_site") else number("home_field_advantage", 3.0)
    projected_margin = home_drive - away_drive + home_field
    projected_margin += (number("home_turnover_margin") - number("away_turnover_margin")) * 0.75
    projected_margin += (number("home_qb_rating") - number("away_qb_rating")) * 0.045
    projected_margin += (number("home_qb_injury_adjustment") - number("away_qb_injury_adjustment")) * 1.25
    projected_margin += (number("home_offensive_line_rating") - number("away_offensive_line_rating")) * 0.035
    projected_margin += (number("home_defensive_line_rating") - number("away_defensive_line_rating")) * 0.035
    projected_margin += (number("home_special_teams_rating") - number("away_special_teams_rating")) * 0.02
    projected_margin += (number("home_strength_of_schedule") - number("away_strength_of_schedule")) * 0.20
    projected_margin += (number("away_rank", 70) - number("home_rank", 70)) * 0.045
    projected_margin += (number("home_power_rating") - number("away_power_rating")) * 0.075
    projected_margin += (number("home_conference_strength") - number("away_conference_strength")) * 0.30
    projected_margin += max(-1.0, min(1.0, (number("home_rest_days") - number("away_rest_days")) * 0.18))
    projected_margin -= max(-0.9, min(0.9, (number("home_travel_fatigue") - number("away_travel_fatigue")) * 0.35))

    pace_seconds = max(20.0, min(35.0, (number("home_pace_seconds_per_play", 26.5) + number("away_pace_seconds_per_play", 26.5)) / 2))
    plays = max(55.0, min(92.0, (number("home_plays_per_game", 70) + number("away_plays_per_game", 70)) / 2))
    tempo_boost = (70 - plays) * -0.08 + (26.5 - pace_seconds) * 0.25
    base_total = 48.0 + ((home_drive + away_drive) * 1.05) + tempo_boost
    base_total += (number("home_explosiveness") + number("away_explosiveness") - 0.28) * 18
    base_total += (number("home_points_per_drive") + number("away_points_per_drive") - 4.8) * 2.2
    wind = number("weather_wind_mph", 0)
    precip = str(input_stats.get("weather_precipitation") or "").strip().lower()
    if wind >= 15:
        base_total -= min(6.0, (wind - 12) * 0.35)
    if precip not in {"", "none", "no", "false", "0", "clear"}:
        base_total -= 2.0
    projected_total = max(31.0, min(82.0, base_total))
    selected_margin = projected_margin if selected_home else -projected_margin
    projected_team_points = (projected_total / 2) + (selected_margin / 2)
    projected_opponent_points = projected_total - projected_team_points

    raw_model_probability = _logistic_probability(selected_margin, 9.8)
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    total_line = _safe_float(payload.get("total_line"), _safe_float(input_stats.get("total_line")))
    if market_key in {"spread", "first_half_spread", "first_quarter_spread", "alt_spread"}:
        period_scale = 0.50 if "first_half" in market_key else 0.24 if "first_quarter" in market_key else 1.0
        raw_model_probability = _logistic_probability((selected_margin * period_scale) + (line or 0), 10.5 * max(0.48, period_scale))
    elif market_key in {"total", "first_half_total", "first_quarter_total", "alt_total"}:
        period_scale = 0.50 if "first_half" in market_key else 0.24 if "first_quarter" in market_key else 1.0
        target = total_line if total_line is not None else projected_total * period_scale
        over_probability = _logistic_probability((projected_total * period_scale) - target, 9.8 * max(0.48, period_scale))
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"team_total", "alt_team_total"}:
        target = total_line if total_line is not None else projected_team_points
        over_probability = _logistic_probability(projected_team_points - target, 7.5)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"first_half_moneyline", "first_quarter_moneyline"}:
        period_scale = 0.50 if market_key == "first_half_moneyline" else 0.24
        raw_model_probability = _logistic_probability(selected_margin * period_scale, 7.5 * max(0.55, period_scale))
    elif market_key in COLLEGE_FOOTBALL_PROP_MARKETS:
        projection_map = {
            "player_passing_yards": "player_passing_yards_projection",
            "player_passing_tds": "player_passing_tds_projection",
            "player_interceptions": "player_interceptions_projection",
            "player_rushing_yards": "player_rushing_yards_projection",
            "player_rushing_tds": "player_rushing_tds_projection",
            "player_receiving_yards": "player_receiving_yards_projection",
            "player_receptions": "player_receptions_projection",
        }
        if market_key == "player_anytime_td":
            raw_model_probability = max(0.03, min(0.82, number("player_anytime_td_probability", 0.33)))
        else:
            projection = number(projection_map.get(market_key, "player_passing_yards_projection"), 40)
            target = line if line is not None else projection
            stddev = max(1.0, abs(projection) * (0.28 if "tds" not in market_key and "interceptions" not in market_key else 0.55))
            over_probability = 1 - _normal_cdf(target, mean=projection, stddev=stddev)
            raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability

    no_vig_anchor = _safe_float(input_stats.get("no_vig_market_probability"))
    if no_vig_anchor is not None and no_vig_anchor > 1:
        no_vig_anchor = no_vig_anchor / 100
    market_anchor = max(0.01, min(0.99, no_vig_anchor)) if no_vig_anchor is not None else None
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.06, min(0.94, calibrated_probability))
    sanity_flags = ["college football probability cap applied"] if true_probability != calibrated_probability else []

    confidence = 72.0
    risk_flags = []
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 3
        risk_flags.append("book count too low")
    if wind >= 15:
        confidence -= 5 if market_key in {"total", "first_half_total", "first_quarter_total", *COLLEGE_FOOTBALL_PROP_MARKETS} else 2
        risk_flags.append("weather sensitivity")
    if precip not in {"", "none", "no", "false", "0", "clear"}:
        confidence -= 4
        risk_flags.append("precipitation volatility")
    if abs(number("home_qb_injury_adjustment")) >= 1 or abs(number("away_qb_injury_adjustment")) >= 1:
        confidence -= 6
        risk_flags.append("QB injury sensitivity")
    if input_stats.get("blowout_risk"):
        confidence -= 5
        risk_flags.append("blowout risk")
    if input_stats.get("garbage_time_risk"):
        confidence -= 4
        risk_flags.append("garbage-time risk")
    if input_stats.get("tempo_volatility"):
        confidence -= 3
        risk_flags.append("tempo volatility")
    if market_key in COLLEGE_FOOTBALL_PROP_MARKETS:
        confidence -= 3
        if number("player_snap_share", 0) < 0.45:
            confidence -= 12
            risk_flags.append("prop snap-share fragility")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=true_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)

    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "final_probability": true_probability,
        "model_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested,
        "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "ncaaf college football sanity cap" if sanity_flags else None,
        "market_anchor_probability": market_anchor,
        "league_calibration_applied": "ncaaf",
        "projected_margin": round(projected_margin, 2),
        "projected_total": round(projected_total, 2),
        "projected_team_points": round(projected_team_points, 2),
        "projected_opponent_points": round(projected_opponent_points, 2),
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(COLLEGE_FOOTBALL_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": COLLEGE_FOOTBALL_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in COLLEGE_FOOTBALL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in COLLEGE_FOOTBALL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {"provider_status": "not_provided", "provider_enrichment_present": []},
        "no_bet_flags": no_bet_flags,
    }


def _cricket_format_calibration(raw_format: Any) -> dict[str, Any]:
    fmt = str(raw_format or "").strip().lower().replace("-", "_").replace(" ", "_")
    if fmt in {"ipl", "indian_premier_league"}:
        return {"format": "ipl", "baseline_total": 174.0, "volatility": 18.0, "confidence_base": 74.0, "overs": 20.0}
    if fmt in {"t20", "t20_cricket", "bbl", "big_bash", "cpl", "psl", "the_hundred"}:
        return {"format": "t20", "baseline_total": 168.0, "volatility": 19.0, "confidence_base": 72.0, "overs": 20.0}
    if fmt in {"odi", "one_day", "one_day_cricket"}:
        return {"format": "odi", "baseline_total": 286.0, "volatility": 27.0, "confidence_base": 70.0, "overs": 50.0}
    if fmt in {"test", "test_cricket"}:
        return {"format": "test", "baseline_total": 330.0, "volatility": 38.0, "confidence_base": 66.0, "overs": 90.0}
    return {"format": "unknown", "baseline_total": 168.0, "volatility": 22.0, "confidence_base": 68.0, "overs": 20.0}


def _f1_session_calibration(raw_session: Any) -> str:
    text = str(raw_session or "").strip().lower()
    if "qual" in text:
        return "qualifying"
    if "sprint" in text:
        return "sprint"
    if "practice" in text:
        return "practice"
    if "race" in text:
        return "race"
    return "unknown"


def _f1_circuit_calibration(raw_track_type: Any) -> str:
    text = str(raw_track_type or "").strip().lower()
    if "street" in text:
        return "street"
    if "hybrid" in text or "semi" in text:
        return "hybrid"
    if "permanent" in text or "road" in text:
        return "permanent"
    return "unknown"


def _f1_weather_calibration(weather: Any, rain_probability: float) -> str:
    text = str(weather or "").strip().lower()
    if "wet" in text or "rain" in text or rain_probability >= 0.55:
        return "wet"
    if "mixed" in text or rain_probability >= 0.25:
        return "mixed"
    if "dry" in text or rain_probability < 0.25:
        return "dry"
    return "unknown"


def _estimate_f1_monte_carlo_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _f1_full_inputs_missing(input_stats, payload) + _f1_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    driver_text = str(input_stats.get("driver") or "").strip().lower()
    opponent_text = str(input_stats.get("opponent") or "").strip().lower()
    selected_driver = not opponent_text or selection_text == driver_text or driver_text in selection_text

    rain_probability = _safe_probability(input_stats.get("rain_probability")) or 0.0
    session_calibration = _f1_session_calibration(input_stats.get("session_type"))
    circuit_calibration = _f1_circuit_calibration(input_stats.get("track_type"))
    weather_calibration = _f1_weather_calibration(input_stats.get("weather_conditions"), rain_probability)

    grid_edge = (number("opponent_starting_grid_position") - number("starting_grid_position")) * (0.75 + number("track_position_importance") * 0.85)
    qualy_edge = (
        (number("qualifying_pace_rating") - number("opponent_qualifying_pace_rating")) * 0.10
        + (number("practice_short_run_pace") - number("opponent_practice_short_run_pace")) * 0.075
        + (number("opponent_qualifying_position") - number("qualifying_position")) * 0.55
    )
    race_edge = (
        (number("race_pace_rating") - number("opponent_race_pace_rating")) * 0.13
        + (number("practice_long_run_pace") - number("opponent_practice_long_run_pace")) * 0.08
        + (number("constructor_pace_rating") - number("opponent_constructor_pace_rating")) * 0.09
        + (number("driver_rating") - number("opponent_driver_rating")) * 0.07
        + (number("driver_recent_form_rating") - number("opponent_recent_form_rating")) * 0.045
        + (number("constructor_recent_form_rating") - number("opponent_constructor_recent_form_rating")) * 0.04
    )
    strategy_edge = (
        (number("strategy_rating") - number("opponent_strategy_rating")) * 0.045
        + (number("pit_crew_rating") - number("opponent_pit_crew_rating")) * 0.035
        + (number("tire_degradation_rating") - number("opponent_tire_degradation_rating")) * 0.045
    )
    racecraft_edge = (
        (number("overtaking_rating") - number("opponent_overtaking_rating")) * (0.035 * (1.2 - min(1.0, number("overtaking_difficulty"))))
        + (number("defending_rating") - number("opponent_defending_rating")) * 0.035
        + (number("start_performance_rating") - number("opponent_start_performance_rating")) * 0.045
    )
    reliability_edge = (
        (number("car_reliability_rating") - number("opponent_car_reliability_rating")) * 4.0
        + (number("opponent_dnf_probability") - number("dnf_probability")) * 8.0
        + (number("opponent_crash_risk") - number("crash_risk")) * 4.0
        + (number("opponent_penalty_risk") - number("penalty_risk")) * 3.2
        + (number("opponent_engine_penalty") - number("engine_penalty")) * 0.8
    )
    circuit_edge = 0.0
    if circuit_calibration == "street":
        circuit_edge += (number("street_circuit_rating") - number("opponent_street_circuit_rating")) * 0.075
        circuit_edge += grid_edge * 0.30
    if weather_calibration in {"wet", "mixed"}:
        circuit_edge += (number("wet_weather_rating") - number("opponent_wet_weather_rating")) * (0.08 if weather_calibration == "wet" else 0.045)

    selected_edge_score = grid_edge + qualy_edge * 0.55 + race_edge + strategy_edge + racecraft_edge + reliability_edge + circuit_edge
    if not selected_driver:
        selected_edge_score *= -1
    head_to_head_probability = _logistic_probability(selected_edge_score, 8.2)

    field_strength_factor = max(0.72, min(1.18, (number("constructor_pace_rating") + number("driver_rating")) / 185))
    dnf = max(0.01, min(0.75, number("dnf_probability")))
    grid_position = max(1, number("starting_grid_position", 10))
    finish_score = selected_edge_score + (12 - grid_position) * 0.32 + (1 - dnf) * 3.5
    raw_model_probability = head_to_head_probability

    if market_key == "race_winner":
        raw_model_probability = max(0.02, min(0.72, _logistic_probability(finish_score - 7.0, 7.5) * field_strength_factor))
    elif market_key in {"podium_finish", "alt_podium"}:
        raw_model_probability = max(0.04, min(0.88, _logistic_probability(finish_score - 2.0, 7.0) * field_strength_factor))
    elif market_key == "top_5_finish":
        raw_model_probability = max(0.06, min(0.92, _logistic_probability(finish_score + 1.0, 6.5) * field_strength_factor))
    elif market_key in {"top_10_finish", "points_finish", "alt_top_10"}:
        raw_model_probability = max(0.08, min(0.94, _logistic_probability(finish_score + 3.2, 6.0) * field_strength_factor))
    elif market_key == "alt_top_6":
        raw_model_probability = max(0.06, min(0.92, _logistic_probability(finish_score + 1.5, 6.2) * field_strength_factor))
    elif market_key == "head_to_head":
        raw_model_probability = head_to_head_probability
    elif market_key == "qualifying_winner":
        raw_model_probability = max(0.02, min(0.70, _logistic_probability(qualy_edge + (15 - number("qualifying_position")) * 0.18 - number("engine_penalty") * 0.9, 6.0)))
    elif market_key == "qualifying_head_to_head":
        raw_model_probability = _logistic_probability(qualy_edge + (number("opponent_engine_penalty") - number("engine_penalty")) * 0.9, 5.8)
    elif market_key == "fastest_lap":
        late_pit_edge = max(0.0, 1.0 - number("track_position_importance")) + number("safety_car_probability") * 0.25
        raw_model_probability = max(0.02, min(0.55, _logistic_probability(race_edge + strategy_edge + late_pit_edge - 4.0, 6.5)))
    elif market_key == "driver_to_retire":
        raw_model_probability = max(0.02, min(0.70, dnf + number("crash_risk") * 0.55 + number("penalty_risk") * 0.12))
    elif market_key == "constructor_winner":
        constructor_score = (
            number("constructor_driver_1_rating") * 0.18 + number("constructor_driver_2_rating") * 0.14
            + number("constructor_race_pace_rating") * 0.22 + number("constructor_qualifying_pace_rating") * 0.12
            + number("constructor_reliability_rating") * 12 + number("constructor_strategy_rating") * 0.10
            + number("constructor_pit_crew_rating") * 0.08
        )
        raw_model_probability = max(0.03, min(0.70, _logistic_probability(constructor_score - 58, 9.0)))
    elif market_key == "safety_car":
        safety_base = number("safety_car_probability") * 0.70 + number("virtual_safety_car_probability") * 0.12
        if circuit_calibration == "street":
            safety_base += 0.08
        safety_base += rain_probability * 0.12 + (number("crash_risk") + number("opponent_crash_risk")) * 0.16
        raw_model_probability = max(0.05, min(0.88, safety_base))
    elif market_key in {"classified_finish", "not_classified"}:
        classified_probability = max(0.08, min(0.97, 1 - (dnf + number("crash_risk") * 0.45 + number("engine_penalty") * 0.025)))
        raw_model_probability = 1 - classified_probability if market_key == "not_classified" else classified_probability
    elif market_key in {"over_laps_completed", "under_laps_completed"}:
        line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line"))) or max(1, number("laps") - 1)
        expected_laps = number("laps") * max(0.05, 1 - dnf - number("crash_risk") * 0.35)
        over_probability = _logistic_probability(expected_laps - line, 6.5)
        raw_model_probability = 1 - over_probability if market_key == "under_laps_completed" else over_probability
    elif market_key == "points_scored":
        line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line"))) or 0.5
        expected_points = max(0, (11 - grid_position) * 1.8 + selected_edge_score * 0.25) * (1 - dnf)
        raw_model_probability = _logistic_probability(expected_points - line, 4.0)

    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.04, min(0.94, calibrated_probability))
    sanity_flags = ["f1 probability cap applied"] if true_probability != calibrated_probability else []

    confidence = 72.0
    risk_flags: list[str] = []
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4
        risk_flags.append("book count too low")
    if weather_calibration in {"wet", "mixed"}:
        confidence -= 4 if market_key in {"fastest_lap", "safety_car", "driver_to_retire", "not_classified"} else 2
        risk_flags.append("weather volatility")
    if number("dnf_probability") >= 0.18 or number("opponent_dnf_probability") >= 0.18:
        confidence -= 5
        risk_flags.append("reliability volatility")
    if number("penalty_risk") >= 0.18 or number("engine_penalty") > 0:
        confidence -= 5
        risk_flags.append("penalty/grid risk")
    if market_key in {"fastest_lap", "driver_to_retire", "safety_car", "not_classified"}:
        confidence -= 4
        risk_flags.append("volatile market")
    if market_key in {"head_to_head", "qualifying_head_to_head"} and abs(selected_edge_score) < 1.5:
        confidence -= 4
        risk_flags.append("thin driver edge")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    if input_stats.get("practice_report_quality") == "low" or input_stats.get("qualifying_report_quality") == "low":
        confidence -= 5
        risk_flags.append("practice/qualifying data uncertainty")
    confidence = max(1, min(95, round(confidence, 2)))

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=true_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)

    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "final_probability": true_probability,
        "model_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested,
        "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "f1 sanity cap" if sanity_flags else None,
        "market_anchor_probability": market_anchor,
        "league_calibration_applied": "f1",
        "session_calibration_applied": session_calibration,
        "circuit_calibration_applied": circuit_calibration,
        "weather_calibration_applied": weather_calibration,
        "driver_edge_score": round(selected_edge_score, 2),
        "head_to_head_probability": head_to_head_probability,
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(F1_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": F1_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in F1_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in F1_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {
            "provider_status": "available" if input_stats.get("provider_status") not in {None, "error"} else input_stats.get("provider_status") or "not_provided",
            "provider_enrichment_present": [field for field in F1_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
        },
        "no_bet_flags": no_bet_flags,
    }


def _formula_e_circuit_calibration(input_stats: dict[str, Any]) -> str:
    text = str(input_stats.get("circuit_type") or "").strip().lower()
    street = input_stats.get("street_circuit")
    if street is True or str(street).strip().lower() in {"true", "1", "yes"} or "street" in text:
        return "street"
    if "permanent" in text or "road" in text:
        return "permanent"
    return "unknown"


def _formula_e_environment_calibration(input_stats: dict[str, Any]) -> str:
    rain = _safe_probability(input_stats.get("rain_probability")) or 0.0
    weather_risk = _safe_probability(input_stats.get("weather_risk")) or 0.0
    if rain >= 0.55 or weather_risk >= 0.55:
        return "wet"
    if rain >= 0.25 or weather_risk >= 0.25:
        return "mixed"
    return "dry"


def _estimate_formula_e_monte_carlo_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _formula_e_full_inputs_missing(input_stats, payload) + _formula_e_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    driver_text = str(input_stats.get("driver") or "").strip().lower()
    selected_driver = not selection_text or selection_text == driver_text or driver_text in selection_text

    circuit_calibration = _formula_e_circuit_calibration(input_stats)
    environment_calibration = _formula_e_environment_calibration(input_stats)
    qualifying_calibration = "qualifying" in market_key or number("qualifying_position") > 0 or number("qualifying_delta") != 0
    energy_calibration = all(input_stats.get(field) is not None for field in ("energy_management_rating", "attack_mode_efficiency", "regen_efficiency", "efficiency_rating"))

    grid_edge = (number("opponent_championship_position") - number("championship_position")) * 0.20
    grid_edge += (number("opponent_practice_pace_rank") - number("practice_pace_rank")) * 0.16
    grid_edge += (number("opponent_grid_penalty") - number("grid_penalty")) * 0.70
    grid_edge += (number("opponent_driver_rating") - number("driver_rating")) * -0.02
    grid_edge += (number("opponent_qualifying_pace_rating") - number("qualifying_pace_rating")) * -0.10
    grid_edge += (number("opponent_driver_rating") - number("driver_rating")) * 0.0
    position_edge = (number("opponent_championship_position") - number("championship_position")) * 0.10
    position_edge += (number("opponent_practice_pace_rank") - number("practice_pace_rank")) * 0.10
    position_edge += -number("qualifying_delta") * 2.0 + -number("race_pace_delta") * 1.8
    position_edge += -number("grid_penalty") * 0.8 + number("opponent_grid_penalty") * 0.8

    pace_edge = (
        (number("driver_rating") - number("opponent_driver_rating")) * 0.08
        + (number("team_rating") - number("opponent_team_rating")) * 0.07
        + (number("recent_form") - number("opponent_recent_form")) * 0.05
        + (number("race_pace_rating") - number("opponent_race_pace_rating")) * 0.12
        + (number("qualifying_pace_rating") - number("opponent_qualifying_pace_rating")) * 0.08
        + (number("season_points") - number("opponent_season_points")) * 0.015
        + position_edge
    )
    energy_edge = (
        (number("energy_management_rating") - number("opponent_energy_management_rating")) * 0.12
        + (number("attack_mode_efficiency") - number("opponent_attack_mode_efficiency")) * 4.5
        + (number("regen_efficiency") - number("opponent_regen_efficiency")) * 3.8
        + (number("efficiency_rating") - number("opponent_efficiency_rating")) * 0.10
        + number("efficiency_window_rating") * 0.025
        - number("battery_temperature_risk") * 2.5
        - number("attack_mode_loss_seconds") * 0.20
        + number("attack_mode_count") * 0.12
    )
    racecraft_edge = (
        (number("overtaking_rating") - number("opponent_overtaking_rating")) * 0.055
        + (number("defensive_driving_rating") - number("opponent_defensive_driving_rating")) * 0.045
        + (number("tire_management_rating") - number("opponent_tire_management_rating")) * 0.04
        + (number("racecraft_rating") - number("opponent_racecraft_rating")) * 0.07
        + (number("race_head_to_head_rate") - 0.5) * 4.0
        + (number("qualifying_head_to_head_rate") - 0.5) * 2.2
    )
    reliability_edge = (
        (number("team_reliability_rating") - number("opponent_team_reliability_rating")) * 3.0
        + (number("opponent_dnf_risk") - number("dnf_risk")) * 8.0
        + (number("opponent_penalty_risk") - number("penalty_risk")) * 3.0
        + (number("opponent_incident_risk") - number("incident_risk")) * 4.0
    )
    circuit_edge = 0.0
    if circuit_calibration == "street":
        circuit_edge += (number("street_circuit_rating") - number("opponent_street_circuit_rating")) * 0.08
        circuit_edge += (number("safety_car_probability") + number("full_course_yellow_probability")) * 0.08
    if environment_calibration in {"wet", "mixed"}:
        circuit_edge -= number("weather_risk") * 1.1
        circuit_edge -= number("rain_probability") * 0.8

    selected_edge_score = pace_edge + energy_edge + racecraft_edge + reliability_edge + circuit_edge + grid_edge * 0.15
    if not selected_driver:
        selected_edge_score *= -1
    matchup_probability = _logistic_probability(selected_edge_score, 8.0)

    dnf = max(0.01, min(0.8, number("dnf_risk")))
    incident = max(0.0, min(0.8, number("incident_risk")))
    grid_position = max(1, number("grid_position", number("qualifying_position", 10)))
    finish_score = selected_edge_score + (12 - grid_position) * 0.28 + (1 - dnf) * 2.8
    raw_model_probability = matchup_probability

    if market_key in {"race_winner", "outright_winner"}:
        raw_model_probability = max(0.02, min(0.72, _logistic_probability(finish_score - 6.0, 7.2)))
    elif market_key in {"podium_finish", "top_3_finish"}:
        raw_model_probability = max(0.04, min(0.88, _logistic_probability(finish_score - 1.6, 6.8)))
    elif market_key == "top_5_finish":
        raw_model_probability = max(0.06, min(0.92, _logistic_probability(finish_score + 1.2, 6.4)))
    elif market_key in {"top_10_finish", "points_finish"}:
        raw_model_probability = max(0.08, min(0.94, _logistic_probability(finish_score + 3.0, 6.0)))
    elif market_key == "qualifying_winner":
        raw_model_probability = max(0.02, min(0.70, _logistic_probability((number("qualifying_pace_rating") - number("opponent_qualifying_pace_rating")) * 0.30 + (12 - number("qualifying_position")) * 0.22 - number("grid_penalty"), 5.8)))
    elif market_key == "qualifying_head_to_head":
        raw_model_probability = _logistic_probability((number("qualifying_pace_rating") - number("opponent_qualifying_pace_rating")) * 0.18 + (number("qualifying_head_to_head_rate") - 0.5) * 4.5, 4.8)
    elif market_key in {"race_head_to_head", "driver_matchup", "constructor_matchup", "team_matchup"}:
        raw_model_probability = matchup_probability
    elif market_key == "fastest_lap":
        raw_model_probability = max(0.02, min(0.55, _logistic_probability(pace_edge + number("attack_mode_efficiency") * 1.8 - 4.0, 6.5)))
    elif market_key == "safety_car":
        raw_model_probability = max(0.05, min(0.90, number("safety_car_probability") * 0.72 + number("full_course_yellow_probability") * 0.14 + incident * 0.18 + number("weather_risk") * 0.10))
    elif market_key == "classified_finish":
        raw_model_probability = max(0.05, min(0.97, 1 - (dnf + incident * 0.45 + number("penalty_risk") * 0.08)))
    elif market_key in {"over_under_position", "finishing_position"}:
        line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line"))) or 7.5
        expected_position = max(1, grid_position - selected_edge_score * 0.18 + dnf * 6 + incident * 3)
        over_probability = _logistic_probability(expected_position - line, 2.8)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"championship_winner", "team_championship_winner"}:
        season_edge = (number("season_points") - number("opponent_season_points")) * 0.02 + selected_edge_score * 0.18
        raw_model_probability = max(0.03, min(0.70, _logistic_probability(season_edge, 6.5)))

    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.04, min(0.94, calibrated_probability))
    sanity_flags = ["formula e probability cap applied"] if true_probability != calibrated_probability else []

    confidence = 72.0
    risk_flags: list[str] = []
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4
        risk_flags.append("book count too low")
    if environment_calibration in {"wet", "mixed"}:
        confidence -= 4
        risk_flags.append("weather volatility")
    if dnf >= 0.20 or incident >= 0.20:
        confidence -= 8
        risk_flags.append("dnf/incident volatility")
    if number("battery_temperature_risk") >= 0.25:
        confidence -= 5
        risk_flags.append("battery temperature risk")
    if number("penalty_risk") >= 0.18 or number("grid_penalty") > 0:
        confidence -= 5
        risk_flags.append("penalty/grid risk")
    if market_key in {"fastest_lap", "safety_car", "group_winner"}:
        confidence -= 4
        risk_flags.append("volatile market")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    if input_stats.get("qualifying_report_quality") == "low" or input_stats.get("battery_report_quality") == "low":
        confidence -= 5
        risk_flags.append("data quality uncertainty")
    confidence = max(1, min(95, round(confidence, 2)))

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    if dnf >= 0.35 or incident >= 0.35:
        no_bet_flags.append("dnf incident risk")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=true_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)

    return {
        "model_status": "active", "estimated_true_probability": true_probability,
        "true_probability": true_probability, "final_probability": true_probability,
        "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested, "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "formula e sanity cap" if sanity_flags else None,
        "market_anchor_probability": market_anchor,
        "league_calibration_applied": "formula_e",
        "circuit_calibration_applied": circuit_calibration,
        "event_environment_calibration_applied": environment_calibration,
        "qualifying_calibration_applied": qualifying_calibration,
        "energy_management_calibration_applied": energy_calibration,
        "formula_e_driver_edge_score": round(selected_edge_score, 2),
        "formula_e_matchup_probability": matchup_probability,
        "formula_e_energy_edge_score": round(energy_edge, 2),
        "formula_e_attack_mode_edge_score": round((number("attack_mode_efficiency") - number("opponent_attack_mode_efficiency")) * 4.5, 2),
        "formula_e_reliability_probability": round(max(0.05, min(0.97, 1 - dnf - incident * 0.35)), 4),
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(FORMULA_E_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": FORMULA_E_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in FORMULA_E_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in FORMULA_E_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [field for field in FORMULA_E_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _rugby_code_variant_calibration(raw_variant: Any) -> str:
    text = str(raw_variant or "").strip().lower().replace("-", "_").replace(" ", "_")
    if "league" in text or text == "nrl":
        return "rugby_league"
    if "union" in text or text in {"rugby", "six_nations", "super_rugby", "top_14"}:
        return "rugby_union"
    return "unknown"


def _rugby_weather_calibration(input_stats: dict[str, Any]) -> str:
    rain = _safe_float(input_stats.get("rain_probability"), 0) or 0
    wind = _safe_float(input_stats.get("wind_speed"), 0) or 0
    risk = _safe_float(input_stats.get("weather_risk"), 0) or 0
    pitch = str(input_stats.get("pitch_condition") or "").lower()
    wet = rain >= 0.45 or "wet" in pitch or risk >= 0.55
    windy = wind >= 28 or "wind" in pitch
    if wet and windy:
        return "mixed"
    if wet:
        return "wet"
    if windy:
        return "windy"
    if any(value is not None for value in (input_stats.get("rain_probability"), input_stats.get("wind_speed"), input_stats.get("weather_risk"), input_stats.get("pitch_condition"))):
        return "dry"
    return "unknown"


def _estimate_rugby_set_piece_territory_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _rugby_full_inputs_missing(input_stats, payload) + _rugby_market_specific_missing(market, input_stats, payload)
    if missing or odds_american is None:
        return None

    market_key = _normal_market_key(input_stats.get("market") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    team_text = str(input_stats.get("team") or "").strip().lower()
    selected_team = selection_text in {"", team_text} or team_text in selection_text

    def n(field: str, default: float = 0.0) -> float:
        value = _safe_float(input_stats.get(field), default)
        return default if value is None else value

    implied_probability = implied_probability_from_american(odds_american)
    code_calibration = _rugby_code_variant_calibration(input_stats.get("code_variant") or payload.get("sport") or payload.get("league"))
    competition_calibration = str(input_stats.get("competition") or payload.get("league") or "unknown").strip() or "unknown"
    weather_calibration = _rugby_weather_calibration(input_stats)
    referee_calibration = any(input_stats.get(field) is not None for field in ("referee_penalty_rate", "referee_card_rate"))

    attack_points = n("team_expected_points_for") * 0.46 + n("team_points_for") * 0.24 + n("team_try_rate") * 1.55 + n("team_goal_kicking_rate") * 3.0
    opponent_attack_points = n("opponent_expected_points_for") * 0.46 + n("opponent_points_for") * 0.24 + n("opponent_try_rate") * 1.55 + n("opponent_goal_kicking_rate") * 3.0
    defensive_allowance = n("team_expected_points_against") * 0.45 + n("team_points_against") * 0.25 + n("team_try_conceded_rate") * 1.2
    opponent_defensive_allowance = n("opponent_expected_points_against") * 0.45 + n("opponent_points_against") * 0.25 + n("opponent_try_conceded_rate") * 1.2
    set_piece_edge = (
        (n("team_set_piece_rating") - n("opponent_set_piece_rating")) * 0.08
        + (n("team_scrum_rating") - n("opponent_scrum_rating")) * 0.035
        + (n("team_lineout_rating") - n("opponent_lineout_rating")) * 0.035
        + (n("team_ruck_rating") - n("opponent_ruck_rating")) * 0.025
        + (n("team_breakdown_rating") - n("opponent_breakdown_rating")) * 0.035
        + (n("team_maul_rating") - n("opponent_maul_rating")) * 0.025
    )
    territory_edge = (
        (n("team_territory_rating") - n("opponent_territory_rating")) * 0.07
        + (n("team_possession_rating") - n("opponent_possession_rating")) * 0.035
        + (n("team_kicking_game_rating") - n("opponent_kicking_game_rating")) * 0.04
        + (n("team_gainline_success_rate") - n("opponent_gainline_success_rate")) * 3.2
        + (n("team_line_break_rate") - n("opponent_line_break_rate")) * 0.18
        + (n("team_offload_rate") - n("opponent_offload_rate")) * 0.06
    )
    discipline_edge = (
        (n("team_discipline_rating") - n("opponent_discipline_rating")) * 0.055
        + (n("opponent_penalties_conceded_rate") - n("team_penalties_conceded_rate")) * 0.16
        + (n("opponent_yellow_card_rate") - n("team_yellow_card_rate")) * 1.8
        + (n("opponent_red_card_rate") - n("team_red_card_rate")) * 3.5
        - max(0, n("referee_penalty_rate") - 21.0) * 0.04
        - max(0, n("referee_card_rate") - 0.65) * 0.8
    )
    defense_edge = (
        (n("team_tackle_success_rate") - n("opponent_tackle_success_rate")) * 4.0
        + (n("opponent_missed_tackle_rate") - n("team_missed_tackle_rate")) * 0.08
        + (n("team_forced_turnover_rate") - n("opponent_forced_turnover_rate")) * 0.11
        + (n("opponent_turnover_rate") - n("team_turnover_rate")) * 0.07
        + (n("team_goal_line_defense_rating") - n("opponent_goal_line_defense_rating")) * 0.045
    )
    availability_edge = (
        (n("key_player_availability") - n("opponent_key_player_availability")) * 4.0
        + (n("team_injury_availability_rating") - n("opponent_injury_availability_rating")) * 3.2
        + (n("rest_days") - n("opponent_rest_days")) * 0.12
        + (n("opponent_travel_fatigue") - n("travel_fatigue")) * 1.8
    )
    home_edge = 1.1 if str(input_stats.get("home_away") or "").lower() == "home" and not input_stats.get("neutral_site") else 0.0
    weather_drag = 1.2 if weather_calibration in {"wet", "windy"} else (1.8 if weather_calibration == "mixed" else 0.0)
    projected_team_points = max(4.0, attack_points * 0.55 + opponent_defensive_allowance * 0.42 + set_piece_edge + territory_edge + discipline_edge + availability_edge + home_edge - weather_drag)
    projected_opponent_points = max(4.0, opponent_attack_points * 0.55 + defensive_allowance * 0.42 - set_piece_edge * 0.62 - territory_edge * 0.55 - discipline_edge * 0.55 - availability_edge * 0.50 + weather_drag * 0.15)
    projected_margin = projected_team_points - projected_opponent_points
    projected_total = projected_team_points + projected_opponent_points

    if not selected_team and market_key not in {"total_points", "first_half_total", "second_half_total", "alt_total_points"}:
        projected_margin *= -1

    raw_model_probability = _logistic_probability(projected_margin, 8.5)
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line") or input_stats.get("player_prop_line")))
    if market_key in {"spread", "handicap", "alt_spread"}:
        raw_model_probability = _logistic_probability(projected_margin + (line or 0), 7.0)
    elif market_key in {"total_points", "alt_total_points"}:
        total_line = line if line is not None else _safe_float(payload.get("total_line"), 47.5) or 47.5
        over_probability = _logistic_probability(projected_total - total_line, 8.0)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"team_total_points", "alt_team_total_points"}:
        total_line = line if line is not None else 24.5
        over_probability = _logistic_probability(projected_team_points - total_line, 5.5)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"first_half_winner", "second_half_winner"}:
        raw_model_probability = _logistic_probability(projected_margin * 0.48, 4.7)
    elif market_key in {"first_half_spread", "second_half_spread"}:
        raw_model_probability = _logistic_probability(projected_margin * 0.48 + (line or 0), 4.2)
    elif market_key in {"first_half_total", "second_half_total"}:
        total_line = line if line is not None else 23.5
        over_probability = _logistic_probability(projected_total * 0.49 - total_line, 4.8)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"winning_margin", "exact_margin"}:
        target_margin = abs(line if line is not None else 7.5)
        raw_model_probability = max(0.04, min(0.42, _logistic_probability(5.0 - abs(abs(projected_margin) - target_margin), 4.0)))
    elif market_key == "draw_no_bet":
        raw_model_probability = max(0.08, min(0.90, _logistic_probability(projected_margin, 7.0)))
    elif market_key == "double_chance":
        raw_model_probability = max(0.28, min(0.92, _logistic_probability(projected_margin + 3.0, 8.0)))
    elif market_key in RUGBY_PROP_MARKETS:
        if market_key in {"try_scorer", "anytime_try_scorer", "player_tries"}:
            raw_model_probability = max(0.04, min(0.78, n("player_anytime_try_probability", n("player_try_projection", 0.25))))
        elif market_key == "first_try_scorer":
            raw_model_probability = max(0.02, min(0.30, n("player_first_try_probability", 0.08)))
        elif market_key == "player_points":
            raw_model_probability = _logistic_probability(n("player_points_projection") - (line if line is not None else n("player_prop_line", 7.5)), 3.0)
        elif market_key == "player_tackles":
            raw_model_probability = _logistic_probability(n("player_tackles_projection") - (line if line is not None else n("player_prop_line", 11.5)), 3.5)
        elif market_key == "player_kicking_points":
            raw_model_probability = _logistic_probability(n("player_kicking_points_projection") - (line if line is not None else n("player_prop_line", 5.5)), 2.5)

    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.04, min(0.94, calibrated_probability))
    sanity_flags = ["rugby probability cap applied"] if true_probability != calibrated_probability else []

    confidence = 73.0
    risk_flags: list[str] = []
    if (_safe_float(input_stats.get("book_count"), 0) or 0) < 4:
        confidence -= 4
        risk_flags.append("book count too low")
    if weather_calibration in {"wet", "windy"}:
        confidence -= 4
        risk_flags.append("weather volatility")
    elif weather_calibration == "mixed":
        confidence -= 7
        risk_flags.append("weather volatility")
    if n("team_yellow_card_rate") >= 0.55 or n("team_red_card_rate") >= 0.12 or n("referee_card_rate") >= 1.2:
        confidence -= 12
        risk_flags.append("discipline/card volatility")
    if n("key_player_availability") < 0.75 or n("team_injury_availability_rating") < 0.78:
        confidence -= 8
        risk_flags.append("key player availability risk")
    if market_key in {"first_try_scorer", "exact_margin", "winning_margin"}:
        confidence -= 6
        risk_flags.append("volatile market")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    if n("team_yellow_card_rate") >= 0.75 or n("team_red_card_rate") >= 0.20:
        no_bet_flags.append("discipline/card risk")

    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=true_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)

    return {
        "model_status": "active", "estimated_true_probability": true_probability,
        "true_probability": true_probability, "final_probability": true_probability,
        "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested, "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "rugby sanity cap" if sanity_flags else None,
        "market_anchor_probability": market_anchor,
        "league_calibration_applied": "rugby",
        "code_variant_calibration_applied": code_calibration,
        "competition_calibration_applied": competition_calibration,
        "weather_calibration_applied": weather_calibration,
        "referee_calibration_applied": referee_calibration,
        "rugby_projected_team_points": round(projected_team_points, 2),
        "rugby_projected_opponent_points": round(projected_opponent_points, 2),
        "rugby_projected_margin": round(projected_margin, 2),
        "rugby_projected_total": round(projected_total, 2),
        "rugby_set_piece_edge_score": round(set_piece_edge, 2),
        "rugby_territory_edge_score": round(territory_edge, 2),
        "rugby_discipline_edge_score": round(discipline_edge, 2),
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(RUGBY_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": RUGBY_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in RUGBY_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in RUGBY_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [field for field in RUGBY_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _lacrosse_format_calibration(input_stats: dict[str, Any]) -> str:
    text = str(input_stats.get("indoor_outdoor") or "").strip().lower().replace("-", "_").replace(" ", "_")
    league = str(input_stats.get("league") or input_stats.get("competition") or "").strip().lower()
    if text in {"box", "indoor"} or league == "nll":
        return "box"
    if text in {"field", "outdoor"} or league in {"pll", "ncaa", "college_lacrosse"}:
        return "field"
    return "unknown"


def _lacrosse_gender_calibration(input_stats: dict[str, Any]) -> str:
    text = str(input_stats.get("gender_format") or "").strip().lower()
    if text.startswith("men") or text in {"m", "mens"}:
        return "mens"
    if text.startswith("women") or text in {"w", "womens"}:
        return "womens"
    return "unknown"


def _lacrosse_competition_calibration(input_stats: dict[str, Any], payload: dict[str, Any]) -> str:
    text = str(input_stats.get("competition") or input_stats.get("league") or payload.get("league") or "").strip().lower().replace("-", "_").replace(" ", "_")
    if text in {"pll", "premier_lacrosse_league"}:
        return "pll"
    if text in {"nll", "national_lacrosse_league"}:
        return "nll"
    if "ncaa" in text or "college" in text:
        return "ncaa"
    if "international" in text or "world" in text:
        return "international"
    return "unknown"


def _lacrosse_weather_calibration(input_stats: dict[str, Any], format_calibration: str) -> str:
    if format_calibration == "box":
        return "indoor"
    wind = _safe_float(input_stats.get("wind_speed"), 0) or 0
    risk = _safe_float(input_stats.get("weather_risk"), 0) or 0
    field = str(input_stats.get("field_condition") or "").lower()
    if wind >= 22 or "wind" in field:
        return "windy"
    if risk >= 0.55 or "wet" in field or "rain" in field:
        return "wet"
    if any(value is not None for value in (input_stats.get("wind_speed"), input_stats.get("weather_risk"), input_stats.get("field_condition"))):
        return "dry"
    return "unknown"


def _estimate_lacrosse_faceoff_possession_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _lacrosse_full_inputs_missing(input_stats, payload) + _lacrosse_market_specific_missing(market, input_stats, payload)
    if missing or odds_american is None:
        return None

    market_key = _normal_market_key(input_stats.get("market") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    team_text = str(input_stats.get("team") or "").strip().lower()
    selected_team = selection_text in {"", team_text} or team_text in selection_text

    def n(field: str, default: float = 0.0) -> float:
        value = _safe_float(input_stats.get(field), default)
        return default if value is None else value

    implied_probability = implied_probability_from_american(odds_american)
    format_calibration = _lacrosse_format_calibration(input_stats)
    gender_calibration = _lacrosse_gender_calibration(input_stats)
    competition_calibration = _lacrosse_competition_calibration(input_stats, payload)
    weather_calibration = _lacrosse_weather_calibration(input_stats, format_calibration)
    faceoff_calibration = any(input_stats.get(field) is not None for field in ("team_faceoff_win_rate", "opponent_faceoff_win_rate"))
    goalie_calibration = any(input_stats.get(field) is not None for field in ("team_save_percentage", "opponent_save_percentage", "goalie_rating", "opponent_goalie_rating"))

    attack_goals = n("team_expected_goals_for") * 0.48 + n("team_goals_for") * 0.28 + n("team_shot_rate") * 0.035 + n("team_shots_on_goal_rate") * 0.055
    opponent_attack_goals = n("opponent_expected_goals_for") * 0.48 + n("opponent_goals_for") * 0.28 + n("opponent_shot_rate") * 0.035 + n("opponent_shots_on_goal_rate") * 0.055
    defense_allowance = n("team_expected_goals_against") * 0.46 + n("team_goals_against") * 0.30
    opponent_defense_allowance = n("opponent_expected_goals_against") * 0.46 + n("opponent_goals_against") * 0.30
    shot_quality_edge = (
        (n("team_shot_quality_rating") - n("opponent_shot_quality_rating")) * 0.035
        + (n("team_set_offense_rating") - n("opponent_set_offense_rating")) * 0.030
        + (n("team_transition_rating") - n("opponent_transition_rating")) * 0.025
    )
    possession_edge = (
        (n("team_faceoff_win_rate") - n("opponent_faceoff_win_rate")) * 5.4
        + (n("team_possession_rating") - n("opponent_possession_rating")) * 0.040
        + (n("team_ground_ball_rate") - n("opponent_ground_ball_rate")) * 0.050
        + (n("opponent_turnover_rate") - n("team_turnover_rate")) * 0.080
        + (n("team_forced_turnover_rate") - n("opponent_forced_turnover_rate")) * 0.070
        + (n("team_clear_rate") - n("opponent_clear_rate")) * 2.0
        + (n("team_ride_success_rate") - n("opponent_ride_success_rate")) * 1.5
    )
    goalie_edge = (
        (n("team_save_percentage") - n("opponent_save_percentage")) * 4.8
        + (n("goalie_rating") - n("opponent_goalie_rating")) * 0.035
        + (n("team_defensive_efficiency") - n("opponent_defensive_efficiency")) * 0.028
    )
    special_teams_edge = (
        (n("team_extra_man_offense_rate") - n("opponent_extra_man_offense_rate")) * 2.0
        + (n("team_man_down_defense_rate") - n("opponent_man_down_defense_rate")) * 1.6
        + (n("opponent_penalty_rate") - n("team_penalty_rate")) * 0.11
        - max(0, n("referee_penalty_rate") - 7.0) * 0.04
    )
    availability_edge = (
        (n("key_player_availability") - n("opponent_key_player_availability")) * 2.7
        + (n("team_injury_availability_rating") - n("opponent_injury_availability_rating")) * 2.4
        + (n("rest_days") - n("opponent_rest_days")) * 0.08
        + (n("opponent_travel_fatigue") - n("travel_fatigue")) * 1.0
    )
    pace_factor = max(0.88, min(1.14, ((n("team_pace") + n("opponent_pace")) / 2.0) / 73.0))
    format_goal_boost = 1.12 if format_calibration == "box" else 1.0
    home_edge = 0.45 if str(input_stats.get("home_away") or "").lower() == "home" and not input_stats.get("neutral_site") else 0.0
    weather_drag = 0.45 if weather_calibration in {"wet", "windy"} else 0.0
    projected_team_goals = max(3.0, (attack_goals * 0.58 + opponent_defense_allowance * 0.38 + shot_quality_edge + possession_edge + goalie_edge + special_teams_edge + availability_edge + home_edge - weather_drag) * format_goal_boost * pace_factor)
    projected_opponent_goals = max(3.0, (opponent_attack_goals * 0.58 + defense_allowance * 0.38 - shot_quality_edge * 0.58 - possession_edge * 0.50 - goalie_edge * 0.60 - special_teams_edge * 0.45 - availability_edge * 0.42 + weather_drag * 0.10) * format_goal_boost * pace_factor)
    projected_margin = projected_team_goals - projected_opponent_goals
    projected_total = projected_team_goals + projected_opponent_goals

    if not selected_team and market_key not in {"total_goals", "first_half_total", "second_half_total", "quarter_total", "alt_total_goals"}:
        projected_margin *= -1

    raw_model_probability = _logistic_probability(projected_margin, 3.2)
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line") or input_stats.get("player_prop_line")))
    if market_key in {"spread", "handicap", "alt_spread"}:
        raw_model_probability = _logistic_probability(projected_margin + (line or 0), 2.8)
    elif market_key in {"total_goals", "alt_total_goals"}:
        total_line = line if line is not None else 24.5
        over_probability = _logistic_probability(projected_total - total_line, 3.8)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"team_total_goals", "alt_team_total_goals"}:
        total_line = line if line is not None else 12.5
        over_probability = _logistic_probability(projected_team_goals - total_line, 2.4)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"first_half_winner", "second_half_winner"}:
        raw_model_probability = _logistic_probability(projected_margin * 0.50, 1.8)
    elif market_key in {"first_half_spread", "second_half_spread"}:
        raw_model_probability = _logistic_probability(projected_margin * 0.50 + (line or 0), 1.6)
    elif market_key in {"first_half_total", "second_half_total"}:
        total_line = line if line is not None else 12.0
        over_probability = _logistic_probability(projected_total * 0.50 - total_line, 2.0)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key == "quarter_winner":
        raw_model_probability = _logistic_probability(projected_margin * 0.25, 1.2)
    elif market_key == "quarter_spread":
        raw_model_probability = _logistic_probability(projected_margin * 0.25 + (line or 0), 1.1)
    elif market_key == "quarter_total":
        total_line = line if line is not None else 6.0
        over_probability = _logistic_probability(projected_total * 0.25 - total_line, 1.3)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key == "winning_margin":
        target_margin = abs(line if line is not None else 2.5)
        raw_model_probability = max(0.05, min(0.46, _logistic_probability(2.2 - abs(abs(projected_margin) - target_margin), 1.8)))
    elif market_key in LACROSSE_PROP_MARKETS:
        prop_line = line if line is not None else n("player_prop_line", 1.5)
        if market_key == "player_goals":
            raw_model_probability = _logistic_probability(n("player_goals_projection") - prop_line, 0.85)
        elif market_key == "player_assists":
            raw_model_probability = _logistic_probability(n("player_assists_projection") - prop_line, 0.85)
        elif market_key == "player_points":
            raw_model_probability = _logistic_probability(n("player_points_projection") - prop_line, 1.15)
        elif market_key == "player_shots":
            raw_model_probability = _logistic_probability(n("player_shots_projection") - prop_line, 1.8)
        elif market_key == "player_shots_on_goal":
            raw_model_probability = _logistic_probability(n("player_shots_on_goal_projection") - prop_line, 1.2)
        elif market_key == "player_saves":
            raw_model_probability = _logistic_probability(n("player_saves_projection") - prop_line, 2.2)
        elif market_key == "player_ground_balls":
            raw_model_probability = _logistic_probability(n("player_ground_balls_projection") - prop_line, 1.1)
        elif market_key == "player_faceoff_wins":
            raw_model_probability = _logistic_probability(n("player_faceoff_wins_projection") - prop_line, 2.4)
        elif market_key == "anytime_goal_scorer":
            raw_model_probability = max(0.04, min(0.84, n("player_anytime_goal_probability", 0.35)))
        elif market_key == "first_goal_scorer":
            raw_model_probability = max(0.02, min(0.30, n("player_first_goal_probability", 0.08)))

    calibrated_probability = raw_model_probability
    true_probability = max(0.04, min(0.94, calibrated_probability))
    sanity_flags = ["lacrosse probability cap applied"] if true_probability != calibrated_probability else []

    confidence = 74.0
    risk_flags: list[str] = []
    if (_safe_float(input_stats.get("book_count"), 0) or 0) < 4:
        confidence -= 4
        risk_flags.append("book count too low")
    if weather_calibration in {"wet", "windy"}:
        confidence -= 5
        risk_flags.append("weather volatility")
    if n("key_player_availability") < 0.75 or n("team_injury_availability_rating") < 0.78:
        confidence -= 9
        risk_flags.append("key player availability risk")
    if n("goalie_rating") < 65 or n("team_save_percentage") < 0.48:
        confidence -= 6
        risk_flags.append("goalie volatility")
    if market_key in {"first_goal_scorer", "winning_margin", "quarter_winner"}:
        confidence -= 6
        risk_flags.append("volatile market")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")

    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=true_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)

    return {
        "model_status": "active", "estimated_true_probability": true_probability,
        "true_probability": true_probability, "final_probability": true_probability,
        "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested, "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "lacrosse sanity cap" if sanity_flags else None,
        "market_anchor_probability": None,
        "league_calibration_applied": "lacrosse",
        "format_calibration_applied": format_calibration,
        "gender_calibration_applied": gender_calibration,
        "competition_calibration_applied": competition_calibration,
        "weather_calibration_applied": weather_calibration,
        "faceoff_calibration_applied": faceoff_calibration,
        "goalie_calibration_applied": goalie_calibration,
        "lacrosse_projected_team_goals": round(projected_team_goals, 2),
        "lacrosse_projected_opponent_goals": round(projected_opponent_goals, 2),
        "lacrosse_projected_margin": round(projected_margin, 2),
        "lacrosse_projected_total": round(projected_total, 2),
        "lacrosse_faceoff_edge_score": round(possession_edge, 2),
        "lacrosse_shot_quality_edge_score": round(shot_quality_edge, 2),
        "lacrosse_goalie_edge_score": round(goalie_edge, 2),
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(LACROSSE_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": LACROSSE_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in LACROSSE_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in LACROSSE_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [field for field in LACROSSE_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _table_tennis_format_calibration(input_stats: dict[str, Any]) -> str:
    games = _safe_float(input_stats.get("best_of_games"))
    text = str(input_stats.get("match_format") or "").strip().lower().replace("-", "_").replace(" ", "_")
    if games in {3, 5, 7}:
        return f"best_of_{int(games)}"
    if "best_of_3" in text or text in {"bo3", "best3"}:
        return "best_of_3"
    if "best_of_5" in text or text in {"bo5", "best5"}:
        return "best_of_5"
    if "best_of_7" in text or text in {"bo7", "best7"}:
        return "best_of_7"
    return "unknown"


def _estimate_table_tennis_serve_return_rally_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _table_tennis_full_inputs_missing(input_stats, payload) + _table_tennis_market_specific_missing(market, input_stats, payload)
    if missing or odds_american is None:
        return None

    market_key = _normal_market_key(input_stats.get("market") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    player_text = str(input_stats.get("player") or "").strip().lower()
    selected_player = selection_text in {"", player_text} or player_text in selection_text

    def n(field: str, default: float = 0.0) -> float:
        value = _safe_float(input_stats.get(field), default)
        return default if value is None else value

    implied_probability = implied_probability_from_american(odds_american)
    format_calibration = _table_tennis_format_calibration(input_stats)
    tournament_calibration = str(input_stats.get("tournament") or payload.get("league") or "unknown").strip() or "unknown"
    serve_return_calibration = any(input_stats.get(field) is not None for field in ("player_serve_rating", "opponent_serve_rating", "player_return_rating", "opponent_return_rating"))
    rally_style_calibration = any(input_stats.get(field) is not None for field in ("player_rally_rating", "opponent_rally_rating", "player_spin_rating", "opponent_spin_rating", "playing_style_matchup"))
    deciding_game_calibration = any(input_stats.get(field) is not None for field in ("player_deciding_game_win_rate", "opponent_deciding_game_win_rate", "player_clutch_rating", "opponent_clutch_rating"))

    rating_edge = (n("player_rating") - n("opponent_rating")) * 0.045 + (n("player_elo") - n("opponent_elo")) * 0.004
    rank_edge = (n("opponent_world_rank") - n("player_world_rank")) * 0.025
    form_edge = (n("player_recent_win_rate") - n("opponent_recent_win_rate")) * 3.2 + (n("player_recent_form") - n("opponent_recent_form")) * 0.030
    serve_return_edge = (
        (n("player_serve_rating") - n("opponent_serve_rating")) * 0.030
        + (n("player_return_rating") - n("opponent_return_rating")) * 0.034
        + (n("player_service_points_won_rate") - n("opponent_service_points_won_rate")) * 4.2
        + (n("player_return_points_won_rate") - n("opponent_return_points_won_rate")) * 4.8
        + (n("player_first_ball_attack_rating") - n("opponent_first_ball_attack_rating")) * 0.025
        + (n("player_receive_quality_rating") - n("opponent_receive_quality_rating")) * 0.026
    )
    rally_edge = (
        (n("player_rally_rating") - n("opponent_rally_rating")) * 0.032
        + (n("player_short_game_rating") - n("opponent_short_game_rating")) * 0.020
        + (n("player_counterattack_rating") - n("opponent_counterattack_rating")) * 0.024
        + (n("player_defensive_rating") - n("opponent_defensive_rating")) * 0.018
        + (n("player_spin_rating") - n("opponent_spin_rating")) * 0.018
        + (n("player_speed_rating") - n("opponent_speed_rating")) * 0.016
        + (n("player_consistency_rating") - n("opponent_consistency_rating")) * 0.026
        + (n("opponent_error_rate") - n("player_error_rate")) * 5.5
    )
    momentum_edge = (
        (n("player_game_win_rate") - n("opponent_game_win_rate")) * 3.6
        + (n("player_deciding_game_win_rate") - n("opponent_deciding_game_win_rate")) * 2.2
        + (n("player_comeback_rating") - n("opponent_comeback_rating")) * 0.018
        + (n("player_clutch_rating") - n("opponent_clutch_rating")) * 0.024
        + (n("player_momentum_rating") - n("opponent_momentum_rating")) * 0.020
        + (n("player_pressure_rating") - n("opponent_pressure_rating")) * 0.020
    )
    context_edge = (
        (n("opponent_fatigue_rating") - n("fatigue_rating")) * 1.8
        + (n("rest_days") - n("opponent_rest_days")) * 0.12
        + (n("opponent_travel_fatigue") - n("travel_fatigue")) * 1.2
        + (n("opponent_injury_risk") - n("injury_risk")) * 2.4
    )
    speed_drag = max(0.0, n("table_speed_rating") - 0.75) * 0.25 + max(0.0, n("ball_speed_rating") - 0.75) * 0.20
    player_edge_score = rating_edge + rank_edge + form_edge + serve_return_edge + rally_edge + momentum_edge + context_edge - speed_drag
    if not selected_player and market_key not in {"total_games", "total_points", "alt_total_games", "alt_total_points"}:
        player_edge_score *= -1

    raw_model_probability = _logistic_probability(player_edge_score, 2.7)
    projected_games = max(3.0, min(n("best_of_games", 5), n("player_games_projection") + n("opponent_games_projection") * 0.15))
    projected_points = max(18.0, n("player_points_projection") + n("opponent_points_projection"))
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line") or input_stats.get("player_prop_line")))
    if market_key in {"game_winner", "set_winner", "first_game_winner", "second_game_winner", "third_game_winner", "fourth_game_winner", "fifth_game_winner"}:
        game_multiplier = 0.72 if market_key in {"fourth_game_winner", "fifth_game_winner"} else 0.85
        raw_model_probability = _logistic_probability(player_edge_score * game_multiplier, 2.2)
    elif market_key in {"game_handicap", "alt_game_handicap"}:
        raw_model_probability = _logistic_probability(player_edge_score + (line or 0), 2.3)
    elif market_key == "point_handicap":
        raw_model_probability = _logistic_probability(player_edge_score * 5.5 + (line or 0), 7.0)
    elif market_key in {"total_games", "alt_total_games"}:
        total_line = line if line is not None else 4.5
        over_probability = _logistic_probability(projected_games - total_line, 0.9)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"total_points", "alt_total_points"}:
        total_line = line if line is not None else 78.5
        over_probability = _logistic_probability(projected_points - total_line, 8.0)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key == "correct_score":
        raw_model_probability = max(0.05, min(0.42, _logistic_probability(abs(player_edge_score) - 1.0, 2.0)))
    elif market_key in TABLE_TENNIS_PROP_MARKETS:
        prop_line = line if line is not None else n("player_prop_line", 24.5)
        if market_key == "player_service_points_won":
            raw_model_probability = _logistic_probability(n("player_service_points_projection") - prop_line, 3.8)
        elif market_key == "player_return_points_won":
            raw_model_probability = _logistic_probability(n("player_return_points_projection") - prop_line, 3.2)
        elif market_key == "player_total_points":
            raw_model_probability = _logistic_probability(n("player_points_projection") - prop_line, 5.5)
        elif market_key == "player_aces":
            raw_model_probability = _logistic_probability((n("player_serve_rating") - 82) * 0.10 - prop_line, 1.6)

    calibrated_probability = raw_model_probability
    true_probability = max(0.04, min(0.94, calibrated_probability))
    sanity_flags = ["table tennis probability cap applied"] if true_probability != calibrated_probability else []

    confidence = 74.0
    risk_flags: list[str] = []
    if (_safe_float(input_stats.get("book_count"), 0) or 0) < 4:
        confidence -= 4
        risk_flags.append("book count too low")
    if n("fatigue_rating") > 0.65 or n("injury_risk") > 0.30:
        confidence -= 9
        risk_flags.append("player condition risk")
    if market_key in {"correct_score", "player_aces", "fourth_game_winner", "fifth_game_winner"}:
        confidence -= 7
        risk_flags.append("volatile market")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")

    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=true_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)

    return {
        "model_status": "active", "estimated_true_probability": true_probability,
        "true_probability": true_probability, "final_probability": true_probability,
        "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested, "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "table tennis sanity cap" if sanity_flags else None,
        "market_anchor_probability": None,
        "league_calibration_applied": "table_tennis",
        "format_calibration_applied": format_calibration,
        "tournament_calibration_applied": tournament_calibration or "unknown",
        "serve_return_calibration_applied": serve_return_calibration,
        "rally_style_calibration_applied": rally_style_calibration,
        "deciding_game_calibration_applied": deciding_game_calibration,
        "table_tennis_player_edge_score": round(player_edge_score, 2),
        "table_tennis_projected_games": round(projected_games, 2),
        "table_tennis_projected_total_points": round(projected_points, 2),
        "table_tennis_serve_return_edge_score": round(serve_return_edge, 2),
        "table_tennis_rally_style_edge_score": round(rally_edge, 2),
        "table_tennis_momentum_edge_score": round(momentum_edge, 2),
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(TABLE_TENNIS_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": TABLE_TENNIS_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in TABLE_TENNIS_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in TABLE_TENNIS_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [field for field in TABLE_TENNIS_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _volleyball_format_calibration(input_stats: dict[str, Any]) -> str:
    sets = _safe_float(input_stats.get("best_of_sets"))
    text = str(input_stats.get("match_format") or "").strip().lower().replace("-", "_").replace(" ", "_")
    if sets in {3, 5}:
        return f"best_of_{int(sets)}"
    if "best_of_3" in text or text in {"bo3", "best3"}:
        return "best_of_3"
    if "best_of_5" in text or text in {"bo5", "best5"}:
        return "best_of_5"
    return "unknown"


def _volleyball_court_calibration(input_stats: dict[str, Any]) -> str:
    text = str(input_stats.get("court_type") or "").strip().lower()
    if "beach" in text or "sand" in text:
        return "beach"
    if "indoor" in text or "court" in text:
        return "indoor"
    return "unknown"


def _volleyball_gender_calibration(input_stats: dict[str, Any]) -> str:
    text = str(input_stats.get("gender_format") or "").strip().lower()
    if text.startswith("men") or text in {"m", "male", "mens"}:
        return "mens"
    if text.startswith("women") or text in {"w", "female", "womens"}:
        return "womens"
    return "unknown"


def _estimate_volleyball_sideout_attack_block_serve_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _volleyball_full_inputs_missing(input_stats, payload) + _volleyball_market_specific_missing(market, input_stats, payload)
    if missing or odds_american is None:
        return None

    market_key = _normal_market_key(input_stats.get("market") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    team_text = str(input_stats.get("team") or "").strip().lower()
    selected_team = selection_text in {"", team_text} or team_text in selection_text

    def n(field: str, default: float = 0.0) -> float:
        value = _safe_float(input_stats.get(field), default)
        return default if value is None else value

    implied_probability = implied_probability_from_american(odds_american)
    format_calibration = _volleyball_format_calibration(input_stats)
    court_calibration = _volleyball_court_calibration(input_stats)
    gender_calibration = _volleyball_gender_calibration(input_stats)
    sideout_calibration = any(input_stats.get(field) is not None for field in ("team_sideout_rate", "opponent_sideout_rate", "team_attack_rating", "opponent_attack_rating"))
    serve_receive_calibration = any(input_stats.get(field) is not None for field in ("team_serve_rating", "opponent_serve_rating", "team_receive_rating", "opponent_receive_rating"))
    deciding_set_calibration = any(input_stats.get(field) is not None for field in ("team_deciding_set_win_rate", "opponent_deciding_set_win_rate", "team_clutch_rating", "opponent_clutch_rating"))

    rating_edge = (n("team_rating") - n("opponent_rating")) * 0.040 + (n("team_elo") - n("opponent_elo")) * 0.004
    form_edge = (n("team_recent_win_rate") - n("opponent_recent_win_rate")) * 3.0 + (n("team_recent_form") - n("opponent_recent_form")) * 0.028
    sideout_edge = (
        (n("team_attack_rating") - n("opponent_attack_rating")) * 0.030
        + (n("team_kill_rate") - n("opponent_kill_rate")) * 4.4
        + (n("team_hitting_percentage") - n("opponent_hitting_percentage")) * 5.2
        + (n("team_sideout_rate") - n("opponent_sideout_rate")) * 5.4
        + (n("team_transition_attack_rating") - n("opponent_transition_attack_rating")) * 0.024
        + (n("opponent_error_rate") - n("team_error_rate")) * 4.0
    )
    serve_receive_edge = (
        (n("team_serve_rating") - n("opponent_serve_rating")) * 0.025
        + (n("team_ace_rate") - n("opponent_ace_rate")) * 4.0
        + (n("opponent_service_error_rate") - n("team_service_error_rate")) * 2.8
        + (n("team_receive_rating") - n("opponent_receive_rating")) * 0.030
        + (n("team_pass_rating") - n("opponent_pass_rating")) * 0.025
        + (n("team_first_contact_rating") - n("opponent_first_contact_rating")) * 0.022
    )
    block_defense_edge = (
        (n("team_block_rating") - n("opponent_block_rating")) * 0.026
        + (n("team_block_rate") - n("opponent_block_rate")) * 3.0
        + (n("team_dig_rate") - n("opponent_dig_rate")) * 0.045
        + (n("team_defensive_rating") - n("opponent_defensive_rating")) * 0.022
        + (n("team_floor_defense_rating") - n("opponent_floor_defense_rating")) * 0.020
    )
    momentum_edge = (
        (n("team_set_win_rate") - n("opponent_set_win_rate")) * 3.2
        + (n("team_deciding_set_win_rate") - n("opponent_deciding_set_win_rate")) * 2.0
        + (n("team_clutch_rating") - n("opponent_clutch_rating")) * 0.024
        + (n("team_momentum_rating") - n("opponent_momentum_rating")) * 0.020
    )
    context_edge = (
        (n("team_injury_availability_rating") - n("opponent_injury_availability_rating")) * 2.6
        + (n("key_player_availability") - n("opponent_key_player_availability")) * 2.2
        + (n("rest_days") - n("opponent_rest_days")) * 0.10
        + (n("opponent_travel_fatigue") - n("travel_fatigue")) * 1.0
        + n("venue_rating") * (0.16 if str(input_stats.get("home_away")).lower() == "home" and not input_stats.get("neutral_site") else 0.0)
    )
    altitude_drag = max(0.0, n("altitude_rating") - 0.55) * 0.18
    team_edge_score = rating_edge + form_edge + sideout_edge + serve_receive_edge + block_defense_edge + momentum_edge + context_edge - altitude_drag
    if not selected_team and market_key not in {"total_sets", "total_points", "alt_total_sets", "alt_total_points"}:
        team_edge_score *= -1

    raw_model_probability = _logistic_probability(team_edge_score, 2.9)
    projected_sets = max(3.0, min(n("best_of_sets", 5), n("player_sets_projection", n("best_of_sets", 5) * 0.82)))
    projected_total_points = max(120.0, projected_sets * 46.0 + (n("team_attack_rating") + n("opponent_attack_rating") - 164.0) * 0.35)
    projected_team_points = projected_total_points * (0.50 + max(-0.08, min(0.08, team_edge_score / 60.0)))
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line") or input_stats.get("player_prop_line")))
    if market_key in {"set_winner", "first_set_winner", "second_set_winner", "third_set_winner", "fourth_set_winner", "fifth_set_winner"}:
        set_multiplier = 0.70 if market_key in {"fourth_set_winner", "fifth_set_winner"} else 0.84
        raw_model_probability = _logistic_probability(team_edge_score * set_multiplier, 2.25)
    elif market_key in {"set_handicap", "alt_set_handicap"}:
        raw_model_probability = _logistic_probability(team_edge_score + (line or 0), 2.35)
    elif market_key == "point_spread":
        raw_model_probability = _logistic_probability(team_edge_score * 5.8 + (line or 0), 8.0)
    elif market_key in {"total_sets", "alt_total_sets"}:
        total_line = line if line is not None else 4.5
        over_probability = _logistic_probability(projected_sets - total_line, 0.85)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"total_points", "alt_total_points"}:
        total_line = line if line is not None else 184.5
        over_probability = _logistic_probability(projected_total_points - total_line, 12.0)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key == "team_total_points":
        total_line = line if line is not None else 92.5
        over_probability = _logistic_probability(projected_team_points - total_line, 8.5)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key == "correct_score":
        raw_model_probability = max(0.05, min(0.38, _logistic_probability(abs(team_edge_score) - 1.1, 2.1)))
    elif market_key in VOLLEYBALL_PROP_MARKETS:
        prop_line = line if line is not None else n("player_prop_line", 10.5)
        projection_field = {
            "player_kills": "player_kills_projection",
            "player_aces": "player_aces_projection",
            "player_blocks": "player_blocks_projection",
            "player_digs": "player_digs_projection",
            "player_assists": "player_assists_projection",
            "player_points": "player_points_projection",
        }[market_key]
        scale = 4.2 if market_key in {"player_kills", "player_points", "player_assists"} else 1.7
        raw_model_probability = _logistic_probability(n(projection_field) - prop_line, scale)

    calibrated_probability = raw_model_probability
    true_probability = max(0.04, min(0.94, calibrated_probability))
    sanity_flags = ["volleyball probability cap applied"] if true_probability != calibrated_probability else []

    confidence = 74.0
    risk_flags: list[str] = []
    if (_safe_float(input_stats.get("book_count"), 0) or 0) < 4:
        confidence -= 4
        risk_flags.append("book count too low")
    if n("team_injury_availability_rating") < 0.78 or n("key_player_availability") < 0.75:
        confidence -= 9
        risk_flags.append("team availability risk")
    if market_key in {"correct_score", "player_aces", "fourth_set_winner", "fifth_set_winner"}:
        confidence -= 7
        risk_flags.append("volatile market")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")

    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=true_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)

    return {
        "model_status": "active", "estimated_true_probability": true_probability,
        "true_probability": true_probability, "final_probability": true_probability,
        "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested, "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "volleyball sanity cap" if sanity_flags else None,
        "market_anchor_probability": None,
        "league_calibration_applied": "volleyball",
        "format_calibration_applied": format_calibration,
        "court_calibration_applied": court_calibration,
        "gender_calibration_applied": gender_calibration,
        "sideout_calibration_applied": sideout_calibration,
        "serve_receive_calibration_applied": serve_receive_calibration,
        "deciding_set_calibration_applied": deciding_set_calibration,
        "volleyball_team_edge_score": round(team_edge_score, 2),
        "volleyball_projected_sets": round(projected_sets, 2),
        "volleyball_projected_total_points": round(projected_total_points, 2),
        "volleyball_projected_team_points": round(projected_team_points, 2),
        "volleyball_sideout_edge_score": round(sideout_edge, 2),
        "volleyball_serve_receive_edge_score": round(serve_receive_edge, 2),
        "volleyball_block_defense_edge_score": round(block_defense_edge, 2),
        "volleyball_momentum_edge_score": round(momentum_edge, 2),
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(VOLLEYBALL_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": VOLLEYBALL_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in VOLLEYBALL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in VOLLEYBALL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [field for field in VOLLEYBALL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _afl_weather_calibration(input_stats: dict[str, Any]) -> str:
    rain = _safe_float(input_stats.get("rain_probability"), 0) or 0
    wind = _safe_float(input_stats.get("wind_speed"), 0) or 0
    risk = _safe_float(input_stats.get("weather_risk"), 0) or 0
    ground = str(input_stats.get("ground_condition") or "").strip().lower()
    wet = rain >= 0.45 or risk >= 0.55 or any(term in ground for term in ("wet", "soft", "heavy", "mud"))
    windy = wind >= 28 or "wind" in ground
    if wet and windy:
        return "mixed"
    if wet:
        return "wet"
    if windy:
        return "windy"
    if any(value is not None for value in (input_stats.get("rain_probability"), input_stats.get("wind_speed"), input_stats.get("weather_risk"), input_stats.get("ground_condition"))):
        return "dry"
    return "unknown"


def _afl_ground_calibration(input_stats: dict[str, Any]) -> str:
    text = str(input_stats.get("ground_condition") or "").strip().lower()
    if any(term in text for term in ("heavy", "mud", "waterlogged")):
        return "heavy"
    if any(term in text for term in ("soft", "wet", "slow")):
        return "soft"
    if any(term in text for term in ("firm", "good", "dry", "fast")):
        return "firm"
    return "unknown"


def _estimate_afl_clearance_inside50_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _afl_full_inputs_missing(input_stats, payload) + _afl_market_specific_missing(market, input_stats, payload)
    if missing or odds_american is None:
        return None

    market_key = _normal_market_key(input_stats.get("market") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    team_text = str(input_stats.get("team") or "").strip().lower()
    selected_team = selection_text in {"", team_text} or team_text in selection_text

    def n(field: str, default: float = 0.0) -> float:
        value = _safe_float(input_stats.get(field), default)
        return default if value is None else value

    implied_probability = implied_probability_from_american(odds_american)
    weather_calibration = _afl_weather_calibration(input_stats)
    ground_calibration = _afl_ground_calibration(input_stats)
    clearance_calibration = any(input_stats.get(field) is not None for field in ("team_clearance_rate", "opponent_clearance_rate", "team_center_clearance_rate", "opponent_center_clearance_rate"))
    inside50_calibration = any(input_stats.get(field) is not None for field in ("team_inside50_rate", "opponent_inside50_rate", "team_inside50_conversion_rate", "opponent_inside50_conversion_rate"))
    ruck_calibration = any(input_stats.get(field) is not None for field in ("team_ruck_rating", "opponent_ruck_rating", "team_hitout_win_rate", "opponent_hitout_win_rate"))

    scoring_power = (
        n("team_expected_score_for") * 0.46
        + n("team_points_for") * 0.24
        + n("team_scoring_shot_rate") * 0.16
        + n("team_inside50_rate") * 0.05
        + n("team_inside50_conversion_rate") * 18
        + n("team_goal_accuracy") * 10
    )
    opponent_scoring_power = (
        n("opponent_expected_score_for") * 0.46
        + n("opponent_points_for") * 0.24
        + n("opponent_scoring_shot_rate") * 0.16
        + n("opponent_inside50_rate") * 0.05
        + n("opponent_inside50_conversion_rate") * 18
        + n("opponent_goal_accuracy") * 10
    )
    defense_allowance = n("team_expected_score_against") * 0.44 + n("team_points_against") * 0.30
    opponent_defense_allowance = n("opponent_expected_score_against") * 0.44 + n("opponent_points_against") * 0.30
    clearance_edge = (
        (n("team_clearance_rate") - n("opponent_clearance_rate")) * 0.18
        + (n("team_center_clearance_rate") - n("opponent_center_clearance_rate")) * 0.12
        + (n("team_stoppage_clearance_rate") - n("opponent_stoppage_clearance_rate")) * 0.10
        + (n("team_contested_possession_rate") - n("opponent_contested_possession_rate")) * 0.05
        + (n("team_uncontested_possession_rate") - n("opponent_uncontested_possession_rate")) * 0.015
        + (n("team_disposal_efficiency") - n("opponent_disposal_efficiency")) * 11
    )
    inside50_edge = (
        (n("team_inside50_rate") - n("opponent_inside50_rate")) * 0.08
        + (n("team_inside50_conversion_rate") - n("opponent_inside50_conversion_rate")) * 16
        + (n("team_marks_inside50_rate") - n("opponent_marks_inside50_rate")) * 0.20
        + (n("team_intercept_mark_rate") - n("opponent_intercept_mark_rate")) * 0.12
    )
    pressure_edge = (
        (n("team_pressure_rating") - n("opponent_pressure_rating")) * 0.08
        + (n("team_tackle_rate") - n("opponent_tackle_rate")) * 0.04
        + (n("team_rebound50_rate") - n("opponent_rebound50_rate")) * 0.08
        + (n("opponent_turnover_rate") - n("team_turnover_rate")) * 0.10
    )
    ruck_edge = (
        (n("team_ruck_rating") - n("opponent_ruck_rating")) * 0.06
        + (n("team_hitout_win_rate") - n("opponent_hitout_win_rate")) * 4
    )
    availability_edge = (
        (n("key_player_availability") - n("opponent_key_player_availability")) * 7
        + (n("team_injury_availability_rating") - n("opponent_injury_availability_rating")) * 6
        + (n("rest_days") - n("opponent_rest_days")) * 0.32
        + (n("opponent_travel_fatigue") - n("travel_fatigue")) * 3.0
    )
    home_edge = 3.0 if str(input_stats.get("home_away") or "").lower() == "home" and not input_stats.get("neutral_site") else 0.0
    weather_drag = 5.5 if weather_calibration == "mixed" else (4.2 if weather_calibration in {"wet", "windy"} else 0.0)
    ground_drag = 3.0 if ground_calibration == "heavy" else (1.5 if ground_calibration == "soft" else 0.0)
    umpire_drag = max(0.0, n("umpire_free_kick_rate") - 44.0) * 0.10
    projected_team_points = max(35.0, scoring_power * 0.58 + opponent_defense_allowance * 0.36 + clearance_edge + inside50_edge + pressure_edge + ruck_edge + availability_edge + home_edge - weather_drag - ground_drag - umpire_drag)
    projected_opponent_points = max(35.0, opponent_scoring_power * 0.58 + defense_allowance * 0.36 - clearance_edge * 0.45 - inside50_edge * 0.52 - pressure_edge * 0.45 - ruck_edge * 0.35 - availability_edge * 0.35 + weather_drag * 0.15 + ground_drag * 0.10)
    projected_margin = projected_team_points - projected_opponent_points
    projected_total = projected_team_points + projected_opponent_points

    if not selected_team and market_key not in {"total_points", "first_half_total", "quarter_total", "alt_total_points"}:
        projected_margin *= -1

    raw_model_probability = _logistic_probability(projected_margin, 18.0)
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line") or input_stats.get("player_prop_line")))
    if market_key in {"spread", "handicap", "alt_spread"}:
        raw_model_probability = _logistic_probability(projected_margin + (line or 0), 16.0)
    elif market_key in {"total_points", "alt_total_points"}:
        total_line = line if line is not None else 170.5
        over_probability = _logistic_probability(projected_total - total_line, 22.0)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"team_total_points", "alt_team_total_points"}:
        total_line = line if line is not None else 85.5
        over_probability = _logistic_probability(projected_team_points - total_line, 15.0)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key == "first_half_winner":
        raw_model_probability = _logistic_probability(projected_margin * 0.50, 10.0)
    elif market_key == "first_half_spread":
        raw_model_probability = _logistic_probability(projected_margin * 0.50 + (line or 0), 8.5)
    elif market_key == "first_half_total":
        total_line = line if line is not None else 84.5
        over_probability = _logistic_probability(projected_total * 0.50 - total_line, 12.0)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key == "quarter_winner":
        raw_model_probability = _logistic_probability(projected_margin * 0.25, 6.0)
    elif market_key == "quarter_spread":
        raw_model_probability = _logistic_probability(projected_margin * 0.25 + (line or 0), 5.5)
    elif market_key == "quarter_total":
        total_line = line if line is not None else 42.5
        over_probability = _logistic_probability(projected_total * 0.25 - total_line, 7.5)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"winning_margin", "exact_margin"}:
        target_margin = abs(line if line is not None else 12.5)
        raw_model_probability = max(0.03, min(0.42, _logistic_probability(8.0 - abs(abs(projected_margin) - target_margin), 7.0)))
    elif market_key in AFL_PROP_MARKETS:
        prop_line = line if line is not None else n("player_prop_line", 1.5)
        if market_key == "player_goals":
            raw_model_probability = _logistic_probability(n("player_goals_projection") - prop_line, 0.8)
        elif market_key == "player_disposals":
            raw_model_probability = _logistic_probability(n("player_disposals_projection") - prop_line, 4.5)
        elif market_key == "player_marks":
            raw_model_probability = _logistic_probability(n("player_marks_projection") - prop_line, 2.0)
        elif market_key == "player_tackles":
            raw_model_probability = _logistic_probability(n("player_tackles_projection") - prop_line, 2.0)
        elif market_key == "player_hitouts":
            raw_model_probability = _logistic_probability(n("player_hitouts_projection") - prop_line, 5.0)
        elif market_key == "player_fantasy_points":
            raw_model_probability = _logistic_probability(n("player_fantasy_points_projection") - prop_line, 12.0)
        elif market_key == "anytime_goal_scorer":
            raw_model_probability = max(0.04, min(0.82, n("player_anytime_goal_probability", 0.35)))
        elif market_key == "first_goal_scorer":
            raw_model_probability = max(0.02, min(0.25, n("player_first_goal_probability", 0.07)))

    calibrated_probability = raw_model_probability
    true_probability = max(0.04, min(0.94, calibrated_probability))
    sanity_flags = ["afl probability cap applied"] if true_probability != calibrated_probability else []

    confidence = 74.0
    risk_flags: list[str] = []
    if (_safe_float(input_stats.get("book_count"), 0) or 0) < 4:
        confidence -= 4
        risk_flags.append("book count too low")
    if weather_calibration in {"wet", "windy", "mixed"}:
        confidence -= 5
        risk_flags.append("weather volatility")
    if ground_calibration in {"soft", "heavy"}:
        confidence -= 4
        risk_flags.append("ground condition volatility")
    if n("key_player_availability") < 0.75 or n("team_injury_availability_rating") < 0.78:
        confidence -= 9
        risk_flags.append("key player availability risk")
    if n("team_ruck_rating") < 65 or n("team_hitout_win_rate") < 0.40:
        confidence -= 5
        risk_flags.append("ruck volatility")
    if market_key in {"first_goal_scorer", "winning_margin", "exact_margin", "quarter_winner"}:
        confidence -= 6
        risk_flags.append("volatile market")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")

    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=true_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)

    return {
        "model_status": "active", "estimated_true_probability": true_probability,
        "true_probability": true_probability, "final_probability": true_probability,
        "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested, "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "afl sanity cap" if sanity_flags else None,
        "market_anchor_probability": None,
        "league_calibration_applied": "afl",
        "venue_calibration_applied": "venue" if str(input_stats.get("venue") or "").strip() else "unknown",
        "weather_calibration_applied": weather_calibration,
        "ground_calibration_applied": ground_calibration,
        "clearance_calibration_applied": clearance_calibration,
        "inside50_calibration_applied": inside50_calibration,
        "ruck_calibration_applied": ruck_calibration,
        "afl_projected_team_points": round(projected_team_points, 2),
        "afl_projected_opponent_points": round(projected_opponent_points, 2),
        "afl_projected_margin": round(projected_margin, 2),
        "afl_projected_total": round(projected_total, 2),
        "afl_clearance_edge_score": round(clearance_edge, 2),
        "afl_inside50_edge_score": round(inside50_edge, 2),
        "afl_ruck_edge_score": round(ruck_edge, 2),
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(AFL_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": AFL_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in AFL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in AFL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [field for field in AFL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _nascar_series_calibration(raw_series: Any) -> str:
    text = str(raw_series or "").strip().lower().replace("-", "_").replace(" ", "_")
    if "xfinity" in text:
        return "xfinity"
    if "truck" in text or "craftsman" in text:
        return "truck"
    if "cup" in text or text in {"nascar", "nascar_cup"}:
        return "cup"
    return "unknown"


def _nascar_track_type_calibration(input_stats: dict[str, Any]) -> str:
    text = str(input_stats.get("track_type") or "").strip().lower().replace("-", "_").replace(" ", "_")
    if input_stats.get("superspeedway_race") or "superspeedway" in text or "plate" in text:
        return "superspeedway"
    if input_stats.get("road_course_race") or "road" in text:
        return "road_course"
    if "dirt" in text:
        return "dirt"
    if input_stats.get("short_track_race") or "short" in text:
        return "short_track"
    if input_stats.get("intermediate_track_race") or "intermediate" in text or "oval" in text:
        return "intermediate"
    return "unknown"


def _nascar_environment_calibration(input_stats: dict[str, Any]) -> str:
    text = str(input_stats.get("day_night_transition") or "").strip().lower().replace("-", "_").replace(" ", "_")
    precip = _safe_float(input_stats.get("weather_precipitation_probability"), 0) or 0
    if precip > 1:
        precip = precip / 100
    if precip >= 0.35:
        return "wet"
    if text in {"day_to_night", "day/night", "day_night", "transition"}:
        return "day_to_night"
    if "night" in text:
        return "night"
    if "day" in text or precip < 0.35:
        return "dry"
    return "unknown"


def _estimate_nascar_monte_carlo_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _nascar_full_inputs_missing(input_stats, payload) + _nascar_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    driver_text = str(input_stats.get("driver") or "").strip().lower()
    opponent_text = str(input_stats.get("opponent") or "").strip().lower()
    selected_driver = not opponent_text or selection_text == driver_text or driver_text in selection_text
    field_size = max(8.0, min(45.0, number("field_size", 36.0)))
    starting_position = max(1.0, min(field_size, number("starting_position", field_size / 2)))
    opponent_starting_position = max(1.0, min(field_size, number("opponent_starting_position", field_size / 2)))
    dnf_probability = max(0.01, min(0.75, _safe_probability(input_stats.get("dnf_probability")) or number("dnf_probability", 0.08)))
    opponent_dnf_probability = max(0.01, min(0.75, _safe_probability(input_stats.get("opponent_dnf_probability")) or number("opponent_dnf_probability", 0.09)))
    crash_risk = max(0.0, min(0.75, _safe_probability(input_stats.get("crash_risk")) or number("crash_risk", 0.07)))
    opponent_crash_risk = max(0.0, min(0.75, _safe_probability(input_stats.get("opponent_crash_risk")) or number("opponent_crash_risk", 0.08)))
    caution_probability = max(0.01, min(0.95, _safe_probability(input_stats.get("caution_probability")) or number("caution_probability", 0.42)))
    overtime_probability = max(0.0, min(0.75, _safe_probability(input_stats.get("overtime_probability")) or number("overtime_probability", 0.16)))

    series_calibration = _nascar_series_calibration(input_stats.get("series") or payload.get("league"))
    track_calibration = _nascar_track_type_calibration(input_stats)
    environment_calibration = _nascar_environment_calibration(input_stats)
    superspeedway = track_calibration == "superspeedway"
    road_course = track_calibration == "road_course"
    short_track = track_calibration == "short_track"

    track_position_weight = 0.24 + number("track_position_importance") * (0.18 if not superspeedway else 0.08)
    practice_edge = (
        (number("opponent_practice_rank", field_size / 2) - number("practice_rank", field_size / 2)) * 0.12
        + (number("practice_single_lap_speed") - number("opponent_practice_single_lap_speed")) * 0.09
        + (number("practice_5_lap_average") - number("opponent_practice_5_lap_average")) * 0.11
        + (number("practice_10_lap_average") - number("opponent_practice_10_lap_average")) * 0.13
        + (number("practice_15_lap_average") - number("opponent_practice_15_lap_average")) * 0.14
    )
    speed_edge = (
        (number("car_speed_rating") - number("opponent_car_speed_rating")) * 0.10
        + (number("long_run_speed_rating") - number("opponent_long_run_speed_rating")) * (0.12 if not superspeedway else 0.06)
        + (number("short_run_speed_rating") - number("opponent_short_run_speed_rating")) * (0.08 if not short_track else 0.12)
        + (number("clean_air_speed_rating") - number("opponent_clean_air_speed_rating")) * 0.07
        + (number("dirty_air_speed_rating") - number("opponent_dirty_air_speed_rating")) * (0.06 + number("passing_difficulty") * 0.03)
    )
    driver_edge = (
        (number("driver_rating") - number("opponent_driver_rating")) * 0.07
        + (number("season_driver_rating") - number("opponent_season_driver_rating")) * 0.05
        + (number("track_history_rating") - number("opponent_track_history_rating")) * (0.07 if not road_course else 0.04)
        + (number("track_type_rating") - number("opponent_track_type_rating")) * 0.07
        + (number("recent_form_rating") - number("opponent_recent_form_rating")) * 0.04
    )
    racecraft_edge = (
        (number("restart_rating") - number("opponent_restart_rating")) * (0.055 + number("caution_probability") * 0.02)
        + (number("passing_rating") - number("opponent_passing_rating")) * 0.045
        + (number("defense_rating") - number("opponent_defense_rating")) * 0.035
        + (number("tire_management_rating") - number("opponent_tire_management_rating")) * (0.045 + number("tire_wear_rating") * 0.02)
    )
    pit_strategy_edge = (
        (number("pit_crew_rating") - number("opponent_pit_crew_rating")) * (0.05 + number("pit_road_sensitivity") * 0.025)
        + (number("crew_chief_rating") - number("opponent_crew_chief_rating")) * 0.04
        + (number("strategy_rating") - number("opponent_strategy_rating")) * (0.045 + number("fuel_strategy_importance") * 0.02)
    )
    context_edge = (
        (opponent_starting_position - starting_position) * track_position_weight
        + (number("opponent_qualifying_position", opponent_starting_position) - number("qualifying_position", starting_position)) * 0.13
        + (number("manufacturer_rating") - number("opponent_manufacturer_rating")) * 0.035
        + (number("team_momentum_rating") - number("opponent_team_momentum_rating")) * 0.025
    )
    risk_edge = (
        (opponent_dnf_probability - dnf_probability) * 8.0
        + (opponent_crash_risk - crash_risk) * 5.5
        + (number("opponent_mechanical_failure_risk") - number("mechanical_failure_risk")) * 4.0
        + (number("opponent_penalty_risk") - number("penalty_risk")) * 2.5
        + (number("opponent_inspection_risk") - number("inspection_risk")) * 2.0
        - (1.4 if input_stats.get("backup_car") else 0)
        + (1.4 if input_stats.get("opponent_backup_car") else 0)
        - (1.2 if input_stats.get("engine_change_penalty") else 0)
        + (1.2 if input_stats.get("opponent_engine_change_penalty") else 0)
        - (1.6 if input_stats.get("start_at_rear") else 0)
        + (1.6 if input_stats.get("opponent_start_at_rear") else 0)
    )
    track_shape_edge = 0.0
    if superspeedway:
        track_shape_edge += (number("drafting_importance") + number("superspeedway_pack_variance")) * 0.10
        speed_edge *= 0.55
        context_edge *= 0.55
    if road_course:
        track_shape_edge += (number("road_course_skill_importance") - 0.5) * 0.8
        racecraft_edge *= 1.08
    if short_track:
        track_shape_edge -= number("short_track_contact_variance") * crash_risk * 1.2
    if track_calibration == "intermediate":
        track_shape_edge += (number("aero_sensitivity") + number("intermediate_track_aero_variance")) * 0.08

    selected_edge_score = practice_edge + speed_edge + driver_edge + racecraft_edge + pit_strategy_edge + context_edge + risk_edge + track_shape_edge
    if not selected_driver:
        selected_edge_score = -selected_edge_score
        starting_position = opponent_starting_position
        dnf_probability = opponent_dnf_probability
        crash_risk = opponent_crash_risk
    volatility = 1.0 + caution_probability * 0.75 + overtime_probability * 0.45 + (0.9 if superspeedway else 0.0)
    matchup_probability = _logistic_probability(selected_edge_score, 7.0 + volatility * 1.5)
    finish_score = selected_edge_score + ((field_size / 2) - starting_position) * (0.16 if not superspeedway else 0.06) + (1 - dnf_probability) * 2.0

    raw_model_probability = matchup_probability
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    if market_key == "race_winner":
        baseline = 1 / field_size
        raw_model_probability = max(0.01, min(0.52, baseline * (1 + max(-0.65, min(2.8, finish_score / 8.5)))))
    elif market_key in {"top_3_finish", "alt_top_5"}:
        cutoff = 3 if market_key == "top_3_finish" else 5
        raw_model_probability = _logistic_probability(finish_score - (field_size / 2 - cutoff), 8.5 + volatility)
    elif market_key in {"top_5_finish", "top_10_finish", "top_20_finish", "alt_top_10", "alt_top_20"}:
        cutoff = 5 if "5" in market_key else 10 if "10" in market_key else 20
        raw_model_probability = _logistic_probability(finish_score - (field_size / 2 - cutoff), 9.0 + volatility)
    elif market_key in {"driver_matchup", "group_winner"}:
        raw_model_probability = matchup_probability if market_key == "driver_matchup" else max(0.08, min(0.68, matchup_probability * 0.86))
    elif market_key in {"stage_1_winner", "stage_2_winner", "stage_3_winner"}:
        stage_edge = selected_edge_score + (field_size / 2 - starting_position) * 0.28 + (number("restart_rating") - number("opponent_restart_rating")) * 0.08
        raw_model_probability = max(0.01, min(0.46, (1 / field_size) * (1 + max(-0.6, min(3.0, stage_edge / 7.0)))))
    elif market_key in {"pole_winner", "qualifying_matchup"}:
        qual_edge = (
            (number("practice_single_lap_speed") - number("opponent_practice_single_lap_speed")) * 0.15
            + (number("car_speed_rating") - number("opponent_car_speed_rating")) * 0.07
            + (number("opponent_inspection_risk") - number("inspection_risk")) * 2.0
        )
        raw_model_probability = max(0.01, min(0.40, (1 / field_size) * (1 + max(-0.5, min(2.8, qual_edge / 7.0))))) if market_key == "pole_winner" else _logistic_probability(qual_edge, 6.0)
    elif market_key == "fastest_lap":
        lap_edge = (number("clean_air_speed_rating") - number("opponent_clean_air_speed_rating")) * 0.11 + (number("short_run_speed_rating") - number("opponent_short_run_speed_rating")) * 0.08 + number("tire_wear_rating") * 0.25
        raw_model_probability = max(0.01, min(0.42, (1 / field_size) * (1 + max(-0.5, min(3.2, lap_edge / 6.5)))))
    elif market_key in {"driver_to_retire", "not_classified"}:
        retire_probability = max(0.02, min(0.75, dnf_probability + crash_risk * 0.35 + number("mechanical_failure_risk") * 0.25))
        raw_model_probability = retire_probability if market_key == "driver_to_retire" else retire_probability
    elif market_key in {"classified_finish", "lead_lap_finish"}:
        classified_probability = max(0.12, min(0.97, 1 - dnf_probability - crash_risk * 0.22))
        if market_key == "lead_lap_finish":
            classified_probability *= max(0.35, min(0.92, _logistic_probability(finish_score - 2.0, 8.0)))
        raw_model_probability = classified_probability
    elif market_key in {"laps_led", "driver_laps_led_over", "driver_laps_led_under"}:
        scheduled_laps = max(1.0, number("scheduled_laps", 200))
        expected_laps_led = max(0.0, scheduled_laps * max(0.0, min(0.45, 0.05 + _logistic_probability(finish_score + (field_size / 2 - starting_position) * 0.3, 8.0) * 0.28)))
        target = line if line is not None else expected_laps_led
        over_probability = _logistic_probability(expected_laps_led - target, max(4.0, scheduled_laps * 0.12))
        raw_model_probability = 1 - over_probability if market_key == "driver_laps_led_under" or "under" in selection_text else over_probability
    elif market_key == "finishing_position":
        projected_finish = max(1.0, min(field_size, (field_size / 2) - finish_score * 0.65))
        target = line if line is not None else projected_finish
        under_probability = _logistic_probability(target - projected_finish, 4.6 + volatility)
        raw_model_probability = 1 - under_probability if "over" in selection_text else under_probability
    elif market_key in {"caution_count_over", "caution_count_under"}:
        expected_cautions = max(1.0, 3.0 + caution_probability * 5.0 + number("multi_car_wreck_probability") * 3.0 + (1.5 if superspeedway else 0) + (0.8 if short_track else 0))
        target = line if line is not None else expected_cautions
        over_probability = _logistic_probability(expected_cautions - target, 1.8)
        raw_model_probability = 1 - over_probability if "under" in market_key or "under" in selection_text else over_probability
    elif market_key in {"green_flag_laps_over", "green_flag_laps_under"}:
        scheduled_laps = max(1.0, number("scheduled_laps", 200))
        expected_green = scheduled_laps * max(0.35, min(0.92, 1 - caution_probability * 0.38 - overtime_probability * 0.08))
        target = line if line is not None else expected_green
        over_probability = _logistic_probability(expected_green - target, max(6.0, scheduled_laps * 0.09))
        raw_model_probability = 1 - over_probability if "under" in market_key or "under" in selection_text else over_probability
    elif market_key == "overtime_finish":
        raw_model_probability = max(0.02, min(0.62, overtime_probability + caution_probability * 0.16 + number("multi_car_wreck_probability") * 0.12))
    elif market_key == "manufacturer_winner":
        manufacturer_edge = (
            number("manufacturer_speed_rating") * 0.08
            + number("manufacturer_reliability_rating") * 0.05
            + number("manufacturer_track_type_rating") * 0.05
            + number("manufacturer_recent_form_rating") * 0.04
            + number("manufacturer_driver_depth_rating") * 0.04
        )
        raw_model_probability = max(0.08, min(0.55, _logistic_probability(manufacturer_edge - 22, 8.0)))

    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.03, min(0.94, calibrated_probability))
    sanity_flags = ["nascar probability cap applied"] if true_probability != calibrated_probability else []

    confidence = 73.0
    risk_flags: list[str] = []
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4
        risk_flags.append("book count too low")
    if superspeedway:
        confidence -= 7
        risk_flags.append("superspeedway pack variance")
    if caution_probability >= 0.58 or overtime_probability >= 0.28:
        confidence -= 4
        risk_flags.append("race volatility")
    if dnf_probability >= 0.18 or opponent_dnf_probability >= 0.18 or crash_risk >= 0.18:
        confidence -= 6
        risk_flags.append("DNF/crash volatility")
    if input_stats.get("start_at_rear") or input_stats.get("backup_car") or input_stats.get("engine_change_penalty"):
        confidence -= 5
        risk_flags.append("start-at-rear/backup-car risk")
    if input_stats.get("inspection_risk") and number("inspection_risk") >= 0.18:
        confidence -= 4
        risk_flags.append("inspection risk")
    if environment_calibration in {"wet", "day_to_night"}:
        confidence -= 3
        risk_flags.append("race environment volatility")
    if market_key in {"fastest_lap", "laps_led", "driver_laps_led_over", "driver_laps_led_under", "stage_1_winner", "stage_2_winner", "stage_3_winner", "caution_count_over", "caution_count_under", "overtime_finish"}:
        confidence -= 4
        risk_flags.append("volatile market")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    if input_stats.get("practice_report_quality") == "low" or input_stats.get("qualifying_report_quality") == "low":
        confidence -= 5
        risk_flags.append("practice/qualifying data uncertainty")
    confidence = max(1, min(95, round(confidence, 2)))

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=true_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)

    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "final_probability": true_probability,
        "model_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested,
        "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "nascar sanity cap" if sanity_flags else None,
        "market_anchor_probability": market_anchor,
        "league_calibration_applied": "nascar",
        "series_calibration_applied": series_calibration,
        "track_type_calibration_applied": track_calibration,
        "race_environment_calibration_applied": environment_calibration,
        "driver_edge_score": round(selected_edge_score, 2),
        "matchup_probability": matchup_probability,
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(NASCAR_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": NASCAR_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in NASCAR_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in NASCAR_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {
            "provider_status": "available" if input_stats.get("provider_status") not in {None, "error"} else input_stats.get("provider_status") or "not_provided",
            "provider_enrichment_present": [field for field in NASCAR_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
        },
        "no_bet_flags": no_bet_flags,
    }


def _estimate_indycar_monte_carlo_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _indycar_full_inputs_missing(input_stats, payload) + _indycar_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    selected_driver = not input_stats.get("opponent") or str(input_stats.get("driver") or "").strip().lower() in selection_text
    field_size = max(8.0, min(36.0, number("field_size", 27)))
    start = max(1.0, min(field_size, number("starting_position", field_size / 2)))
    opp_start = max(1.0, min(field_size, number("opponent_starting_position", field_size / 2)))
    track_text = str(input_stats.get("track_type") or "").lower()
    if input_stats.get("indy_500_race") or input_stats.get("superspeedway_race") or "superspeedway" in track_text:
        track_calibration = "superspeedway"
    elif input_stats.get("street_course_race") or "street" in track_text:
        track_calibration = "street_course"
    elif input_stats.get("road_course_race") or "road" in track_text:
        track_calibration = "road_course"
    elif input_stats.get("oval_race") or "oval" in track_text:
        track_calibration = "oval"
    else:
        track_calibration = "unknown"
    precip = _safe_probability(input_stats.get("weather_precipitation_probability")) or 0
    environment_calibration = "wet" if precip >= 0.45 else "mixed" if precip >= 0.20 else "dry"
    dnf = max(0.01, min(0.70, _safe_probability(input_stats.get("dnf_probability")) or number("dnf_probability", 0.08)))
    opp_dnf = max(0.01, min(0.70, _safe_probability(input_stats.get("opponent_dnf_probability")) or number("opponent_dnf_probability", 0.09)))
    crash = max(0.0, min(0.70, _safe_probability(input_stats.get("crash_risk")) or number("crash_risk", 0.07)))
    caution = max(0.01, min(0.95, _safe_probability(input_stats.get("caution_probability")) or number("caution_probability", 0.42)))
    overtime = max(0.0, min(0.70, _safe_probability(input_stats.get("overtime_probability")) or number("overtime_probability", 0.12)))
    edge_score = (
        (number("opponent_practice_rank", field_size / 2) - number("practice_rank", field_size / 2)) * 0.14
        + (number("practice_single_lap_speed") - number("opponent_practice_single_lap_speed")) * 0.12
        + (number("practice_5_lap_average") - number("opponent_practice_5_lap_average")) * 0.13
        + (number("practice_10_lap_average") - number("opponent_practice_10_lap_average")) * 0.14
        + (number("driver_rating") - number("opponent_driver_rating")) * 0.07
        + (number("season_driver_rating") - number("opponent_season_driver_rating")) * 0.05
        + (number("car_speed_rating") - number("opponent_car_speed_rating")) * 0.10
        + (number("long_run_speed_rating") - number("opponent_long_run_speed_rating")) * 0.12
        + (number("traffic_speed_rating") - number("opponent_traffic_speed_rating")) * 0.07
        + (number("fuel_save_rating") - number("opponent_fuel_save_rating")) * 0.08
        + (number("pit_crew_rating") - number("opponent_pit_crew_rating")) * 0.05
        + (number("strategy_rating") - number("opponent_strategy_rating")) * 0.05
        + (number("restart_rating") - number("opponent_restart_rating")) * (0.05 + caution * 0.02)
        + (opp_start - start) * (0.18 + number("track_position_importance") * 0.12)
        + (number("opponent_manufacturer_rating") - number("manufacturer_rating")) * -0.035
        + (opp_dnf - dnf) * 7.0
        + (number("opponent_crash_risk") - crash) * 4.5
    )
    if track_calibration == "superspeedway":
        edge_score += (number("drafting_importance") + number("oval_pack_variance")) * 0.10
    if not selected_driver:
        edge_score = -edge_score
        start = opp_start
    volatility = 1 + caution * 0.55 + overtime * 0.35 + (0.45 if input_stats.get("indy_500_race") else 0)
    matchup_probability = _logistic_probability(edge_score, 6.8 + volatility)
    finish_score = edge_score + ((field_size / 2) - start) * 0.14 + (1 - dnf) * 1.8
    raw_model_probability = matchup_probability
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    if market_key == "race_winner":
        raw_model_probability = max(0.01, min(0.50, (1 / field_size) * (1 + max(-0.65, min(3.0, finish_score / 7.5)))))
    elif market_key in {"podium_finish", "top_5_finish", "top_10_finish", "top_15_finish", "alt_top_5", "alt_top_10", "alt_top_15"}:
        cutoff = 3 if market_key == "podium_finish" else 5 if "5" in market_key else 10 if "10" in market_key else 15
        raw_model_probability = _logistic_probability(finish_score - (field_size / 2 - cutoff), 8.4 + volatility)
    elif market_key in {"driver_matchup", "group_winner"}:
        raw_model_probability = matchup_probability if market_key == "driver_matchup" else max(0.08, min(0.68, matchup_probability * 0.86))
    elif market_key in {"pole_winner", "qualifying_matchup"}:
        q_edge = (number("practice_single_lap_speed") - number("opponent_practice_single_lap_speed")) * 0.18 + (number("car_speed_rating") - number("opponent_car_speed_rating")) * 0.06
        raw_model_probability = max(0.01, min(0.40, (1 / field_size) * (1 + max(-0.5, min(3.0, q_edge / 6.0))))) if market_key == "pole_winner" else _logistic_probability(q_edge, 5.8)
    elif market_key == "fastest_lap":
        raw_model_probability = max(0.01, min(0.40, (1 / field_size) * (1 + max(-0.5, min(3.1, edge_score / 6.0)))))
    elif market_key in {"driver_to_retire", "not_classified"}:
        raw_model_probability = max(0.02, min(0.70, dnf + crash * 0.35 + number("mechanical_failure_risk") * 0.25))
    elif market_key in {"classified_finish", "lead_lap_finish"}:
        raw_model_probability = max(0.12, min(0.97, 1 - dnf - crash * 0.22))
    elif market_key == "finishing_position":
        projected = max(1.0, min(field_size, (field_size / 2) - finish_score * 0.62))
        raw_model_probability = _logistic_probability((line if line is not None else projected) - projected, 4.4 + volatility)
    elif market_key == "laps_led":
        scheduled = max(1.0, number("scheduled_laps", 200))
        expected = scheduled * max(0.0, min(0.42, 0.05 + _logistic_probability(finish_score, 7.5) * 0.26))
        raw_model_probability = _logistic_probability(expected - (line if line is not None else expected), max(4.0, scheduled * 0.11))
    elif market_key in {"caution_count_over", "caution_count_under"}:
        expected = max(1.0, 2.6 + caution * 4.6 + number("multi_car_wreck_probability") * 2.4)
        over = _logistic_probability(expected - (line if line is not None else expected), 1.7)
        raw_model_probability = 1 - over if "under" in market_key else over
    elif market_key in {"green_flag_laps_over", "green_flag_laps_under"}:
        scheduled = max(1.0, number("scheduled_laps", 200))
        expected = scheduled * max(0.35, min(0.94, 1 - caution * 0.32 - overtime * 0.08))
        over = _logistic_probability(expected - (line if line is not None else expected), max(6.0, scheduled * 0.08))
        raw_model_probability = 1 - over if "under" in market_key else over
    elif market_key == "overtime_finish":
        raw_model_probability = max(0.02, min(0.58, overtime + caution * 0.13 + number("multi_car_wreck_probability") * 0.10))
    elif market_key == "manufacturer_winner":
        m_edge = number("manufacturer_speed_rating") * 0.08 + number("manufacturer_reliability_rating") * 0.05 + number("manufacturer_track_type_rating") * 0.05 + number("manufacturer_recent_form_rating") * 0.04 + number("manufacturer_driver_depth_rating") * 0.04
        raw_model_probability = max(0.08, min(0.55, _logistic_probability(m_edge - 22, 8.0)))
    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.03, min(0.94, calibrated_probability))
    sanity_flags = ["indycar probability cap applied"] if true_probability != calibrated_probability else []
    confidence = 73.0
    risk_flags: list[str] = []
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4; risk_flags.append("book count too low")
    if input_stats.get("indy_500_race"):
        confidence -= 4; risk_flags.append("Indy 500 pack/fuel variance")
    if caution >= 0.58 or overtime >= 0.25:
        confidence -= 4; risk_flags.append("race volatility")
    if dnf >= 0.18 or crash >= 0.18:
        confidence -= 6; risk_flags.append("DNF/crash volatility")
    if environment_calibration in {"wet", "mixed"}:
        confidence -= 4; risk_flags.append("weather volatility")
    if market_key in {"fastest_lap", "laps_led", "caution_count_over", "caution_count_under", "overtime_finish"}:
        confidence -= 4; risk_flags.append("volatile market")
    if input_stats.get("practice_report_quality") == "low" or input_stats.get("qualifying_report_quality") == "low":
        confidence -= 5; risk_flags.append("practice/qualifying data uncertainty")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))
    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(bankroll=bankroll, american_odds=odds_american, true_probability=true_probability, risk_profile=risk_profile, confidence=confidence)
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)
    return {"model_status": "active", "estimated_true_probability": true_probability, "true_probability": true_probability, "final_probability": true_probability, "model_probability": true_probability, "implied_probability": implied_probability, "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate", "suggested_stake": suggested, "raw_model_probability": raw_model_probability, "calibrated_model_probability": calibrated_probability, "probability_calibration_applied": bool(market_anchor is not None or sanity_flags), "probability_sanity_flags": sanity_flags, "probability_cap_reason": "indycar sanity cap" if sanity_flags else None, "market_anchor_probability": market_anchor, "league_calibration_applied": "indycar", "series_calibration_applied": "indycar", "track_type_calibration_applied": track_calibration, "race_environment_calibration_applied": environment_calibration, "driver_edge_score": round(edge_score, 2), "matchup_probability": matchup_probability, "risk_flags": risk_flags, "input_coverage": {"required_core_present": list(INDYCAR_REQUIRED_CORE_INPUTS), "required_market_specific_present": INDYCAR_REQUIRED_MARKET_INPUTS.get(market_key, []), "optional_enrichment_present": [f for f in INDYCAR_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None], "optional_enrichment_missing": [f for f in INDYCAR_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is None]}, "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [f for f in INDYCAR_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None]}, "no_bet_flags": no_bet_flags}


def _estimate_motogp_monte_carlo_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _motogp_full_inputs_missing(input_stats, payload) + _motogp_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    selected_rider = not input_stats.get("opponent") or str(input_stats.get("rider") or "").strip().lower() in selection_text
    field_size = max(8.0, min(26.0, number("field_size", 22)))
    grid = max(1.0, min(field_size, number("starting_grid_position", field_size / 2)))
    opp_grid = max(1.0, min(field_size, number("opponent_starting_grid_position", field_size / 2)))
    crash = max(0.0, min(0.75, _safe_probability(input_stats.get("crash_probability")) or number("crash_probability", 0.08)))
    opp_crash = max(0.0, min(0.75, _safe_probability(input_stats.get("opponent_crash_probability")) or number("opponent_crash_probability", 0.10)))
    rain = max(0.0, min(1.0, _safe_probability(input_stats.get("rain_probability")) or number("rain_probability", 0.05)))
    transition = max(0.0, min(1.0, _safe_probability(input_stats.get("dry_wet_transition_risk")) or number("dry_wet_transition_risk", 0.05)))
    session_text = str(input_stats.get("session_type") or "").lower()
    session_calibration = "sprint" if "sprint" in session_text else "qualifying" if "qual" in session_text else "practice" if "practice" in session_text else "race" if "race" in session_text else "unknown"
    track_text = str(input_stats.get("track_type") or "").lower()
    track_calibration = "flowing" if "flow" in track_text else "stop_go" if "stop" in track_text else "street" if "street" in track_text else "mixed" if "mixed" in track_text else "unknown"
    weather_calibration = "wet" if rain >= 0.55 else "mixed" if rain >= 0.25 or transition >= 0.30 else "dry"
    edge_score = (
        (number("opponent_practice_rank", field_size / 2) - number("practice_rank", field_size / 2)) * 0.12
        + (number("opponent_practice_lap_time") - number("practice_lap_time")) * 1.2
        + (number("practice_long_run_pace") - number("opponent_practice_long_run_pace")) * 0.10
        + (number("practice_short_run_pace") - number("opponent_practice_short_run_pace")) * 0.08
        + (number("rider_rating") - number("opponent_rider_rating")) * 0.07
        + (number("season_rider_rating") - number("opponent_season_rider_rating")) * 0.05
        + (number("bike_pace_rating") - number("opponent_bike_pace_rating")) * 0.10
        + (number("race_pace_rating") - number("opponent_race_pace_rating")) * 0.12
        + (number("braking_rating") - number("opponent_braking_rating")) * 0.055
        + (number("cornering_rating") - number("opponent_cornering_rating")) * 0.06
        + (number("launch_start_rating") - number("opponent_launch_start_rating")) * 0.05
        + (opp_grid - grid) * (0.28 + number("track_position_importance") * 0.18)
        + (number("wet_weather_rating") - number("opponent_wet_weather_rating")) * (0.02 + rain * 0.08)
        + (opp_crash - crash) * 4.8
        + (number("opponent_mechanical_failure_risk") - number("mechanical_failure_risk")) * 3.5
        + (number("rider_injury_adjustment") - number("opponent_rider_injury_adjustment")) * 1.4
        - (number("front_tire_stress") + number("rear_tire_stress")) * 0.18
    )
    if not selected_rider:
        edge_score = -edge_score
        grid = opp_grid
    volatility = 1 + crash + rain * 0.45 + transition * 0.55
    matchup_probability = _logistic_probability(edge_score, 6.6 + volatility)
    finish_score = edge_score + ((field_size / 2) - grid) * 0.22 + (1 - crash) * 1.6
    raw_model_probability = matchup_probability
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    if market_key == "race_winner":
        raw_model_probability = max(0.01, min(0.52, (1 / field_size) * (1 + max(-0.65, min(3.2, finish_score / 6.8)))))
    elif market_key in {"podium_finish", "alt_podium", "sprint_podium"}:
        raw_model_probability = _logistic_probability(finish_score - (field_size / 2 - 3), 7.5 + volatility)
    elif market_key in {"top_5_finish", "top_10_finish", "points_finish", "alt_top_5", "alt_top_10"}:
        cutoff = 5 if "5" in market_key else 10
        raw_model_probability = _logistic_probability(finish_score - (field_size / 2 - cutoff), 8.0 + volatility)
    elif market_key in {"rider_matchup", "group_winner"}:
        raw_model_probability = matchup_probability if market_key == "rider_matchup" else max(0.08, min(0.68, matchup_probability * 0.86))
    elif market_key in {"qualifying_winner", "qualifying_matchup"}:
        q_edge = edge_score + (number("qualifying_pace_rating") - number("opponent_qualifying_pace_rating")) * 0.12
        raw_model_probability = max(0.01, min(0.42, (1 / field_size) * (1 + max(-0.5, min(3.1, q_edge / 6.0))))) if market_key == "qualifying_winner" else _logistic_probability(q_edge, 5.7)
    elif market_key == "sprint_winner":
        raw_model_probability = max(0.01, min(0.48, (1 / field_size) * (1 + max(-0.6, min(3.1, finish_score / 6.5)))))
    elif market_key == "fastest_lap":
        raw_model_probability = max(0.01, min(0.40, (1 / field_size) * (1 + max(-0.5, min(3.0, edge_score / 6.0)))))
    elif market_key in {"rider_to_retire", "not_classified"}:
        raw_model_probability = max(0.02, min(0.72, crash + number("mechanical_failure_risk") * 0.3))
    elif market_key == "classified_finish":
        raw_model_probability = max(0.12, min(0.97, 1 - crash - number("mechanical_failure_risk") * 0.18))
    elif market_key == "finishing_position":
        projected = max(1.0, min(field_size, (field_size / 2) - finish_score * 0.64))
        raw_model_probability = _logistic_probability((line if line is not None else projected) - projected, 4.2 + volatility)
    elif market_key == "manufacturer_winner":
        raw_model_probability = max(0.08, min(0.55, _logistic_probability(number("manufacturer_pace_rating") * 0.08 + number("manufacturer_recent_form_rating") * 0.05 + number("manufacturer_rider_depth_rating") * 0.04 - 16, 8.0)))
    elif market_key == "team_winner":
        raw_model_probability = max(0.08, min(0.55, _logistic_probability(number("team_rider_1_rating") * 0.06 + number("team_strategy_rating") * 0.04 + number("team_bike_pace_rating") * 0.06 - 14, 8.0)))
    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.03, min(0.94, calibrated_probability))
    sanity_flags = ["motogp probability cap applied"] if true_probability != calibrated_probability else []
    confidence = 73.0
    risk_flags: list[str] = []
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4; risk_flags.append("book count too low")
    if weather_calibration in {"wet", "mixed"}:
        confidence -= 5; risk_flags.append("weather volatility")
    if crash >= 0.18 or opp_crash >= 0.18:
        confidence -= 6; risk_flags.append("crash volatility")
    if input_stats.get("sprint_weekend") and market_key in {"sprint_winner", "sprint_podium"}:
        confidence -= 3; risk_flags.append("sprint variance")
    if number("front_tire_stress") >= 0.75 or number("rear_tire_stress") >= 0.75:
        confidence -= 4; risk_flags.append("tire stress")
    if market_key in {"fastest_lap", "rider_to_retire", "not_classified", "sprint_winner"}:
        confidence -= 4; risk_flags.append("volatile market")
    if input_stats.get("practice_report_quality") == "low" or input_stats.get("qualifying_report_quality") == "low":
        confidence -= 5; risk_flags.append("practice/qualifying data uncertainty")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))
    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(bankroll=bankroll, american_odds=odds_american, true_probability=true_probability, risk_profile=risk_profile, confidence=confidence)
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)
    return {"model_status": "active", "estimated_true_probability": true_probability, "true_probability": true_probability, "final_probability": true_probability, "model_probability": true_probability, "implied_probability": implied_probability, "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate", "suggested_stake": suggested, "raw_model_probability": raw_model_probability, "calibrated_model_probability": calibrated_probability, "probability_calibration_applied": bool(market_anchor is not None or sanity_flags), "probability_sanity_flags": sanity_flags, "probability_cap_reason": "motogp sanity cap" if sanity_flags else None, "market_anchor_probability": market_anchor, "league_calibration_applied": "motogp", "session_calibration_applied": session_calibration, "track_type_calibration_applied": track_calibration, "weather_calibration_applied": weather_calibration, "rider_edge_score": round(edge_score, 2), "matchup_probability": matchup_probability, "risk_flags": risk_flags, "input_coverage": {"required_core_present": list(MOTOGP_REQUIRED_CORE_INPUTS), "required_market_specific_present": MOTOGP_REQUIRED_MARKET_INPUTS.get(market_key, []), "optional_enrichment_present": [f for f in MOTOGP_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None], "optional_enrichment_missing": [f for f in MOTOGP_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is None]}, "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [f for f in MOTOGP_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None]}, "no_bet_flags": no_bet_flags}


def _estimate_cricket_run_rate_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _cricket_full_inputs_missing(input_stats, payload) + _cricket_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    team_text = str(input_stats.get("team") or "").strip().lower()
    opponent_text = str(input_stats.get("opponent") or "").strip().lower()
    selected_team = not opponent_text or selection_text == team_text or team_text in selection_text

    calibration = _cricket_format_calibration(input_stats.get("format") or payload.get("league"))
    format_key = calibration["format"]
    baseline_total = calibration["baseline_total"]
    volatility = calibration["volatility"]

    team_phase_rr = (
        number("team_powerplay_run_rate") * 0.32
        + number("team_middle_overs_run_rate") * 0.34
        + number("team_death_overs_run_rate") * 0.34
    )
    opponent_phase_rr = (
        number("opponent_powerplay_run_rate") * 0.32
        + number("opponent_middle_overs_run_rate") * 0.34
        + number("opponent_death_overs_run_rate") * 0.34
    )
    run_rate_edge = team_phase_rr - opponent_phase_rr
    batting_edge = (number("team_batting_rating") - number("opponent_batting_rating")) * 0.032
    bowling_edge = (number("team_bowling_rating") - number("opponent_bowling_rating")) * 0.030
    fielding_edge = (number("team_fielding_rating") - number("opponent_fielding_rating")) * 0.018
    form_edge = (number("team_recent_form_rating") - number("opponent_recent_form_rating")) * 0.025
    wicket_resource_edge = (
        (number("team_wicket_taking_rate") - number("opponent_wicket_taking_rate")) * 7.5
        + (number("opponent_wicket_loss_rate") - number("team_wicket_loss_rate")) * 7.0
    )
    boundary_edge = (
        (number("team_boundary_rate") - number("opponent_boundary_rate")) * 8.0
        + (number("opponent_dot_ball_rate") - number("team_dot_ball_rate")) * 5.0
    )
    chase_edge = (number("team_chase_rating") - number("opponent_chase_rating")) * 0.018
    defend_edge = (number("team_defend_total_rating") - number("opponent_defend_total_rating")) * 0.014

    toss_winner = str(input_stats.get("toss_winner") or "").strip().lower()
    toss_decision = str(input_stats.get("toss_decision") or "").strip().lower()
    dew = number("dew_factor")
    wind = number("wind_factor")
    venue_chase = number("venue_chase_win_rate", 0.5)
    toss_edge = 0.0
    if toss_winner and toss_winner == team_text:
        if "bowl" in toss_decision:
            toss_edge += (venue_chase - 0.5) * 2.8 + dew * 0.55 + chase_edge
        elif "bat" in toss_decision:
            toss_edge += defend_edge + (0.5 - venue_chase) * 1.5
    elif toss_winner and toss_winner == opponent_text:
        if "bowl" in toss_decision:
            toss_edge -= (venue_chase - 0.5) * 2.4 + dew * 0.45
        elif "bat" in toss_decision:
            toss_edge -= defend_edge * 0.5

    pitch_spin = number("pitch_spin_assist")
    pitch_pace = number("pitch_pace_assist")
    bowling_style_edge = ((pitch_spin + pitch_pace) - 1.0) * (number("team_bowling_rating") - number("opponent_bowling_rating")) * 0.006
    venue_average = number("venue_average_score", baseline_total)
    venue_scoring_boost = (venue_average - baseline_total) * 0.035
    wind_drag = -abs(wind) * 0.7 if wind > 0.35 else 0

    selected_edge_score = (
        run_rate_edge * 1.45 + batting_edge + bowling_edge + fielding_edge + form_edge
        + wicket_resource_edge + boundary_edge + toss_edge + bowling_style_edge + venue_scoring_boost + wind_drag
    )
    if not selected_team:
        selected_edge_score *= -1

    raw_match_probability = _logistic_probability(selected_edge_score, 4.8 if format_key in {"ipl", "t20"} else 5.6)

    selected_run_rate = team_phase_rr if selected_team else opponent_phase_rr
    opponent_run_rate = opponent_phase_rr if selected_team else team_phase_rr
    selected_wicket_loss = number("team_wicket_loss_rate") if selected_team else number("opponent_wicket_loss_rate")
    opponent_wicket_loss = number("opponent_wicket_loss_rate") if selected_team else number("team_wicket_loss_rate")
    overs = calibration["overs"]
    innings_overs = 20.0 if format_key in {"ipl", "t20", "unknown"} else 50.0 if format_key == "odi" else 90.0
    projected_team_runs = max(35.0, selected_run_rate * innings_overs * (1 - selected_wicket_loss * 0.18))
    projected_opponent_runs = max(35.0, opponent_run_rate * innings_overs * (1 - opponent_wicket_loss * 0.18))
    projected_team_runs += selected_edge_score * 1.6 + (venue_average - baseline_total) * 0.22
    projected_opponent_runs -= selected_edge_score * 1.1 - (venue_average - baseline_total) * 0.16
    projected_total_runs = max(60.0, projected_team_runs + projected_opponent_runs)

    raw_model_probability = raw_match_probability
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    total_runs_line = _safe_float(payload.get("total_runs_line"), _safe_float(input_stats.get("total_runs_line")))
    team_total_line = _safe_float(payload.get("team_total_runs_line"), _safe_float(input_stats.get("team_total_runs_line")))
    if market_key in {"spread", "run_line"}:
        target = line if line is not None else 0
        margin = projected_team_runs - projected_opponent_runs
        raw_model_probability = _logistic_probability(margin + target, volatility * 0.65)
    elif market_key in {"total_runs", "alt_total_runs", "first_innings_total"}:
        target = total_runs_line if total_runs_line is not None else projected_total_runs
        over_probability = _logistic_probability(projected_total_runs - target, volatility)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"first_6_overs_total", "powerplay_total"}:
        target = total_runs_line if total_runs_line is not None else projected_total_runs * 0.18
        powerplay_projection = selected_run_rate * 6.0
        over_probability = _logistic_probability(powerplay_projection - target, 6.5)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key in {"team_total_runs", "alt_team_total_runs"}:
        target = team_total_line if team_total_line is not None else projected_team_runs
        over_probability = _logistic_probability(projected_team_runs - target, volatility * 0.65)
        raw_model_probability = 1 - over_probability if "under" in selection_text else over_probability
    elif market_key == "first_innings_winner":
        raw_model_probability = _logistic_probability(selected_edge_score + toss_edge * 0.6, 5.0)
    elif market_key in CRICKET_PROP_MARKETS:
        player_runs = number("player_runs_projection")
        player_wickets = number("player_wickets_projection")
        player_sixes = number("player_sixes_projection")
        player_fours = number("player_fours_projection")
        prop_line = line if line is not None else number("line", 0.5)
        balls_faced = number("player_balls_faced_projection")
        overs_projection = number("player_overs_projection")
        if market_key in {"top_batter", "player_runs"}:
            stddev = max(6.0, player_runs * 0.42)
            over_probability = 1 - _normal_cdf(prop_line, mean=player_runs, stddev=stddev)
            raw_model_probability = max(0.04, min(0.88, over_probability if market_key == "player_runs" else 0.16 + player_runs / 155))
        elif market_key in {"top_bowler", "player_wickets"}:
            stddev = max(0.55, player_wickets * 0.75)
            over_probability = 1 - _normal_cdf(prop_line, mean=player_wickets, stddev=stddev)
            raw_model_probability = max(0.04, min(0.82, over_probability if market_key == "player_wickets" else 0.12 + player_wickets / 5.5))
        elif market_key == "player_sixes":
            raw_model_probability = max(0.03, min(0.78, 1 - _normal_cdf(prop_line, mean=player_sixes, stddev=max(0.6, player_sixes * 0.70))))
        elif market_key == "player_fours":
            raw_model_probability = max(0.03, min(0.80, 1 - _normal_cdf(prop_line, mean=player_fours, stddev=max(0.8, player_fours * 0.55))))
        elif market_key == "player_total_boundaries":
            boundaries = player_sixes + player_fours
            raw_model_probability = max(0.03, min(0.80, 1 - _normal_cdf(prop_line, mean=boundaries, stddev=max(1.0, boundaries * 0.52))))
        elif market_key == "player_ducks":
            raw_model_probability = max(0.02, min(0.36, _safe_probability(input_stats.get("player_duck_rate")) or 0.08))
        elif market_key == "player_dismissal_method":
            raw_model_probability = max(0.03, min(0.34, 0.12 + selected_wicket_loss * 0.35))
        elif market_key == "anytime_fifty":
            raw_model_probability = max(0.03, min(0.72, (_safe_probability(input_stats.get("player_fifty_rate")) or 0.20) + max(0, player_runs - 32) * 0.006))
        elif market_key == "anytime_hundred":
            raw_model_probability = max(0.01, min(0.34, (_safe_probability(input_stats.get("player_hundred_rate")) or 0.04) + max(0, player_runs - 55) * 0.003))
        if balls_faced < 8 and market_key in {"top_batter", "player_runs", "player_sixes", "player_fours", "player_total_boundaries", "anytime_fifty", "anytime_hundred"}:
            raw_model_probability = min(raw_model_probability, 0.55)
        if overs_projection < 1 and market_key in {"top_bowler", "player_wickets"}:
            raw_model_probability = min(raw_model_probability, 0.50)

    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.06, min(0.92, calibrated_probability))
    sanity_flags = ["cricket probability cap applied"] if true_probability != calibrated_probability else []

    confidence = calibration["confidence_base"]
    risk_flags: list[str] = []
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4
        risk_flags.append("book count too low")
    if format_key == "unknown":
        confidence -= 5
        risk_flags.append("format calibration unknown")
    if dew > 0.5:
        confidence -= 2
        risk_flags.append("dew volatility")
    if wind > 0.35:
        confidence -= 3
        risk_flags.append("wind volatility")
    if market_key in CRICKET_PROP_MARKETS:
        confidence -= 3
        if number("player_balls_faced_projection") < 10 and market_key not in {"top_bowler", "player_wickets"}:
            confidence -= 12
            risk_flags.append("prop batting-role fragility")
        if number("player_overs_projection") < 1 and market_key in {"top_bowler", "player_wickets"}:
            confidence -= 10
            risk_flags.append("bowler overs fragility")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    if input_stats.get("lineup_confirmed") is False or input_stats.get("batting_order_confirmed") is False:
        confidence -= 6
        risk_flags.append("lineup uncertainty")
    confidence = max(1, min(95, round(confidence, 2)))

    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(
        bankroll=bankroll,
        american_odds=odds_american,
        true_probability=true_probability,
        risk_profile=risk_profile,
        confidence=confidence,
    )
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)

    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "final_probability": true_probability,
        "model_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested,
        "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "cricket sanity cap" if sanity_flags else None,
        "market_anchor_probability": market_anchor,
        "league_calibration_applied": "cricket",
        "format_calibration_applied": format_key,
        "projected_team_runs": round(projected_team_runs, 2),
        "projected_opponent_runs": round(projected_opponent_runs, 2),
        "projected_total_runs": round(projected_total_runs, 2),
        "projected_run_differential": round(projected_team_runs - projected_opponent_runs, 2),
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(CRICKET_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": CRICKET_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in CRICKET_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in CRICKET_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {
            "provider_status": "available" if input_stats.get("provider_status") not in {None, "error"} else input_stats.get("provider_status") or "not_provided",
            "provider_enrichment_present": [field for field in CRICKET_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
        },
        "no_bet_flags": no_bet_flags,
    }


def _cs2_match_format_calibration(raw_format: Any, best_of_maps: Any = None) -> str:
    text = str(raw_format or "").strip().lower().replace("best_of_", "bo")
    maps = int(_safe_float(best_of_maps, 0) or 0)
    if "bo1" in text or maps == 1:
        return "bo1"
    if "bo5" in text or maps == 5:
        return "bo5"
    if "bo3" in text or maps == 3:
        return "bo3"
    return "unknown"


def _estimate_cs2_round_economy_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _cs2_full_inputs_missing(input_stats, payload) + _cs2_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    selected_team = not input_stats.get("opponent") or str(input_stats.get("team") or "").strip().lower() in selection_text
    format_key = _cs2_match_format_calibration(input_stats.get("match_format"), input_stats.get("best_of_maps"))
    event_environment = "lan" if input_stats.get("lan_event") else "online" if input_stats.get("online_event") else "unknown"
    map_calibration = str(input_stats.get("map_name") or "unknown").strip() or "unknown"
    tier_bonus = 1.0 if str(input_stats.get("tournament_tier") or "").strip().lower() in {"s", "tier_s", "major"} else 0.0
    edge_score = (
        (number("team_elo") - number("opponent_elo")) / 38.0
        + (number("opponent_world_rank") - number("team_world_rank")) * 0.18
        + (number("team_recent_win_rate") - number("opponent_recent_win_rate")) * 5.8
        + (number("team_recent_round_win_rate") - number("opponent_recent_round_win_rate")) * 7.0
        + (number("team_ct_round_win_rate") - number("opponent_ct_round_win_rate")) * (2.2 + number("map_ct_bias") * 1.2)
        + (number("team_t_round_win_rate") - number("opponent_t_round_win_rate")) * (2.2 + number("map_t_bias") * 1.2)
        + (number("team_pistol_round_win_rate") - number("opponent_pistol_round_win_rate")) * 2.4
        + (number("team_force_buy_success_rate") - number("opponent_force_buy_success_rate")) * 2.1
        + (number("team_eco_round_win_rate") - number("opponent_eco_round_win_rate")) * 1.7
        + (number("team_anti_eco_success_rate") - number("opponent_anti_eco_success_rate")) * 1.9
        + (number("team_clutch_rate") - number("opponent_clutch_rate")) * 2.0
        + (number("team_entry_success_rate") - number("opponent_entry_success_rate")) * 2.6
        + (number("team_trade_rate") - number("opponent_trade_rate")) * 1.7
        + (number("team_opening_kill_rate") - number("opponent_opening_kill_rate")) * 2.2
        + (number("team_kast") - number("opponent_kast")) * 0.05
        + (number("team_adr") - number("opponent_adr")) * 0.06
        + (number("team_rating") - number("opponent_rating")) * 5.5
        + (number("team_utility_damage") - number("opponent_utility_damage")) * 0.04
        + (number("team_flash_assist_rate") - number("opponent_flash_assist_rate")) * 1.1
        + (number("team_map_win_rate") - number("opponent_map_win_rate")) * 4.2
        + (number("team_map_pick_rate") - number("opponent_map_pick_rate")) * 1.2
        - (number("team_map_ban_rate") - number("opponent_map_ban_rate")) * 1.1
        + (number("map_pool_depth") - number("opponent_map_pool_depth")) * 0.16
        + (number("recent_form") - number("opponent_recent_form")) * 0.04
        + number("roster_stability") * 1.1
        - number("substitute_risk") * 3.0
        - number("injury_or_availability_risk") * 2.8
        - number("travel_fatigue") * 0.9
        + tier_bonus
    )
    if not selected_team:
        edge_score = -edge_score
    volatility = 1.0
    if format_key == "bo1":
        volatility += 0.75
    elif format_key == "bo5":
        volatility -= 0.18
    if event_environment == "online":
        volatility += 0.12
    if input_stats.get("elimination_match"):
        volatility += 0.10
    match_probability = _logistic_probability(edge_score, 6.4 + volatility)
    map_probability = _logistic_probability(edge_score + (number("team_map_win_rate") - number("opponent_map_win_rate")) * 2.5, 5.8 + volatility)
    round_probability = _logistic_probability(edge_score + (number("team_recent_round_win_rate") - number("opponent_recent_round_win_rate")) * 4.0, 5.9 + volatility)
    pistol_probability = _logistic_probability((number("team_pistol_round_win_rate") - number("opponent_pistol_round_win_rate")) * 5.5 + edge_score * 0.25, 4.4 + volatility)
    expected_rounds = 24.0 + max(-3.2, min(3.2, abs(edge_score) * -0.35 + (1 - abs(match_probability - 0.5) * 2) * 2.7))
    expected_team_rounds = expected_rounds * round_probability
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    total_line = _safe_float(payload.get("total_line"), _safe_float(input_stats.get("total_line")))
    raw_model_probability = match_probability
    if market_key in {"match_winner", "moneyline"}:
        raw_model_probability = match_probability
    elif market_key in {"map_winner", "first_map_winner", "second_map_winner", "third_map_winner"}:
        raw_model_probability = map_probability
    elif market_key in {"pistol_round_winner", "first_pistol_round_winner", "second_pistol_round_winner"}:
        raw_model_probability = pistol_probability
    elif market_key in {"map_handicap", "alt_map_handicap"}:
        raw_model_probability = _logistic_probability((match_probability - 0.5) * 8 - (line or 0), 3.2 + volatility)
    elif market_key in {"total_maps", "alt_total_maps"}:
        projected_maps = 2.0 if format_key == "bo3" else 3.1 if format_key == "bo5" else 1.0
        projected_maps += (1 - abs(match_probability - 0.5) * 2) * (0.6 if format_key != "bo1" else 0.0)
        raw_model_probability = _logistic_probability(projected_maps - (total_line if total_line is not None else projected_maps), 0.55 + volatility * 0.12)
    elif market_key in {"round_handicap", "race_to_rounds"}:
        raw_model_probability = _logistic_probability((expected_team_rounds - expected_rounds / 2) - (line or 0), 3.8 + volatility)
    elif market_key in {"total_rounds", "alt_total_rounds"}:
        raw_model_probability = _logistic_probability(expected_rounds - (total_line if total_line is not None else expected_rounds), 3.4 + volatility)
    elif market_key == "team_total_rounds":
        raw_model_probability = _logistic_probability(expected_team_rounds - (total_line if total_line is not None else expected_team_rounds), 2.8 + volatility)
    elif market_key == "correct_score":
        raw_model_probability = max(0.04, min(0.42, match_probability * (0.65 if format_key == "bo3" else 0.46 if format_key == "bo5" else 1.0)))
    elif market_key in CS2_PROP_MARKETS:
        prop_map = {
            "player_kills": "player_kills_projection", "player_headshots": "player_headshots_projection",
            "player_assists": "player_assists_projection", "player_deaths": "player_deaths_projection",
            "player_kda": "player_kda_projection", "player_adr": "player_adr_projection",
            "player_clutches": "player_clutches_projection", "player_opening_kills": "player_opening_kills_projection",
            "player_flash_assists": "player_flash_assists_projection",
        }
        projection = number(prop_map[market_key])
        prop_line = number("player_prop_line", line or projection)
        raw_model_probability = _logistic_probability(projection - prop_line, max(0.9, abs(projection) * 0.18))
    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.04, min(0.88, calibrated_probability))
    sanity_flags = ["cs2 probability cap applied"] if true_probability != calibrated_probability else []
    confidence = 74.0
    risk_flags: list[str] = []
    if format_key == "bo1":
        confidence -= 5; risk_flags.append("BO1 volatility")
    if event_environment == "online":
        confidence -= 3; risk_flags.append("online server variance")
    if number("substitute_risk") >= 0.10 or number("injury_or_availability_risk") >= 0.10:
        confidence -= 7; risk_flags.append("roster availability risk")
    if number("roster_stability") < 0.75:
        confidence -= 5; risk_flags.append("roster instability")
    if market_key in CS2_PROP_MARKETS:
        confidence -= 4; risk_flags.append("player prop fragility")
    if market_key in {"pistol_round_winner", "first_pistol_round_winner", "second_pistol_round_winner", "correct_score"}:
        confidence -= 5; risk_flags.append("volatile CS2 market")
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4; risk_flags.append("book count too low")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))
    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(bankroll=bankroll, american_odds=odds_american, true_probability=true_probability, risk_profile=risk_profile, confidence=confidence)
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)
    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "final_probability": true_probability,
        "model_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": "high" if risk_flags else "moderate",
        "suggested_stake": suggested,
        "raw_model_probability": raw_model_probability,
        "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags),
        "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "cs2 sanity cap" if sanity_flags else None,
        "market_anchor_probability": market_anchor,
        "league_calibration_applied": "cs2",
        "match_format_calibration_applied": format_key,
        "event_environment_calibration_applied": event_environment,
        "map_calibration_applied": map_calibration,
        "cs2_team_edge_score": round(edge_score, 2),
        "cs2_match_probability": match_probability,
        "cs2_map_probability": map_probability,
        "cs2_round_probability": round_probability,
        "cs2_projected_total_rounds": round(expected_rounds, 2),
        "cs2_projected_team_rounds": round(expected_team_rounds, 2),
        "risk_flags": risk_flags,
        "input_coverage": {
            "required_core_present": list(CS2_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": CS2_REQUIRED_MARKET_INPUTS.get(market_key, []),
            "optional_enrichment_present": [field for field in CS2_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
            "optional_enrichment_missing": [field for field in CS2_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
        },
        "provider_enrichment": {
            "provider_status": input_stats.get("provider_status") or "not_provided",
            "provider_enrichment_present": [field for field in CS2_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None],
        },
        "no_bet_flags": no_bet_flags,
    }


def _estimate_valorant_agent_composition_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _valorant_full_inputs_missing(input_stats, payload) + _valorant_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    selected_team = not input_stats.get("opponent") or str(input_stats.get("team") or "").strip().lower() in selection_text
    format_key = _cs2_match_format_calibration(input_stats.get("match_format"), input_stats.get("best_of_maps"))
    event_environment = "lan" if input_stats.get("lan_event") else "online" if input_stats.get("online_event") else "unknown"
    map_calibration = str(input_stats.get("map_name") or "unknown").strip() or "unknown"
    agent_composition_applied = all(input_stats.get(field) is not None for field in ("team_agent_comp_rating", "opponent_agent_comp_rating", "duelist_rating", "initiator_rating", "controller_rating", "sentinel_rating"))
    tier_bonus = 1.0 if str(input_stats.get("tournament_tier") or "").strip().lower() in {"s", "tier_s", "major", "vct"} else 0.0
    role_balance = (number("duelist_rating") + number("initiator_rating") + number("controller_rating") + number("sentinel_rating")) / 4.0
    edge_score = (
        (number("team_elo") - number("opponent_elo")) / 38.0
        + (number("opponent_world_rank") - number("team_world_rank")) * 0.17
        + (number("team_recent_win_rate") - number("opponent_recent_win_rate")) * 5.6
        + (number("team_recent_round_win_rate") - number("opponent_recent_round_win_rate")) * 6.8
        + (number("team_attack_round_win_rate") - number("opponent_attack_round_win_rate")) * (2.2 + number("map_attack_bias") * 1.0)
        + (number("team_defense_round_win_rate") - number("opponent_defense_round_win_rate")) * (2.2 + number("map_defense_bias") * 1.0)
        + (number("team_pistol_round_win_rate") - number("opponent_pistol_round_win_rate")) * 2.1
        + (number("team_bonus_round_conversion_rate") - number("opponent_bonus_round_conversion_rate")) * 2.0
        + (number("team_eco_round_win_rate") - number("opponent_eco_round_win_rate")) * 1.4
        + (number("team_anti_eco_success_rate") - number("opponent_anti_eco_success_rate")) * 1.6
        + (number("team_clutch_rate") - number("opponent_clutch_rate")) * 1.8
        + (number("team_first_blood_rate") - number("opponent_first_blood_rate")) * 2.4
        + (number("team_trade_rate") - number("opponent_trade_rate")) * 1.6
        + (number("team_post_plant_win_rate") - number("opponent_post_plant_win_rate")) * 1.8
        + (number("team_retaking_success_rate") - number("opponent_retaking_success_rate")) * 1.6
        + (number("team_acs") - number("opponent_acs")) * 0.025
        + (number("team_adr") - number("opponent_adr")) * 0.04
        + (number("team_kast") - number("opponent_kast")) * 0.045
        + (number("team_rating") - number("opponent_rating")) * 5.2
        + (number("team_utility_value") - number("opponent_utility_value")) * 0.035
        + (number("team_agent_comp_rating") - number("opponent_agent_comp_rating")) * 0.055
        + (role_balance - 80) * 0.035
        + (number("team_map_win_rate") - number("opponent_map_win_rate")) * 4.0
        + (number("team_map_pick_rate") - number("opponent_map_pick_rate")) * 1.0
        - (number("team_map_ban_rate") - number("opponent_map_ban_rate")) * 0.9
        + (number("map_pool_depth") - number("opponent_map_pool_depth")) * 0.15
        + (number("recent_form") - number("opponent_recent_form")) * 0.04
        + number("roster_stability") * 1.0
        - number("substitute_risk") * 3.0
        - number("injury_or_availability_risk") * 2.7
        - number("travel_fatigue") * 0.8
        + tier_bonus
    )
    if not selected_team:
        edge_score = -edge_score
    volatility = 1.0 + (0.72 if format_key == "bo1" else -0.15 if format_key == "bo5" else 0)
    if event_environment == "online":
        volatility += 0.12
    if input_stats.get("elimination_match"):
        volatility += 0.10
    match_probability = _logistic_probability(edge_score, 6.5 + volatility)
    map_probability = _logistic_probability(edge_score + (number("team_map_win_rate") - number("opponent_map_win_rate")) * 2.3, 5.9 + volatility)
    round_probability = _logistic_probability(edge_score + (number("team_recent_round_win_rate") - number("opponent_recent_round_win_rate")) * 3.8, 6.0 + volatility)
    pistol_probability = _logistic_probability((number("team_pistol_round_win_rate") - number("opponent_pistol_round_win_rate")) * 5.2 + edge_score * 0.22, 4.5 + volatility)
    expected_rounds = 24.0 + max(-3.0, min(3.0, abs(edge_score) * -0.32 + (1 - abs(match_probability - 0.5) * 2) * 2.6))
    expected_team_rounds = expected_rounds * round_probability
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    total_line = _safe_float(payload.get("total_line"), _safe_float(input_stats.get("total_line")))
    raw_model_probability = match_probability
    if market_key in {"map_winner", "first_map_winner", "second_map_winner", "third_map_winner"}:
        raw_model_probability = map_probability
    elif market_key in {"pistol_round_winner", "first_pistol_round_winner", "second_pistol_round_winner"}:
        raw_model_probability = pistol_probability
    elif market_key in {"map_handicap", "alt_map_handicap"}:
        raw_model_probability = _logistic_probability((match_probability - 0.5) * 8 - (line or 0), 3.2 + volatility)
    elif market_key in {"total_maps", "alt_total_maps"}:
        projected_maps = 2.0 if format_key == "bo3" else 3.1 if format_key == "bo5" else 1.0
        projected_maps += (1 - abs(match_probability - 0.5) * 2) * (0.6 if format_key != "bo1" else 0.0)
        raw_model_probability = _logistic_probability(projected_maps - (total_line if total_line is not None else projected_maps), 0.55 + volatility * 0.12)
    elif market_key in {"round_handicap", "race_to_rounds"}:
        raw_model_probability = _logistic_probability((expected_team_rounds - expected_rounds / 2) - (line or 0), 3.8 + volatility)
    elif market_key in {"total_rounds", "alt_total_rounds"}:
        raw_model_probability = _logistic_probability(expected_rounds - (total_line if total_line is not None else expected_rounds), 3.4 + volatility)
    elif market_key == "team_total_rounds":
        raw_model_probability = _logistic_probability(expected_team_rounds - (total_line if total_line is not None else expected_team_rounds), 2.8 + volatility)
    elif market_key == "correct_score":
        raw_model_probability = max(0.04, min(0.42, match_probability * (0.65 if format_key == "bo3" else 0.46 if format_key == "bo5" else 1.0)))
    elif market_key in VALORANT_PROP_MARKETS:
        prop_map = {
            "player_kills": "player_kills_projection", "player_assists": "player_assists_projection",
            "player_deaths": "player_deaths_projection", "player_kda": "player_kda_projection",
            "player_acs": "player_acs_projection", "player_adr": "player_adr_projection",
            "player_first_bloods": "player_first_bloods_projection", "player_headshots": "player_headshots_projection",
            "player_clutches": "player_clutches_projection",
        }
        projection = number(prop_map[market_key])
        prop_line = number("player_prop_line", line or projection)
        raw_model_probability = _logistic_probability(projection - prop_line, max(0.9, abs(projection) * 0.18))
    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.04, min(0.88, calibrated_probability))
    sanity_flags = ["valorant probability cap applied"] if true_probability != calibrated_probability else []
    confidence = 74.0
    risk_flags: list[str] = []
    if format_key == "bo1":
        confidence -= 5; risk_flags.append("BO1 volatility")
    if event_environment == "online":
        confidence -= 3; risk_flags.append("online server variance")
    if not agent_composition_applied:
        confidence -= 5; risk_flags.append("agent composition uncertainty")
    if number("substitute_risk") >= 0.10 or number("injury_or_availability_risk") >= 0.10:
        confidence -= 7; risk_flags.append("roster availability risk")
    if number("roster_stability") < 0.75:
        confidence -= 5; risk_flags.append("roster instability")
    if market_key in VALORANT_PROP_MARKETS:
        confidence -= 4; risk_flags.append("player prop fragility")
    if market_key in {"pistol_round_winner", "first_pistol_round_winner", "second_pistol_round_winner", "correct_score"}:
        confidence -= 5; risk_flags.append("volatile Valorant market")
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4; risk_flags.append("book count too low")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))
    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(bankroll=bankroll, american_odds=odds_american, true_probability=true_probability, risk_profile=risk_profile, confidence=confidence)
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)
    return {
        "model_status": "active", "estimated_true_probability": true_probability, "true_probability": true_probability,
        "final_probability": true_probability, "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate", "suggested_stake": suggested,
        "raw_model_probability": raw_model_probability, "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags), "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "valorant sanity cap" if sanity_flags else None, "market_anchor_probability": market_anchor,
        "league_calibration_applied": "valorant", "match_format_calibration_applied": format_key,
        "event_environment_calibration_applied": event_environment, "map_calibration_applied": map_calibration,
        "agent_composition_calibration_applied": agent_composition_applied,
        "valorant_team_edge_score": round(edge_score, 2), "valorant_match_probability": match_probability,
        "valorant_map_probability": map_probability, "valorant_round_probability": round_probability,
        "valorant_projected_total_rounds": round(expected_rounds, 2), "valorant_projected_team_rounds": round(expected_team_rounds, 2),
        "risk_flags": risk_flags,
        "input_coverage": {"required_core_present": list(VALORANT_REQUIRED_CORE_INPUTS), "required_market_specific_present": VALORANT_REQUIRED_MARKET_INPUTS.get(market_key, []), "optional_enrichment_present": [f for f in VALORANT_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None], "optional_enrichment_missing": [f for f in VALORANT_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is None]},
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [f for f in VALORANT_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _lol_region_calibration(raw_region: Any, raw_league: Any = None) -> str:
    text = str(raw_region or raw_league or "").strip().lower()
    if text in {"lcs", "lec", "lck", "lpl"}:
        return text
    if text in {"worlds", "msi", "international", "intl"}:
        return "international"
    return "unknown"


def _estimate_lol_draft_objective_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _lol_full_inputs_missing(input_stats, payload) + _lol_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    selected_team = not input_stats.get("opponent") or str(input_stats.get("team") or "").strip().lower() in selection_text
    format_key = _cs2_match_format_calibration(input_stats.get("match_format"), input_stats.get("best_of_maps"))
    region_key = _lol_region_calibration(input_stats.get("region"), input_stats.get("league"))
    patch_calibration = str(input_stats.get("patch_version") or "unknown").strip() or "unknown"
    draft_applied = all(input_stats.get(field) is not None for field in ("team_draft_rating", "opponent_draft_rating", "team_champion_pool_depth", "opponent_champion_pool_depth", "team_meta_fit_rating", "opponent_meta_fit_rating"))
    event_environment = "lan" if input_stats.get("lan_event") else "online" if input_stats.get("online_event") else "unknown"
    lane_edge = (
        (number("top_lane_rating") - number("opponent_top_lane_rating"))
        + (number("jungle_rating") - number("opponent_jungle_rating")) * 1.15
        + (number("mid_lane_rating") - number("opponent_mid_lane_rating")) * 1.2
        + (number("adc_rating") - number("opponent_adc_rating"))
        + (number("support_rating") - number("opponent_support_rating")) * 0.9
    ) / 5.0
    objective_edge = (
        (number("team_objective_control_rating") - number("opponent_objective_control_rating")) * 0.08
        + (number("team_dragon_control_rate") - number("opponent_dragon_control_rate")) * 4.0
        + (number("team_baron_control_rate") - number("opponent_baron_control_rate")) * 3.4
        + (number("team_first_dragon_rate") - number("opponent_first_dragon_rate")) * 1.8
        + (number("team_first_herald_rate") - number("opponent_first_herald_rate")) * 1.4
    )
    gold_edge = (
        (number("team_gold_diff_10") - number("opponent_gold_diff_10")) / 180.0
        + (number("team_gold_diff_15") - number("opponent_gold_diff_15")) / 260.0
        + (number("team_xp_diff_10") - number("opponent_xp_diff_10")) / 230.0
        + (number("team_xp_diff_15") - number("opponent_xp_diff_15")) / 320.0
    )
    edge_score = (
        (number("team_elo") - number("opponent_elo")) / 38.0
        + (number("opponent_world_rank") - number("team_world_rank")) * 0.18
        + (number("team_recent_win_rate") - number("opponent_recent_win_rate")) * 5.4
        + (number("team_game_win_rate") - number("opponent_game_win_rate")) * 6.0
        + (number("team_blue_side_win_rate") - number("opponent_blue_side_win_rate")) * 1.4
        + (number("team_red_side_win_rate") - number("opponent_red_side_win_rate")) * 1.2
        + (number("team_early_game_rating") - number("opponent_early_game_rating")) * 0.055
        + (number("team_mid_game_rating") - number("opponent_mid_game_rating")) * 0.06
        + (number("team_late_game_rating") - number("opponent_late_game_rating")) * 0.05
        + gold_edge
        + objective_edge
        + (number("team_first_blood_rate") - number("opponent_first_blood_rate")) * 1.8
        + (number("team_first_tower_rate") - number("opponent_first_tower_rate")) * 1.7
        + (number("team_vision_score_rating") - number("opponent_vision_score_rating")) * 0.035
        + (number("team_kill_rate") - number("opponent_kill_rate")) * 0.28
        - (number("team_death_rate") - number("opponent_death_rate")) * 0.24
        + (number("team_kda") - number("opponent_kda")) * 0.42
        + (number("team_damage_per_minute") - number("opponent_damage_per_minute")) / 90.0
        + (number("team_gold_per_minute") - number("opponent_gold_per_minute")) / 55.0
        + (number("team_draft_rating") - number("opponent_draft_rating")) * 0.07
        + (number("team_champion_pool_depth") - number("opponent_champion_pool_depth")) * 0.12
        + (number("team_meta_fit_rating") - number("opponent_meta_fit_rating")) * 0.055
        + lane_edge * 0.08
        + (number("recent_form") - number("opponent_recent_form")) * 0.04
        + number("roster_stability") * 0.9
        - number("substitute_risk") * 3.0
        - number("player_availability_risk") * 2.6
        - number("travel_fatigue") * 0.7
    )
    if not selected_team:
        edge_score = -edge_score
    volatility = 1.0 + (0.65 if format_key == "bo1" else -0.15 if format_key == "bo5" else 0)
    if event_environment == "online":
        volatility += 0.10
    if input_stats.get("elimination_match"):
        volatility += 0.08
    match_probability = _logistic_probability(edge_score, 6.4 + volatility)
    game_probability = _logistic_probability(edge_score + gold_edge * 0.45 + objective_edge * 0.5, 5.8 + volatility)
    objective_probability = _logistic_probability(objective_edge + edge_score * 0.2, 3.8 + volatility)
    first_blood_probability = _logistic_probability((number("team_first_blood_rate") - number("opponent_first_blood_rate")) * 5.0 + edge_score * 0.2, 4.0 + volatility)
    expected_total_kills = max(14.0, number("team_kill_rate") + number("opponent_kill_rate") + 4.0 + volatility * 1.2)
    expected_team_kills = expected_total_kills * _logistic_probability(edge_score + (number("team_kill_rate") - number("opponent_kill_rate")) * 0.35, 6.2 + volatility)
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    total_line = _safe_float(payload.get("total_line"), _safe_float(input_stats.get("total_line")))
    raw_model_probability = match_probability
    if market_key in {"map_winner", "game_winner", "first_game_winner", "second_game_winner", "third_game_winner"}:
        raw_model_probability = game_probability
    elif market_key in {"first_blood"}:
        raw_model_probability = first_blood_probability
    elif market_key in {"first_tower"}:
        raw_model_probability = _logistic_probability((number("team_first_tower_rate") - number("opponent_first_tower_rate")) * 4.8 + edge_score * 0.18, 4.0 + volatility)
    elif market_key in {"first_dragon", "first_herald", "first_baron", "first_inhibitor"}:
        raw_model_probability = objective_probability
    elif market_key in {"map_handicap", "alt_map_handicap"}:
        raw_model_probability = _logistic_probability((match_probability - 0.5) * 8 - (line or 0), 3.1 + volatility)
    elif market_key in {"kill_handicap"}:
        raw_model_probability = _logistic_probability((expected_team_kills - expected_total_kills / 2) - (line or 0), 3.4 + volatility)
    elif market_key in {"total_maps", "alt_total_maps"}:
        projected_maps = 2.0 if format_key == "bo3" else 3.2 if format_key == "bo5" else 1.0
        projected_maps += (1 - abs(match_probability - 0.5) * 2) * (0.6 if format_key != "bo1" else 0.0)
        raw_model_probability = _logistic_probability(projected_maps - (total_line if total_line is not None else projected_maps), 0.55 + volatility * 0.12)
    elif market_key in {"total_kills", "alt_total_kills"}:
        raw_model_probability = _logistic_probability(expected_total_kills - (total_line if total_line is not None else expected_total_kills), 4.2 + volatility)
    elif market_key == "team_total_kills":
        raw_model_probability = _logistic_probability(expected_team_kills - (total_line if total_line is not None else expected_team_kills), 3.2 + volatility)
    elif market_key == "total_dragons":
        raw_model_probability = _logistic_probability(4.8 + objective_edge * 0.18 - (total_line if total_line is not None else 4.5), 1.15 + volatility * 0.15)
    elif market_key == "total_barons":
        raw_model_probability = _logistic_probability(1.45 + objective_edge * 0.08 - (total_line if total_line is not None else 1.5), 0.75 + volatility * 0.12)
    elif market_key == "correct_score":
        raw_model_probability = max(0.04, min(0.42, match_probability * (0.65 if format_key == "bo3" else 0.46 if format_key == "bo5" else 1.0)))
    elif market_key in LOL_PROP_MARKETS:
        prop_map = {
            "player_kills": "player_kills_projection", "player_assists": "player_assists_projection",
            "player_deaths": "player_deaths_projection", "player_kda": "player_kda_projection",
            "player_kill_participation": "player_kill_participation_projection",
        }
        projection = number(prop_map[market_key])
        prop_line = number("player_prop_line", line or projection)
        raw_model_probability = _logistic_probability(projection - prop_line, max(0.9, abs(projection) * 0.20))
    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.04, min(0.88, calibrated_probability))
    sanity_flags = ["league of legends probability cap applied"] if true_probability != calibrated_probability else []
    confidence = 74.0
    risk_flags: list[str] = []
    if format_key == "bo1":
        confidence -= 5; risk_flags.append("BO1 volatility")
    if event_environment == "online":
        confidence -= 3; risk_flags.append("online server variance")
    if not draft_applied:
        confidence -= 5; risk_flags.append("draft uncertainty")
    if number("substitute_risk") >= 0.10 or number("player_availability_risk") >= 0.10:
        confidence -= 7; risk_flags.append("player availability risk")
    if number("roster_stability") < 0.75:
        confidence -= 5; risk_flags.append("roster instability")
    if market_key in LOL_PROP_MARKETS:
        confidence -= 4; risk_flags.append("player prop fragility")
    if market_key in {"first_blood", "correct_score"}:
        confidence -= 5; risk_flags.append("volatile League market")
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4; risk_flags.append("book count too low")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))
    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(bankroll=bankroll, american_odds=odds_american, true_probability=true_probability, risk_profile=risk_profile, confidence=confidence)
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)
    return {
        "model_status": "active", "estimated_true_probability": true_probability, "true_probability": true_probability,
        "final_probability": true_probability, "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate", "suggested_stake": suggested,
        "raw_model_probability": raw_model_probability, "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags), "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "league of legends sanity cap" if sanity_flags else None, "market_anchor_probability": market_anchor,
        "league_calibration_applied": "league_of_legends", "match_format_calibration_applied": format_key,
        "region_calibration_applied": region_key, "patch_calibration_applied": patch_calibration,
        "draft_calibration_applied": draft_applied,
        "lol_team_edge_score": round(edge_score, 2), "lol_match_probability": match_probability,
        "lol_game_probability": game_probability, "lol_objective_probability": objective_probability,
        "lol_projected_total_kills": round(expected_total_kills, 2), "lol_projected_team_kills": round(expected_team_kills, 2),
        "risk_flags": risk_flags,
        "input_coverage": {"required_core_present": list(LOL_REQUIRED_CORE_INPUTS), "required_market_specific_present": LOL_REQUIRED_MARKET_INPUTS.get(market_key, []), "optional_enrichment_present": [f for f in LOL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None], "optional_enrichment_missing": [f for f in LOL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is None]},
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [f for f in LOL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _dota2_region_calibration(raw_region: Any, raw_league: Any = None) -> str:
    text = str(raw_region or raw_league or "").strip().lower().replace(" ", "_")
    mapping = {
        "weu": "western_europe", "western_europe": "western_europe",
        "eeu": "eastern_europe", "eastern_europe": "eastern_europe",
        "cn": "china", "china": "china",
        "sea": "southeast_asia", "southeast_asia": "southeast_asia",
        "na": "north_america", "north_america": "north_america",
        "sa": "south_america", "south_america": "south_america",
        "the_international": "international", "ti": "international", "dpc": "international",
    }
    return mapping.get(text, "unknown")


def _estimate_dota2_draft_lane_roshan_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _dota2_full_inputs_missing(input_stats, payload) + _dota2_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    selected_team = not input_stats.get("opponent") or str(input_stats.get("team") or "").strip().lower() in selection_text
    format_key = _cs2_match_format_calibration(input_stats.get("match_format"), input_stats.get("best_of_maps"))
    region_key = _dota2_region_calibration(input_stats.get("region"), input_stats.get("league"))
    patch_calibration = str(input_stats.get("patch_version") or "unknown").strip() or "unknown"
    draft_applied = all(input_stats.get(field) is not None for field in ("team_draft_rating", "opponent_draft_rating", "team_hero_pool_depth", "opponent_hero_pool_depth", "team_meta_fit_rating", "opponent_meta_fit_rating"))
    event_environment = "lan" if input_stats.get("lan_event") else "online" if input_stats.get("online_event") else "unknown"
    role_edge = (
        (number("carry_rating") - number("opponent_carry_rating")) * 1.1
        + (number("mid_rating") - number("opponent_mid_rating")) * 1.2
        + (number("offlane_rating") - number("opponent_offlane_rating"))
        + (number("soft_support_rating") - number("opponent_soft_support_rating")) * 0.9
        + (number("hard_support_rating") - number("opponent_hard_support_rating")) * 0.85
    ) / 5.0
    economy_edge = (
        (number("team_gold_diff_10") - number("opponent_gold_diff_10")) / 180.0
        + (number("team_gold_diff_20") - number("opponent_gold_diff_20")) / 420.0
        + (number("team_xp_diff_10") - number("opponent_xp_diff_10")) / 220.0
        + (number("team_xp_diff_20") - number("opponent_xp_diff_20")) / 480.0
        + (number("team_net_worth_rating") - number("opponent_net_worth_rating")) * 0.06
    )
    roshan_edge = (number("team_roshan_control_rate") - number("opponent_roshan_control_rate")) * 4.2
    objective_edge = (
        roshan_edge
        + (number("team_tower_pressure_rating") - number("opponent_tower_pressure_rating")) * 0.06
        + (number("team_objective_control_rating") - number("opponent_objective_control_rating")) * 0.07
        + (number("team_vision_control_rating") - number("opponent_vision_control_rating")) * 0.035
    )
    edge_score = (
        (number("team_elo") - number("opponent_elo")) / 38.0
        + (number("opponent_world_rank") - number("team_world_rank")) * 0.18
        + (number("team_recent_win_rate") - number("opponent_recent_win_rate")) * 5.2
        + (number("team_game_win_rate") - number("opponent_game_win_rate")) * 5.8
        + (number("team_radiant_win_rate") - number("opponent_radiant_win_rate")) * 1.2
        + (number("team_dire_win_rate") - number("opponent_dire_win_rate")) * 1.1
        + (number("team_laning_rating") - number("opponent_laning_rating")) * 0.07
        + (number("team_mid_game_rating") - number("opponent_mid_game_rating")) * 0.06
        + (number("team_late_game_rating") - number("opponent_late_game_rating")) * 0.055
        + economy_edge + objective_edge
        + (number("team_first_blood_rate") - number("opponent_first_blood_rate")) * 1.6
        + (number("team_first_tower_rate") - number("opponent_first_tower_rate")) * 1.5
        + (number("team_kill_rate") - number("opponent_kill_rate")) * 0.15
        - (number("team_death_rate") - number("opponent_death_rate")) * 0.14
        + (number("team_kda") - number("opponent_kda")) * 0.35
        + (number("team_gpm") - number("opponent_gpm")) / 65.0
        + (number("team_xpm") - number("opponent_xpm")) / 85.0
        + (number("team_draft_rating") - number("opponent_draft_rating")) * 0.07
        + (number("team_hero_pool_depth") - number("opponent_hero_pool_depth")) * 0.12
        + (number("team_meta_fit_rating") - number("opponent_meta_fit_rating")) * 0.055
        + role_edge * 0.08
        + (number("recent_form") - number("opponent_recent_form")) * 0.04
        + number("roster_stability") * 0.9
        - number("substitute_risk") * 3.0
        - number("player_availability_risk") * 2.6
        - number("travel_fatigue") * 0.7
    )
    if not selected_team:
        edge_score = -edge_score
    volatility = 1.0 + (0.65 if format_key == "bo1" else -0.15 if format_key == "bo5" else 0)
    if event_environment == "online":
        volatility += 0.10
    if input_stats.get("elimination_match"):
        volatility += 0.08
    match_probability = _logistic_probability(edge_score, 6.4 + volatility)
    game_probability = _logistic_probability(edge_score + economy_edge * 0.4 + objective_edge * 0.5, 5.8 + volatility)
    roshan_probability = _logistic_probability(roshan_edge + edge_score * 0.2, 3.6 + volatility)
    first_blood_probability = _logistic_probability((number("team_first_blood_rate") - number("opponent_first_blood_rate")) * 5.0 + edge_score * 0.2, 4.0 + volatility)
    expected_total_kills = max(28.0, number("team_kill_rate") + number("opponent_kill_rate") + 6.0 + volatility * 2.0)
    expected_team_kills = expected_total_kills * _logistic_probability(edge_score + (number("team_kill_rate") - number("opponent_kill_rate")) * 0.18, 6.2 + volatility)
    expected_duration = 35.0 + max(-6.0, min(7.0, (1 - abs(match_probability - 0.5) * 2) * 5.5 + volatility * 1.2 - abs(edge_score) * 0.25))
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    total_line = _safe_float(payload.get("total_line"), _safe_float(input_stats.get("total_line")))
    raw_model_probability = match_probability
    if market_key in {"map_winner", "game_winner", "first_game_winner", "second_game_winner", "third_game_winner"}:
        raw_model_probability = game_probability
    elif market_key == "first_blood":
        raw_model_probability = first_blood_probability
    elif market_key == "first_tower":
        raw_model_probability = _logistic_probability((number("team_first_tower_rate") - number("opponent_first_tower_rate")) * 4.8 + edge_score * 0.18, 4.0 + volatility)
    elif market_key == "first_roshan":
        raw_model_probability = roshan_probability
    elif market_key in {"map_handicap", "alt_map_handicap"}:
        raw_model_probability = _logistic_probability((match_probability - 0.5) * 8 - (line or 0), 3.1 + volatility)
    elif market_key == "kill_handicap":
        raw_model_probability = _logistic_probability((expected_team_kills - expected_total_kills / 2) - (line or 0), 4.4 + volatility)
    elif market_key in {"total_maps", "alt_total_maps"}:
        projected_maps = 2.0 if format_key == "bo3" else 3.2 if format_key == "bo5" else 1.0
        projected_maps += (1 - abs(match_probability - 0.5) * 2) * (0.6 if format_key != "bo1" else 0.0)
        raw_model_probability = _logistic_probability(projected_maps - (total_line if total_line is not None else projected_maps), 0.55 + volatility * 0.12)
    elif market_key in {"total_kills", "alt_total_kills"}:
        raw_model_probability = _logistic_probability(expected_total_kills - (total_line if total_line is not None else expected_total_kills), 6.2 + volatility)
    elif market_key == "team_total_kills":
        raw_model_probability = _logistic_probability(expected_team_kills - (total_line if total_line is not None else expected_team_kills), 4.8 + volatility)
    elif market_key == "total_roshans":
        raw_model_probability = _logistic_probability(2.1 + roshan_edge * 0.10 - (total_line if total_line is not None else 2.0), 0.85 + volatility * 0.12)
    elif market_key == "total_towers":
        raw_model_probability = _logistic_probability(13.5 + objective_edge * 0.22 - (total_line if total_line is not None else 13.5), 2.2 + volatility * 0.2)
    elif market_key == "game_duration":
        raw_model_probability = _logistic_probability(expected_duration - (total_line if total_line is not None else expected_duration), 4.2 + volatility)
    elif market_key == "correct_score":
        raw_model_probability = max(0.04, min(0.42, match_probability * (0.65 if format_key == "bo3" else 0.46 if format_key == "bo5" else 1.0)))
    elif market_key in DOTA2_PROP_MARKETS:
        prop_map = {
            "player_kills": "player_kills_projection", "player_assists": "player_assists_projection",
            "player_deaths": "player_deaths_projection", "player_kda": "player_kda_projection",
            "player_last_hits": "player_last_hits_projection", "player_gpm": "player_gpm_projection",
            "player_xpm": "player_xpm_projection", "player_net_worth": "player_net_worth_projection",
        }
        projection = number(prop_map[market_key])
        prop_line = number("player_prop_line", line or projection)
        raw_model_probability = _logistic_probability(projection - prop_line, max(0.9, abs(projection) * 0.18))
    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.04, min(0.88, calibrated_probability))
    sanity_flags = ["dota2 probability cap applied"] if true_probability != calibrated_probability else []
    confidence = 74.0
    risk_flags: list[str] = []
    if format_key == "bo1":
        confidence -= 5; risk_flags.append("BO1 volatility")
    if event_environment == "online":
        confidence -= 3; risk_flags.append("online server variance")
    if not draft_applied:
        confidence -= 5; risk_flags.append("draft uncertainty")
    if number("substitute_risk") >= 0.10 or number("player_availability_risk") >= 0.10:
        confidence -= 7; risk_flags.append("player availability risk")
    if number("roster_stability") < 0.75:
        confidence -= 5; risk_flags.append("roster instability")
    if market_key in DOTA2_PROP_MARKETS:
        confidence -= 4; risk_flags.append("player prop fragility")
    if market_key in {"first_blood", "correct_score", "first_roshan"}:
        confidence -= 5; risk_flags.append("volatile Dota 2 market")
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4; risk_flags.append("book count too low")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))
    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(bankroll=bankroll, american_odds=odds_american, true_probability=true_probability, risk_profile=risk_profile, confidence=confidence)
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)
    return {
        "model_status": "active", "estimated_true_probability": true_probability, "true_probability": true_probability,
        "final_probability": true_probability, "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate", "suggested_stake": suggested,
        "raw_model_probability": raw_model_probability, "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags), "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "dota2 sanity cap" if sanity_flags else None, "market_anchor_probability": market_anchor,
        "league_calibration_applied": "dota2", "match_format_calibration_applied": format_key,
        "region_calibration_applied": region_key, "patch_calibration_applied": patch_calibration,
        "draft_calibration_applied": draft_applied,
        "dota2_team_edge_score": round(edge_score, 2), "dota2_match_probability": match_probability,
        "dota2_game_probability": game_probability, "dota2_roshan_probability": roshan_probability,
        "dota2_projected_total_kills": round(expected_total_kills, 2), "dota2_projected_team_kills": round(expected_team_kills, 2),
        "dota2_projected_game_duration": round(expected_duration, 2),
        "risk_flags": risk_flags,
        "input_coverage": {"required_core_present": list(DOTA2_REQUIRED_CORE_INPUTS), "required_market_specific_present": DOTA2_REQUIRED_MARKET_INPUTS.get(market_key, []), "optional_enrichment_present": [f for f in DOTA2_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None], "optional_enrichment_missing": [f for f in DOTA2_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is None]},
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [f for f in DOTA2_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _cod_mode_calibration(raw_mode: Any) -> str:
    text = str(raw_mode or "").strip().lower().replace(" ", "_").replace("&", "and")
    if text in {"hardpoint", "hp"}:
        return "hardpoint"
    if text in {"search_and_destroy", "search_destroy", "snd", "s_and_d"}:
        return "search_and_destroy"
    if text in {"control", "ctrl"}:
        return "control"
    if text in {"mixed", "rotation", "series"}:
        return "mixed"
    return "unknown"


def _estimate_cod_map_mode_rotation_model(
    *,
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _cod_full_inputs_missing(input_stats, payload) + _cod_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    selected_team = not input_stats.get("opponent") or str(input_stats.get("team") or "").strip().lower() in selection_text
    format_key = _cs2_match_format_calibration(input_stats.get("match_format"), input_stats.get("best_of_maps"))
    mode_key = _cod_mode_calibration(input_stats.get("game_mode"))
    map_key = str(input_stats.get("map_name") or "unknown").strip() or "unknown"
    environment = "lan" if input_stats.get("lan_event") else "online" if input_stats.get("online_event") else "unknown"
    respawn_edge = (
        (number("team_respawn_rating") - number("opponent_respawn_rating")) * 0.09
        + (number("team_hardpoint_win_rate") - number("opponent_hardpoint_win_rate")) * 3.2
        + (number("team_control_win_rate") - number("opponent_control_win_rate")) * 2.6
        + (number("team_rotation_rating") - number("opponent_rotation_rating")) * 0.06
        + (number("team_hold_rating") - number("opponent_hold_rating")) * 0.05
        + (number("team_breaking_rating") - number("opponent_breaking_rating")) * 0.05
    )
    snd_edge = (
        (number("team_snd_rating") - number("opponent_snd_rating")) * 0.10
        + (number("team_search_destroy_win_rate") - number("opponent_search_destroy_win_rate")) * 4.0
        + (number("team_first_blood_rate") - number("opponent_first_blood_rate")) * 2.1
        + (number("team_clutch_rate") - number("opponent_clutch_rate")) * 1.8
    )
    slay_objective_edge = (
        (number("team_slaying_rating") - number("opponent_slaying_rating")) * 0.08
        + (number("team_objective_rating") - number("opponent_objective_rating")) * 0.065
        + (number("team_trade_rate") - number("opponent_trade_rate")) * 1.4
        + (number("team_kd_ratio") - number("opponent_kd_ratio")) * 3.2
        + (number("team_damage_per_round") - number("opponent_damage_per_round")) / 90.0
    )
    map_pool_edge = (
        (number("team_map_win_rate") - number("opponent_map_win_rate")) * 4.2
        + (number("team_map_pool_depth") - number("opponent_map_pool_depth")) * 0.14
        + (number("team_map_pick_rate") - number("opponent_map_pick_rate")) * 0.8
        - (number("team_map_ban_rate") - number("opponent_map_ban_rate")) * 0.5
    )
    mode_edge = respawn_edge
    if mode_key == "search_and_destroy":
        mode_edge = snd_edge
    elif mode_key == "control":
        mode_edge = (respawn_edge + (number("team_control_rating") - number("opponent_control_rating")) * 0.10) / 1.25
    elif mode_key == "mixed":
        mode_edge = respawn_edge * 0.55 + snd_edge * 0.30 + (number("team_control_rating") - number("opponent_control_rating")) * 0.08
    edge_score = (
        (number("team_elo") - number("opponent_elo")) / 42.0
        + (number("opponent_world_rank") - number("team_world_rank")) * 0.18
        + (number("team_recent_win_rate") - number("opponent_recent_win_rate")) * 5.0
        + map_pool_edge + mode_edge + slay_objective_edge
        + (number("recent_form") - number("opponent_recent_form")) * 0.045
        + number("roster_stability") * 0.85
        - number("substitute_risk") * 3.0
        - number("player_availability_risk") * 2.8
        - number("travel_fatigue") * 0.65
    )
    if not selected_team:
        edge_score = -edge_score
    volatility = 1.0 + (0.18 if format_key == "bo3" else -0.08 if format_key == "bo5" else 0)
    if environment == "online":
        volatility += 0.12
    if input_stats.get("elimination_match"):
        volatility += 0.08
    match_probability = _logistic_probability(edge_score, 6.2 + volatility)
    map_probability = _logistic_probability(edge_score * 0.72 + mode_edge * 0.55, 5.3 + volatility)
    hardpoint_probability = _logistic_probability(respawn_edge + slay_objective_edge * 0.35, 4.2 + volatility)
    snd_probability = _logistic_probability(snd_edge + edge_score * 0.20, 4.0 + volatility)
    control_probability = _logistic_probability(mode_edge + (number("team_control_rating") - number("opponent_control_rating")) * 0.08, 4.2 + volatility)
    first_blood_probability = _logistic_probability((number("team_first_blood_rate") - number("opponent_first_blood_rate")) * 5.0 + snd_edge * 0.2, 4.1 + volatility)
    projected_total_rounds = max(180.0, 210.0 + volatility * 6.0 + (1 - abs(match_probability - 0.5) * 2) * 20.0)
    projected_team_rounds = projected_total_rounds * _logistic_probability(edge_score + slay_objective_edge * 0.25, 6.1 + volatility)
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    total_line = _safe_float(payload.get("total_line"), _safe_float(input_stats.get("total_line")))
    raw_model_probability = match_probability
    if market_key in {"map_winner", "first_map_winner", "second_map_winner", "third_map_winner", "fourth_map_winner", "fifth_map_winner"}:
        raw_model_probability = map_probability
    elif market_key == "hardpoint_winner":
        raw_model_probability = hardpoint_probability
    elif market_key == "search_and_destroy_winner":
        raw_model_probability = snd_probability
    elif market_key == "control_winner":
        raw_model_probability = control_probability
    elif market_key == "first_blood":
        raw_model_probability = first_blood_probability
    elif market_key in {"map_handicap", "alt_map_handicap"}:
        raw_model_probability = _logistic_probability((match_probability - 0.5) * 8.0 - (line or 0), 3.0 + volatility)
    elif market_key == "round_handicap":
        raw_model_probability = _logistic_probability((projected_team_rounds - projected_total_rounds / 2) - (line or 0), 5.0 + volatility)
    elif market_key in {"total_maps", "alt_total_maps"}:
        projected_maps = 3.2 if format_key == "bo5" else 2.2
        projected_maps += (1 - abs(match_probability - 0.5) * 2) * 0.7
        raw_model_probability = _logistic_probability(projected_maps - (total_line if total_line is not None else projected_maps), 0.6 + volatility * 0.12)
    elif market_key == "total_rounds":
        raw_model_probability = _logistic_probability(projected_total_rounds - (total_line if total_line is not None else projected_total_rounds), 11.0 + volatility)
    elif market_key == "team_total_rounds":
        raw_model_probability = _logistic_probability(projected_team_rounds - (total_line if total_line is not None else projected_team_rounds), 7.5 + volatility)
    elif market_key == "correct_score":
        raw_model_probability = max(0.04, min(0.42, match_probability * (0.52 if format_key == "bo5" else 0.66)))
    elif market_key in COD_PROP_MARKETS:
        prop_map = {
            "player_kills": "player_kills_projection", "player_assists": "player_assists_projection",
            "player_deaths": "player_deaths_projection", "player_kda": "player_kda_projection",
            "player_damage": "player_damage_projection", "player_objective_time": "player_objective_time_projection",
            "player_first_bloods": "player_first_bloods_projection",
        }
        projection = number(prop_map[market_key])
        prop_line = number("player_prop_line", line or projection)
        raw_model_probability = _logistic_probability(projection - prop_line, max(0.9, abs(projection) * 0.18))
    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.04, min(0.88, calibrated_probability))
    sanity_flags = ["call of duty probability cap applied"] if true_probability != calibrated_probability else []
    confidence = 74.0
    risk_flags: list[str] = []
    if format_key == "bo3":
        confidence -= 3; risk_flags.append("BO3 series variance")
    if environment == "online":
        confidence -= 3; risk_flags.append("online server variance")
    if mode_key == "search_and_destroy":
        confidence -= 3; risk_flags.append("SND round volatility")
    if number("substitute_risk") >= 0.10 or number("player_availability_risk") >= 0.10:
        confidence -= 7; risk_flags.append("player availability risk")
    if number("roster_stability") < 0.75:
        confidence -= 5; risk_flags.append("roster instability")
    if market_key in COD_PROP_MARKETS:
        confidence -= 4; risk_flags.append("player prop fragility")
    if market_key in {"first_blood", "correct_score"}:
        confidence -= 5; risk_flags.append("volatile Call of Duty market")
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4; risk_flags.append("book count too low")
    if input_stats.get("provider_status") == "error":
        risk_flags.append("provider failure ignored")
    confidence = max(1, min(95, round(confidence, 2)))
    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(bankroll=bankroll, american_odds=odds_american, true_probability=true_probability, risk_profile=risk_profile, confidence=confidence)
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)
    return {
        "model_status": "active", "estimated_true_probability": true_probability, "true_probability": true_probability,
        "final_probability": true_probability, "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate", "suggested_stake": suggested,
        "raw_model_probability": raw_model_probability, "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags), "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "call of duty sanity cap" if sanity_flags else None, "market_anchor_probability": market_anchor,
        "league_calibration_applied": "call_of_duty", "match_format_calibration_applied": format_key,
        "mode_calibration_applied": mode_key, "event_environment_calibration_applied": environment,
        "map_calibration_applied": map_key,
        "cod_team_edge_score": round(edge_score, 2), "cod_match_probability": match_probability,
        "cod_map_probability": map_probability, "cod_hardpoint_probability": hardpoint_probability,
        "cod_snd_probability": snd_probability, "cod_control_probability": control_probability,
        "cod_projected_total_rounds": round(projected_total_rounds, 2),
        "cod_projected_team_rounds": round(projected_team_rounds, 2),
        "risk_flags": risk_flags,
        "input_coverage": {"required_core_present": list(COD_REQUIRED_CORE_INPUTS), "required_market_specific_present": COD_REQUIRED_MARKET_INPUTS.get(market_key, []), "optional_enrichment_present": [f for f in COD_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None], "optional_enrichment_missing": [f for f in COD_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is None]},
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [f for f in COD_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _overwatch_mode_calibration(raw_mode: Any) -> str:
    text = str(raw_mode or "").strip().lower().replace(" ", "_")
    mapping = {"control": "control", "escort": "escort", "hybrid": "hybrid", "push": "push", "flashpoint": "flashpoint", "clash": "clash", "mixed": "mixed"}
    return mapping.get(text, "unknown")


def _estimate_overwatch_hero_objective_model(
    *, input_stats: dict[str, Any], payload: dict[str, Any], market: Any,
    odds_american: Optional[float], bankroll: float, risk_profile: str,
) -> Optional[dict[str, Any]]:
    missing = _overwatch_full_inputs_missing(input_stats, payload) + _overwatch_market_specific_missing(market, input_stats, payload)
    if missing:
        return None
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    if implied_probability is None:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    selection_text = str(payload.get("selection") or input_stats.get("selection") or "").strip().lower()
    selected_team = not input_stats.get("opponent") or str(input_stats.get("team") or "").strip().lower() in selection_text
    format_key = _cs2_match_format_calibration(input_stats.get("match_format"), input_stats.get("best_of_maps"))
    mode_key = _overwatch_mode_calibration(input_stats.get("game_mode"))
    environment = "lan" if input_stats.get("lan_event") else "online" if input_stats.get("online_event") else "unknown"
    map_key = str(input_stats.get("map_name") or "unknown").strip() or "unknown"
    patch_key = str(input_stats.get("patch_version") or "unknown").strip() or "unknown"
    comp_applied = all(input_stats.get(f) is not None for f in ("team_composition_rating", "opponent_composition_rating", "team_meta_fit_rating", "opponent_meta_fit_rating"))
    mode_rates = {
        "control": ("team_control_win_rate", "opponent_control_win_rate"),
        "escort": ("team_escort_win_rate", "opponent_escort_win_rate"),
        "hybrid": ("team_hybrid_win_rate", "opponent_hybrid_win_rate"),
        "push": ("team_push_win_rate", "opponent_push_win_rate"),
        "flashpoint": ("team_flashpoint_win_rate", "opponent_flashpoint_win_rate"),
        "clash": ("team_clash_win_rate", "opponent_clash_win_rate"),
    }
    team_mode, opp_mode = mode_rates.get(mode_key, ("team_map_win_rate", "opponent_map_win_rate"))
    role_edge = ((number("team_tank_rating") - number("opponent_tank_rating")) * 1.0 + (number("team_dps_rating") - number("opponent_dps_rating")) * 1.15 + (number("team_support_rating") - number("opponent_support_rating")) * 0.95) / 3.0
    objective_edge = (
        (number("team_objective_control_rating") - number("opponent_objective_control_rating")) * 0.08
        + (number("team_ultimate_economy_rating") - number("opponent_ultimate_economy_rating")) * 0.065
        + (number("team_ultimate_conversion_rate") - number("opponent_ultimate_conversion_rate")) * 3.0
        + (number("team_stagger_avoidance_rating") - number("opponent_stagger_avoidance_rating")) * 0.04
    )
    fight_edge = (
        (number("team_fight_win_rate") - number("opponent_fight_win_rate")) * 5.2
        + (number("team_first_fight_win_rate") - number("opponent_first_fight_win_rate")) * 1.8
        + (number("team_eliminations_per_10") - number("opponent_eliminations_per_10")) * 0.16
        - (number("team_deaths_per_10") - number("opponent_deaths_per_10")) * 0.14
        + (number("team_final_blow_rate") - number("opponent_final_blow_rate")) * 1.8
        + (number("team_damage_per_10") - number("opponent_damage_per_10")) / 1000.0
        + (number("team_healing_per_10") - number("opponent_healing_per_10")) / 1400.0
    )
    comp_edge = (number("team_composition_rating") - number("opponent_composition_rating")) * 0.08 + (number("team_meta_fit_rating") - number("opponent_meta_fit_rating")) * 0.07 + role_edge * 0.08
    map_edge = (number("team_map_win_rate") - number("opponent_map_win_rate")) * 4.0 + (number(team_mode) - number(opp_mode)) * 3.4 + (number("team_map_pool_depth") - number("opponent_map_pool_depth")) * 0.12
    edge_score = (
        (number("team_elo") - number("opponent_elo")) / 42.0
        + (number("opponent_world_rank") - number("team_world_rank")) * 0.18
        + (number("team_recent_win_rate") - number("opponent_recent_win_rate")) * 5.0
        + map_edge + objective_edge + fight_edge + comp_edge
        + (number("recent_form") - number("opponent_recent_form")) * 0.04
        + number("roster_stability") * 0.85
        - number("substitute_risk") * 3.0 - number("player_availability_risk") * 2.8 - number("travel_fatigue") * 0.65
    )
    if not selected_team:
        edge_score = -edge_score
    volatility = 1.0 + (0.2 if format_key == "bo3" else -0.1 if format_key in {"bo5", "bo7"} else 0)
    if environment == "online":
        volatility += 0.12
    match_probability = _logistic_probability(edge_score, 6.3 + volatility)
    map_probability = _logistic_probability(edge_score * 0.72 + map_edge * 0.5 + objective_edge * 0.3, 5.3 + volatility)
    objective_probability = _logistic_probability(objective_edge + fight_edge * 0.25, 4.2 + volatility)
    projected_maps = 3.2 if format_key == "bo5" else 4.1 if format_key == "bo7" else 2.2
    projected_maps += (1 - abs(match_probability - 0.5) * 2) * 0.7
    line = _safe_float(payload.get("line"), _safe_float(input_stats.get("line")))
    total_line = _safe_float(payload.get("total_line"), _safe_float(input_stats.get("total_line")))
    raw_model_probability = match_probability
    if market_key in {"map_winner", "first_map_winner", "second_map_winner", "third_map_winner", "fourth_map_winner", "fifth_map_winner"}:
        raw_model_probability = map_probability
    elif market_key in {"control_map_winner", "escort_map_winner", "hybrid_map_winner", "push_map_winner", "flashpoint_map_winner", "clash_map_winner"}:
        raw_model_probability = _logistic_probability(edge_score * 0.4 + objective_edge + map_edge * 0.5, 4.7 + volatility)
    elif market_key in {"map_handicap", "alt_map_handicap"}:
        raw_model_probability = _logistic_probability((match_probability - 0.5) * 8.0 - (line or 0), 3.0 + volatility)
    elif market_key == "objective_handicap":
        raw_model_probability = _logistic_probability(objective_edge - (line or 0), 3.8 + volatility)
    elif market_key in {"total_maps", "alt_total_maps", "team_total_maps"}:
        raw_model_probability = _logistic_probability(projected_maps - (total_line if total_line is not None else projected_maps), 0.6 + volatility * 0.12)
    elif market_key == "correct_score":
        raw_model_probability = max(0.04, min(0.42, match_probability * (0.52 if format_key in {"bo5", "bo7"} else 0.66)))
    elif market_key in OVERWATCH_PROP_MARKETS:
        prop_map = {
            "player_eliminations": "player_eliminations_projection", "player_final_blows": "player_final_blows_projection",
            "player_assists": "player_assists_projection", "player_deaths": "player_deaths_projection",
            "player_damage": "player_damage_projection", "player_healing": "player_healing_projection",
            "player_mitigation": "player_mitigation_projection", "player_kda": "player_kda_projection",
        }
        projection = number(prop_map[market_key])
        prop_line = number("player_prop_line", line or projection)
        raw_model_probability = _logistic_probability(projection - prop_line, max(0.9, abs(projection) * 0.18))
    market_anchor = _safe_probability(input_stats.get("no_vig_market_probability"))
    calibrated_probability = raw_model_probability * 0.90 + market_anchor * 0.10 if market_anchor is not None else raw_model_probability
    true_probability = max(0.04, min(0.88, calibrated_probability))
    sanity_flags = ["overwatch probability cap applied"] if true_probability != calibrated_probability else []
    confidence = 74.0
    risk_flags: list[str] = []
    if format_key == "bo3":
        confidence -= 3; risk_flags.append("BO3 series variance")
    if environment == "online":
        confidence -= 3; risk_flags.append("online server variance")
    if not comp_applied:
        confidence -= 5; risk_flags.append("hero composition uncertainty")
    if number("substitute_risk") >= 0.10 or number("player_availability_risk") >= 0.10:
        confidence -= 7; risk_flags.append("player availability risk")
    if number("roster_stability") < 0.75:
        confidence -= 5; risk_flags.append("roster instability")
    if market_key in OVERWATCH_PROP_MARKETS:
        confidence -= 4; risk_flags.append("player prop fragility")
    if _safe_float(input_stats.get("book_count"), 0) < 4:
        confidence -= 4; risk_flags.append("book count too low")
    confidence = max(1, min(95, round(confidence, 2)))
    edge = calculate_edge_percent(true_probability, implied_probability)
    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
    suggested = 0 if no_bet_flags else calculate_suggested_stake(bankroll=bankroll, american_odds=odds_american, true_probability=true_probability, risk_profile=risk_profile, confidence=confidence)
    if suggested <= 0 and not no_bet_flags and edge is not None and edge >= edge_threshold and confidence >= confidence_threshold:
        suggested = round(max(1.0, bankroll * 0.004), 2)
    return {
        "model_status": "active", "estimated_true_probability": true_probability, "true_probability": true_probability,
        "final_probability": true_probability, "model_probability": true_probability, "implied_probability": implied_probability,
        "edge": edge, "confidence": confidence, "risk": "high" if risk_flags else "moderate", "suggested_stake": suggested,
        "raw_model_probability": raw_model_probability, "calibrated_model_probability": calibrated_probability,
        "probability_calibration_applied": bool(market_anchor is not None or sanity_flags), "probability_sanity_flags": sanity_flags,
        "probability_cap_reason": "overwatch sanity cap" if sanity_flags else None, "market_anchor_probability": market_anchor,
        "league_calibration_applied": "overwatch", "match_format_calibration_applied": format_key,
        "mode_calibration_applied": mode_key, "event_environment_calibration_applied": environment,
        "patch_calibration_applied": patch_key, "hero_composition_calibration_applied": comp_applied,
        "map_calibration_applied": map_key, "overwatch_team_edge_score": round(edge_score, 2),
        "overwatch_match_probability": match_probability, "overwatch_map_probability": map_probability,
        "overwatch_objective_probability": objective_probability, "overwatch_projected_maps": round(projected_maps, 2),
        "risk_flags": risk_flags,
        "input_coverage": {"required_core_present": list(OVERWATCH_REQUIRED_CORE_INPUTS), "required_market_specific_present": OVERWATCH_REQUIRED_MARKET_INPUTS.get(market_key, []), "optional_enrichment_present": [f for f in OVERWATCH_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None], "optional_enrichment_missing": [f for f in OVERWATCH_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is None]},
        "provider_enrichment": {"provider_status": input_stats.get("provider_status") or "not_provided", "provider_enrichment_present": [f for f in OVERWATCH_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(f) is not None]},
        "no_bet_flags": no_bet_flags,
    }


def _estimate_nfl_drive_model(
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    core_missing = _nfl_full_inputs_missing(input_stats)
    market_missing = _nfl_market_specific_missing(market, input_stats, payload)
    if core_missing or market_missing:
        return None

    def number(key: str, default: float = 0) -> float:
        return _safe_float(input_stats.get(key), default) or default

    optional_present = [field for field in NFL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    provider_present = [field for field in NFL_PROVIDER_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    officiating_present = _official_inputs_present(input_stats, NFL_OFFICIATING_INPUTS)
    social_present = [field for field in NFL_SOCIAL_CROWD_INPUTS if input_stats.get(field) is not None]
    live_present = [field for field in NFL_LIVE_BETTING_INPUTS if input_stats.get(field) is not None]

    team_drive = (
        (number("team_offensive_epa_per_play") - number("opponent_defensive_epa_per_play")) * 18
        + (number("team_success_rate") - number("opponent_defensive_success_rate_allowed")) * 14
        + (number("team_explosive_play_rate") - number("opponent_explosive_play_rate_allowed")) * 16
        + (number("team_pressure_rate_allowed") - number("opponent_pressure_rate_generated")) * -8
        + (number("team_red_zone_td_rate") - number("opponent_red_zone_td_rate_allowed")) * 8
        + (number("opponent_turnover_rate") - number("team_turnover_rate")) * 10
    )
    opponent_drive = (
        (number("opponent_offensive_epa_per_play") - number("team_defensive_epa_per_play")) * 18
        + (number("opponent_success_rate") - number("team_defensive_success_rate_allowed")) * 14
        + (number("opponent_explosive_play_rate") - number("team_explosive_play_rate_allowed")) * 16
        + (number("opponent_pressure_rate_allowed") - number("team_pressure_rate_generated")) * -8
        + (number("opponent_red_zone_td_rate") - number("team_red_zone_td_rate_allowed")) * 8
        + (number("team_turnover_rate") - number("opponent_turnover_rate")) * 10
    )
    pace = max(24.0, min(34.0, (number("team_pace_seconds_per_play", 28) + number("opponent_pace_seconds_per_play", 28)) / 2))
    pace_boost = (28.5 - pace) * 0.35
    home_away = str(input_stats.get("home_away") or "").strip().lower()
    home_adjustment = 1.4 if home_away == "home" else -1.0 if home_away == "away" else 0
    projected_margin = (team_drive - opponent_drive) + home_adjustment
    projected_total = 44 + ((team_drive + opponent_drive) * 0.9) + pace_boost

    if input_stats.get("team_recent_epa_per_play_3") is not None and input_stats.get("opponent_recent_epa_per_play_3") is not None:
        projected_margin += (number("team_recent_epa_per_play_3") - number("opponent_recent_epa_per_play_3")) * 6
    if input_stats.get("team_special_teams_epa") is not None and input_stats.get("opponent_special_teams_epa") is not None:
        projected_margin += (number("team_special_teams_epa") - number("opponent_special_teams_epa")) * 4
    rest_edge = number("team_rest_days", 0) - number("opponent_rest_days", 0)
    projected_margin += max(-1.0, min(1.0, rest_edge * 0.2))
    travel_edge = (number("opponent_travel_distance_miles", 0) - number("team_travel_distance_miles", 0)) / 1000
    projected_margin += max(-0.8, min(0.8, travel_edge * 0.2))
    if input_stats.get("team_short_week") is True:
        projected_margin -= 0.8
    if input_stats.get("opponent_short_week") is True:
        projected_margin += 0.8

    qb_status = str(input_stats.get("qb_status") or "").strip().lower()
    offensive_line_health = str(input_stats.get("offensive_line_health") or "").strip().lower()
    injury_status = str(input_stats.get("injury_report_status") or "").strip().lower()
    if qb_status in {"out", "backup", "doubtful"}:
        projected_margin -= 3.5
        projected_total -= 2.5
    elif qb_status in {"questionable", "uncertain", "limited"}:
        projected_margin -= 1.4
        projected_total -= 1.0
    if offensive_line_health in {"poor", "bad", "thin", "injured"}:
        projected_margin -= 1.2
        projected_total -= 1.0
    if injury_status not in {"clean", "clear", "healthy", "normal", "available"}:
        projected_margin -= 0.8
        projected_total -= 0.6

    wind = number("weather_wind_mph", 0)
    if wind >= 15 and not input_stats.get("dome_game"):
        projected_total -= min(5.0, (wind - 12) * 0.35)
    if _truthy_available(input_stats.get("weather_precipitation")) and not input_stats.get("dome_game"):
        projected_total -= 1.5
    projected_total = max(28.0, min(64.0, projected_total))
    projected_team_points = (projected_total / 2) + (projected_margin / 2)
    projected_opponent_points = projected_total - projected_team_points
    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    if market_key in {"spread", "first_half_spread", "first_quarter_spread"}:
        line = _safe_float(input_stats.get("line") if input_stats.get("line") is not None else payload.get("line"), 0) or 0
        period_scale = 0.50 if market_key == "first_half_spread" else 0.24 if market_key == "first_quarter_spread" else 1.0
        raw_model_probability = _logistic_probability((projected_margin * period_scale) + line, 9.5 * max(0.45, period_scale))
    elif market_key in {"total", "first_half_total", "first_quarter_total"}:
        total_line = _safe_float(input_stats.get("total_line") if input_stats.get("total_line") is not None else payload.get("total_line"), 0) or 0
        period_scale = 0.50 if market_key == "first_half_total" else 0.24 if market_key == "first_quarter_total" else 1.0
        over_probability = _logistic_probability((projected_total * period_scale) - total_line, 8.5 * max(0.45, period_scale))
        selection = str(payload.get("selection") or input_stats.get("selection") or "").lower()
        raw_model_probability = 1 - over_probability if "under" in selection else over_probability
    elif market_key == "team_total":
        team_total_line = _safe_float(input_stats.get("team_total_line") if input_stats.get("team_total_line") is not None else payload.get("team_total_line"), 0) or 0
        over_probability = _logistic_probability(projected_team_points - team_total_line, 6.0)
        selection = str(payload.get("selection") or input_stats.get("selection") or "").lower()
        raw_model_probability = 1 - over_probability if "under" in selection else over_probability
    elif market_key == "player_prop":
        projection = number("player_projection")
        prop_line = number("prop_line")
        raw_model_probability = _logistic_probability(projection - prop_line, max(1.0, abs(prop_line) * 0.18))
    elif market_key == "first_half":
        raw_model_probability = _logistic_probability(projected_margin * 0.50, 6.0)
    elif market_key == "first_quarter":
        raw_model_probability = _logistic_probability(projected_margin * 0.24, 4.5)
    else:
        raw_model_probability = _logistic_probability(projected_margin, 8.0)

    market_probability = _safe_probability(input_stats.get("no_vig_market_probability"))
    confidence = 68
    confidence += min(8, len(optional_present) * 0.18)
    confidence += min(4, len(provider_present) * 0.5)
    if qb_status in {"out", "questionable", "uncertain", "limited", "backup", "doubtful"}:
        confidence -= 10 if qb_status == "out" else 6
    if offensive_line_health in {"poor", "bad", "thin", "injured"}:
        confidence -= 6
    if injury_status not in {"clean", "clear", "healthy", "normal", "available"}:
        confidence -= 5
    if wind >= 15:
        confidence -= 5 if market_key in {"total", "player_prop"} else 2
    book_count = _safe_float(input_stats.get("book_count"))
    if book_count is not None and book_count < 5:
        confidence -= 4
    if input_stats.get("best_available_odds") is None:
        confidence -= 3
    current_odds = _safe_float(input_stats.get("current_odds"))
    consensus_odds = _safe_float(input_stats.get("consensus_odds"))
    risk = "medium"
    if current_odds is not None and consensus_odds is not None and abs(current_odds - consensus_odds) >= 25:
        risk = "high"
        confidence -= 3
    if officiating_present:
        confidence += min(2, len(officiating_present) * 0.5)
    if social_present:
        confidence += min(2, len(social_present) * 0.2)
    if live_present and input_stats.get("live_game") is True:
        confidence += 3 if len(live_present) >= 5 else -8
    confidence = max(1, min(95, round(confidence, 2)))

    market_anchor_probability = market_probability if market_probability is not None else implied_probability if implied_probability is not None else 0.5
    if market_key == "moneyline":
        calibration = _calibrate_nfl_probability(
            raw_probability=raw_model_probability,
            market_anchor_probability=market_anchor_probability,
            market_anchor_is_no_vig=market_probability is not None,
            projected_margin=projected_margin,
            input_confidence_hint=confidence,
        )
        true_probability = calibration["final_probability"]
    else:
        calibrated_probability = (raw_model_probability * 0.85) + (market_anchor_probability * 0.15)
        true_probability = max(0.03, min(0.97, calibrated_probability))
        calibration = {
            "raw_model_probability": raw_model_probability,
            "calibrated_model_probability": calibrated_probability,
            "final_probability": true_probability,
            "market_anchor_probability": market_anchor_probability,
            "probability_calibration_applied": abs(calibrated_probability - raw_model_probability) >= 0.025,
            "probability_sanity_flags": ["probability calibration applied"] if abs(calibrated_probability - raw_model_probability) >= 0.025 else [],
            "probability_cap_reason": None,
        }
    if calibration["probability_sanity_flags"]:
        confidence = max(1, round(confidence - min(8, 2 * len(calibration["probability_sanity_flags"])), 2))
        if "probability calibration applied" not in calibration["probability_sanity_flags"]:
            calibration["probability_sanity_flags"].append("probability calibration applied")

    edge = edge_percentage(true_probability, implied_probability) if implied_probability is not None else None

    edge_threshold, confidence_threshold = _nfl_thresholds(risk_profile)
    no_bet_flags: list[str] = []
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
        risk = "high"
    elif edge < edge_threshold:
        no_bet_flags.append("edge too small")
    if confidence < confidence_threshold:
        no_bet_flags.append("low confidence")
        risk = "high"
    if odds_american is None:
        no_bet_flags.append("odds missing")
    if current_odds is not None and consensus_odds is not None and abs(current_odds - consensus_odds) >= 35:
        no_bet_flags.append("market disagreement too high")

    suggested = 0.0
    if not no_bet_flags and odds_american is not None:
        suggested = suggested_stake_with_risk_controls(
            bankroll=bankroll,
            american_odds=odds_american,
            true_probability=true_probability,
            risk_profile="standard" if str(risk_profile or "").lower() == "moderate" else risk_profile,
            confidence_0_100=confidence,
        )
        risk = "low" if edge is not None and edge >= 5 else risk

    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "final_probability": true_probability,
        "model_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": risk,
        "suggested_stake": suggested,
        "raw_model_probability": calibration["raw_model_probability"],
        "calibrated_model_probability": calibration["calibrated_model_probability"],
        "probability_calibration_applied": calibration["probability_calibration_applied"],
        "probability_sanity_flags": calibration["probability_sanity_flags"],
        "probability_cap_reason": calibration["probability_cap_reason"],
        "market_anchor_probability": calibration["market_anchor_probability"],
        "projected_margin": round(projected_margin, 2),
        "projected_total": round(projected_total, 2),
        "projected_team_points": round(projected_team_points, 2),
        "projected_opponent_points": round(projected_opponent_points, 2),
        "nfl_input_contract": deepcopy(NFL_INPUT_CONTRACT),
        "input_coverage": {
            "required_core_present": list(NFL_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": NFL_REQUIRED_MARKET_SPECIFIC_INPUTS.get(market_key, []),
            "optional_enrichment_present": optional_present,
            "optional_enrichment_missing": [field for field in NFL_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
            "provider_enrichment_present": provider_present,
            "officiating_present": officiating_present,
            "referee_present": officiating_present,
            "social_crowd_present": social_present,
            "live_betting_present": live_present,
        },
        "provider_enrichment": {
            "provider_enrichment_present": provider_present,
            "provider_status": "available" if provider_present else "not_provided",
        },
        "no_bet_flags": no_bet_flags,
    }


def _estimate_nba_possession_model(
    input_stats: dict[str, Any],
    payload: dict[str, Any],
    market: Any,
    odds_american: Optional[float],
    bankroll: float,
    risk_profile: str,
) -> Optional[dict[str, Any]]:
    core_missing = _nba_full_inputs_missing(input_stats)
    market_missing = _nba_market_specific_missing(market, input_stats, payload)
    if core_missing or market_missing:
        return None

    team_pace = _safe_float(input_stats.get("team_pace"), 0) or 0
    opponent_pace = _safe_float(input_stats.get("opponent_pace"), 0) or 0
    team_off = _safe_float(input_stats.get("team_offensive_rating"), 0) or 0
    opponent_off = _safe_float(input_stats.get("opponent_offensive_rating"), 0) or 0
    team_def = _safe_float(input_stats.get("team_defensive_rating"), 0) or 0
    opponent_def = _safe_float(input_stats.get("opponent_defensive_rating"), 0) or 0

    team_efg = _safe_probability(input_stats.get("team_efg_percent")) or 0.5
    opponent_efg = _safe_probability(input_stats.get("opponent_efg_percent")) or 0.5
    team_tov = _safe_probability(input_stats.get("team_turnover_percent")) or 0.13
    opponent_tov = _safe_probability(input_stats.get("opponent_turnover_percent")) or 0.13
    team_oreb = _safe_probability(input_stats.get("team_offensive_rebound_percent")) or 0.25
    opponent_oreb = _safe_probability(input_stats.get("opponent_offensive_rebound_percent")) or 0.25
    team_ftr = _safe_probability(input_stats.get("team_free_throw_rate")) or 0.22
    opponent_ftr = _safe_probability(input_stats.get("opponent_free_throw_rate")) or 0.22

    pace = (team_pace + opponent_pace) / 2
    team_expected_per_100 = (team_off * 0.55) + (opponent_def * 0.45)
    opponent_expected_per_100 = (opponent_off * 0.55) + (team_def * 0.45)
    four_factor_margin = (
        ((team_efg - opponent_efg) * 40)
        + ((opponent_tov - team_tov) * 18)
        + ((team_oreb - opponent_oreb) * 12)
        + ((team_ftr - opponent_ftr) * 8)
    )
    home_away = str(input_stats.get("home_away") or "").strip().lower()
    home_adjustment = 1.8 if home_away == "home" else -1.0 if home_away == "away" else 0.0
    usage_adjustment = 0.8 if _truthy_available(input_stats.get("key_player_usage_available")) else -1.5
    minutes_adjustment = 0.6 if _truthy_available(input_stats.get("minutes_projection_available")) else -1.5
    injury_status = str(input_stats.get("injury_report_status") or "").strip().lower()
    injury_adjustment = 0.6 if injury_status in {"clean", "clear", "available", "normal", "healthy"} else -1.2

    optional_present = [field for field in NBA_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    provider_present = [field for field in NBA_PROVIDER_ENRICHMENT_INPUTS if input_stats.get(field) is not None]
    referee_present = [field for field in NBA_REFEREE_INPUTS if input_stats.get(field) is not None]
    social_present = [field for field in NBA_SOCIAL_CROWD_INPUTS if input_stats.get(field) is not None]
    live_present = [field for field in NBA_LIVE_BETTING_INPUTS if input_stats.get(field) is not None]

    raw_margin_per_100 = team_expected_per_100 - opponent_expected_per_100
    estimated_margin = (raw_margin_per_100 * (pace / 100)) + four_factor_margin + home_adjustment + usage_adjustment + minutes_adjustment + injury_adjustment
    projected_margin = _safe_float(input_stats.get("projected_margin"))
    if projected_margin is not None:
        estimated_margin = (estimated_margin * 0.7) + (projected_margin * 0.3)
    recent_margin = None
    team_recent_5 = _safe_float(input_stats.get("team_recent_net_rating_5"))
    opponent_recent_5 = _safe_float(input_stats.get("opponent_recent_net_rating_5"))
    if team_recent_5 is not None and opponent_recent_5 is not None:
        recent_margin = (team_recent_5 - opponent_recent_5) * 0.08
        estimated_margin += recent_margin
    rest_edge = (_safe_float(input_stats.get("team_rest_days"), 0) or 0) - (_safe_float(input_stats.get("opponent_rest_days"), 0) or 0)
    estimated_margin += max(-1.0, min(1.0, rest_edge * 0.25))
    if input_stats.get("team_back_to_back") is True:
        estimated_margin -= 0.7
    if input_stats.get("opponent_back_to_back") is True:
        estimated_margin += 0.7
    travel_edge = ((_safe_float(input_stats.get("opponent_travel_distance_miles"), 0) or 0) - (_safe_float(input_stats.get("team_travel_distance_miles"), 0) or 0)) / 1000
    estimated_margin += max(-0.8, min(0.8, travel_edge * 0.25))
    ref_quality = str(input_stats.get("referee_data_quality") or "").strip().lower()
    if ref_quality in {"strong", "high"}:
        estimated_margin += max(-0.5, min(0.5, (_safe_float(input_stats.get("home_foul_differential"), 0) or 0) * 0.15))
    projected_total = _safe_float(input_stats.get("projected_total"))
    if projected_total is None:
        projected_total = ((team_expected_per_100 + opponent_expected_per_100) * pace / 100)
    projected_team_score = (projected_total / 2) + (estimated_margin / 2)
    projected_opponent_score = projected_total - projected_team_score

    market_key = _normal_market_key(input_stats.get("market_type") or market)
    if market_key in {"spread", "first_quarter_spread"}:
        line = _safe_float(input_stats.get("line") if input_stats.get("line") is not None else payload.get("line"), 0) or 0
        true_probability = _logistic_probability(estimated_margin + line, 12.0)
    elif market_key in {"total", "first_quarter_total"}:
        total_line = _safe_float(input_stats.get("total_line") if input_stats.get("total_line") is not None else payload.get("total_line"), 0) or 0
        scaled_total = projected_total * (0.24 if market_key == "first_quarter_total" else 1.0)
        over_probability = _logistic_probability(scaled_total - total_line, 15.0 if market_key == "total" else 5.0)
        true_probability = 1 - over_probability if "under" in str(payload.get("selection") or input_stats.get("selection") or "").lower() else over_probability
    elif market_key == "team_total":
        team_total_line = _safe_float(input_stats.get("team_total_line") if input_stats.get("team_total_line") is not None else payload.get("team_total_line"), 0) or 0
        over_probability = _logistic_probability(projected_team_score - team_total_line, 8.0)
        true_probability = 1 - over_probability if "under" in str(payload.get("selection") or input_stats.get("selection") or "").lower() else over_probability
    elif market_key == "first_half":
        true_probability = _logistic_probability(estimated_margin * 0.49, 7.5)
    elif market_key in {"first_quarter", "first_quarter_moneyline"}:
        true_probability = _logistic_probability(estimated_margin * 0.24, 5.5)
    elif market_key == "player_prop":
        projection = _safe_float(input_stats.get("player_projection"), 0) or 0
        prop_line = _safe_float(input_stats.get("prop_line"), 0) or 0
        true_probability = _logistic_probability(projection - prop_line, max(1.0, abs(prop_line) * 0.18))
    else:
        true_probability = 1 / (1 + 2.718281828 ** (-(estimated_margin / 11.0)))
    true_probability = max(0.03, min(0.97, true_probability))

    implied_probability = implied_probability_from_american(odds_american) if odds_american is not None else None
    edge = edge_percentage(true_probability, implied_probability) if implied_probability is not None else None
    confidence = 72
    if injury_status in {"clean", "clear", "available", "normal", "healthy"}:
        confidence += 6
    else:
        confidence -= 8
    if _truthy_available(input_stats.get("key_player_usage_available")):
        confidence += 5
    else:
        confidence -= 6
    if _truthy_available(input_stats.get("minutes_projection_available")):
        confidence += 5
    else:
        confidence -= 6
    if abs(estimated_margin) < 1.5:
        confidence -= 8
    confidence += min(10, len(optional_present) * 0.35)
    confidence += min(4, len(provider_present) * 0.5)
    if ref_quality in {"strong", "high"} and (_safe_float(input_stats.get("referee_sample_size"), 0) or 0) >= 30:
        confidence += 4
    if social_present:
        confidence += min(3, len(social_present) * 0.25)
    if str(input_stats.get("rumor_risk") or "").strip().lower() not in {"", "none", "low"}:
        confidence -= 8
    if input_stats.get("live_game") is True:
        confidence += 4 if len(live_present) >= 5 else -10
    if market_key == "player_prop":
        if input_stats.get("player_minutes_projection") is None:
            confidence -= 10
        if not _truthy_available(input_stats.get("minutes_projection_available")):
            confidence -= 6
    confidence = max(1, min(95, confidence))

    no_bet_flags: list[str] = []
    suggested = 0.0
    risk = "standard"
    if edge is None:
        no_bet_flags.append("edge missing")
    elif edge <= 0:
        no_bet_flags.append("negative edge")
        risk = "high"
    elif edge < 2.5:
        no_bet_flags.append("edge too small")
        risk = "medium"
    if confidence < 70:
        no_bet_flags.append("low confidence")
        risk = "high"
    if odds_american is None:
        no_bet_flags.append("odds missing")
    if not no_bet_flags and odds_american is not None:
        suggested = suggested_stake_with_risk_controls(
            bankroll=bankroll,
            american_odds=odds_american,
            true_probability=true_probability,
            risk_profile=risk_profile,
            confidence_0_100=confidence,
        )
        risk = "low" if edge is not None and edge >= 5 else "medium"

    return {
        "model_status": "active",
        "estimated_true_probability": true_probability,
        "true_probability": true_probability,
        "implied_probability": implied_probability,
        "edge": edge,
        "confidence": confidence,
        "risk": risk,
        "suggested_stake": suggested,
        "nba_input_contract": deepcopy(NBA_INPUT_CONTRACT),
        "input_coverage": {
            "required_core_present": list(NBA_REQUIRED_CORE_INPUTS),
            "required_market_specific_present": NBA_REQUIRED_MARKET_SPECIFIC_INPUTS.get(_normal_market_key(input_stats.get("market_type") or market), []),
            "optional_enrichment_present": optional_present,
            "optional_enrichment_missing": [field for field in NBA_OPTIONAL_ENRICHMENT_INPUTS if input_stats.get(field) is None],
            "provider_enrichment_present": provider_present,
            "referee_present": referee_present,
            "social_crowd_present": social_present,
            "live_betting_present": live_present,
        },
        "projected_score": {
            "team": round(projected_team_score, 2),
            "opponent": round(projected_opponent_score, 2),
            "estimated_margin": round(estimated_margin, 2),
        },
        "no_bet_flags": no_bet_flags,
    }


